INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：棚里的环境要注意，工资与蘑菇种植无关。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是人的特征，不是棚里需要注意的对象。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“注意棚里的”后不接学费，语境也不相合。"}, {"text": "温湿度", "is_correct": true, "explanation": "正确：养蘑菇要注意棚里的温湿度，符合语境。"}], "explanations": {"工资": "语义：棚里的环境要注意，工资与蘑菇种植无关。", "血型": "语义：血型是人的特征，不是棚里需要注意的对象。", "学费": "搭配：“注意棚里的”后不接学费，语境也不相合。", "温湿度": "正确：养蘑菇要注意棚里的温湿度，符合语境。"}, "sentence_index": 6, "correct_answer": "温湿度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里的温湿度是二十五度，很舒服。", "explanation": "这里应该用〈室温〉。温湿度是合称，不单指室内温度。"}, {"text": "墙上的温湿度坏了，没法读数。", "explanation": "这里应该用〈温度计〉。温湿度是数值或状况，不是仪器名。"}, {"text": "山上的温湿度很新鲜，我们出去走走吧。", "explanation": "这里应该用〈空气〉。温湿度是温度与湿度的合称，不能用来形容“新鲜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仓库里要装一个温湿度。", "corrected_sentence": "仓库里要装一个温湿度计。", "error_description": "应为“温湿度计”。“温湿度”是温度与湿度的合称，表示数值或状况，不是仪器，装的仪器要说“温湿度计”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台仪器能测出仓库的一个温湿度。", "corrected_sentence": "这台仪器能测出仓库的温湿度。", "error_description": "多余量词：温湿度是抽象的量，不能用“一个”计量，应直接说“温湿度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
