INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13107, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物中起决定作用的关键因素或核心内容。", "primary_collocate": null, "pronunciation": "sān yào sù", "ipa": "san˥ jɑʊ˥˩ su˥˩", "syllable_count": 3, "sentences": [{"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "三要素", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "写故事要先想好故事的三要素。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，种花的三要素是水、光和土。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "声音的三要素是音调、响度和音色。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的计划要有目标、方法和时间这三要素。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做面包的三要素是面粉、水和时间。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得学语言的三要素是听、说和练。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者写新闻时，要先找到新闻的三要素。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店成功的三要素是位置、服务和价格。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上写着力的三要素。", "target_word": "三要素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "构成或决定某事物的三个关键要素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d26fe1-76de-4d72-b2de-845fecb9db9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三要素", "is_correct": true, "explanation": "“三要素”指起决定作用的关键因素。前文的湿度、翻堆频率和温度正是三项并列的控制因素，可以放入空缺。"}, {"text": "三阶段", "is_correct": false, "explanation": "语义：前文的湿度、翻堆频率和温度是同时需要控制的并列因素，不是先后进行的阶段。"}, {"text": "三大件", "is_correct": false, "explanation": "搭配：“协同”多用于因素、系统，“三大件”指具体的成套物品，不能说“维持三大件协同”。"}, {"text": "三部曲", "is_correct": false, "explanation": "语义：“三部曲”指成套的三部作品，与控制湿度、温度的操作无关。"}], "explanations": {"三要素": "“三要素”指起决定作用的关键因素。前文的湿度、翻堆频率和温度正是三项并列的控制因素，可以放入空缺。", "三阶段": "语义：前文的湿度、翻堆频率和温度是同时需要控制的并列因素，不是先后进行的阶段。", "三大件": "搭配：“协同”多用于因素、系统，“三大件”指具体的成套物品，不能说“维持三大件协同”。", "三部曲": "语义：“三部曲”指成套的三部作品，与控制湿度、温度的操作无关。"}, "sentence_index": 0, "correct_answer": "三要素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班有三要素学生，都很努力。", "explanation": "这里应说〈三名学生〉。「三要素」是抽象的关键因素，不能用来指人。"}, {"text": "这些动物分为三要素：哺乳类、鸟类和鱼类。", "explanation": "这里应该用〈三种类型〉。“三要素”指决定作用的关键因素，不能用来给事物分类。"}, {"text": "这张桌子上放着三要素。", "explanation": "这里用的是具体实物的意思。“三要素”是抽象概念，不能当作物品放在桌上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三要素", "is_correct": true, "explanation": "“三要素”指学语言必须具备的关键因素，与“听、说和练”三项相合。"}, {"text": "三轮车", "is_correct": false, "explanation": "语义：「三轮车」是交通工具，不指学习的构成要素，句意不通。"}, {"text": "三件套", "is_correct": false, "explanation": "搭配：“三件套”指成套配备的三样物品，不能用来说学习方法的构成。"}, {"text": "三条款", "is_correct": false, "explanation": "语域：“三条款”是法律、规章类的书面说法，用于日常谈论学习方法并不自然，且与“听、说和练”的内容不符。"}], "explanations": {"三要素": "“三要素”指学语言必须具备的关键因素，与“听、说和练”三项相合。", "三轮车": "语义：「三轮车」是交通工具，不指学习的构成要素，句意不通。", "三件套": "搭配：“三件套”指成套配备的三样物品，不能用来说学习方法的构成。", "三条款": "语域：“三条款”是法律、规章类的书面说法，用于日常谈论学习方法并不自然，且与“听、说和练”的内容不符。"}, "sentence_index": 6, "correct_answer": "三要素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的三要素比我高。", "explanation": "这里用的是身高的意思。“三要素”指事情中起决定作用的关键因素，不能用来说身高。"}, {"text": "我们开车去三要素。", "explanation": "这里把“三要素”当成了地点。“三要素”是抽象概念，不是可以前往的场所。"}, {"text": "他们家生了三要素。", "explanation": "这里应该用〈三胞胎〉。“三要素”指关键因素，不指人，不能用来说生了几个孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要找出决定成败的三要素们。", "corrected_sentence": "我们要找出决定成败的三要素。", "error_description": "错误在于“们”。“们”只附在指人的名词后面，“三要素”是抽象名词，应去掉“们”，说“三要素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "写稿子前，记者要先想清楚新闻地三要素。", "corrected_sentence": "写稿子前，记者要先想清楚新闻的三要素。", "error_description": "结构助词用错。“新闻”修饰名词“三要素”，应用「的」，不能用「地」。「地」用于修饰动词，这里是助词误用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
