INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13108, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手拿着，握持。", "primary_collocate": null, "pronunciation": "shǒu wò", "ipa": "ʂou˨˩˦ wo˥˩", "syllable_count": 2, "sentences": [{"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "手握", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他手握一把雨伞站在门口。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她手握方向盘，认真地看着前面。", "target_word": "手握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子手握着一朵小红花跑回家。", "target_word": "手握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人手握拐杖慢慢走上楼。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他手握话筒，开始唱歌。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察手握手电筒走进黑屋子。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她手握一支笔，在纸上写字。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明手握钥匙，却打不开门。", "target_word": "手握", "complexity_tier": "T3", "furigana": "xiǎo míng shǒu wò yào shi, què dǎ bu kāi mén。", "sentence_source": "generated"}, {"text": "运动员手握奖杯，高兴地笑了。", "target_word": "手握", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手握着", "label": "持续体"}, {"form": "手握过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用手握住并持有某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799c0aa-2ee0-4905-9cb8-472d94641281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手握", "is_correct": true, "explanation": "正确。手握成团指用手紧握使湿土成团，此处用“手握”。"}, {"text": "提", "is_correct": false, "explanation": "搭配：“提”不能用来描述湿土被握成团。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”指用脚压，与用手握成团不符。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能与“成团”搭配描述湿土，搭配不当。"}], "explanations": {"手握": "正确。手握成团指用手紧握使湿土成团，此处用“手握”。", "提": "搭配：“提”不能用来描述湿土被握成团。", "踩": "语义：“踩”指用脚压，与用手握成团不符。", "咬": "搭配：“咬”不能与“成团”搭配描述湿土，搭配不当。"}, "sentence_index": 0, "correct_answer": "手握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手握着我的头，轻轻摸了两下。", "explanation": "这里应该用〈摸〉。手握指用手握住物品，轻轻摸头要用〈摸〉。"}, {"text": "工人手握着一座大楼，很快就完工了。", "explanation": "这里应该用〈盖〉。手握指握持可拿在手里的物品，大楼不能握在手中；建造大楼要用〈盖〉。"}, {"text": "她手握着妈妈的脖子撒娇。", "explanation": "这里应该用〈搂〉。手握指用手握住物品，搂住脖子撒娇要用〈搂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手握", "is_correct": true, "explanation": "正确。手握手电筒指用手拿着手电筒，符合句意。"}, {"text": "吻", "is_correct": false, "explanation": "搭配：“吻”不能带“手电筒”作宾语，搭配不当。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹饪，与拿着手电筒走进屋子无关。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带宾语“手电筒”。"}], "explanations": {"手握": "正确。手握手电筒指用手拿着手电筒，符合句意。", "吻": "搭配：“吻”不能带“手电筒”作宾语，搭配不当。", "煮": "语义：“煮”指烹饪，与拿着手电筒走进屋子无关。", "笑": "配价：“笑”是不及物动词，不能带宾语“手电筒”。"}, "sentence_index": 6, "correct_answer": "手握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他手握着孩子的背，轻声哄他睡觉。", "explanation": "这里应该用〈拍〉。手握指用手握住物品，轻拍孩子的背要用〈拍〉。"}, {"text": "他手握着嘴，忍不住笑了。", "explanation": "这里应该用〈捂〉。手握指用手握住物品，捂嘴要用〈捂〉。"}, {"text": "他手握着耳朵，装作没听见。", "explanation": "这里应该用〈堵〉。手握指用手握住物品，堵住耳朵要用〈堵〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她手握着了剪刀，站在门口。", "corrected_sentence": "她手握着剪刀，站在门口。", "error_description": "多加了“了”：“手握着”已表示持续状态，不能再加完成的“了”，应说“手握着剪刀”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他手握很紧钥匙，不肯放手。", "corrected_sentence": "他手握紧钥匙，不肯放手。", "error_description": "“很”误加在结果补语“紧”之前：结果补语“紧”前不能加“很”，应说“手握紧钥匙”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13109, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散", "is_correct": true, "explanation": "正确：“散”与“成团”相对，指分散、散开。"}, {"text": "出发", "is_correct": false, "explanation": "不是反义词：“出发”指动身前往，与“成团”的聚拢义无对应关系。"}, {"text": "保持", "is_correct": false, "explanation": "不是反义词：“保持”指维持原状，与“成团”没有相对关系。"}, {"text": "修建", "is_correct": false, "explanation": "不是反义词：“修建”指建造工程，与“成团”的聚集义无关。"}], "correct_answer": "散", "explanations": {"散": "正确：“散”与“成团”相对，指分散、散开。", "出发": "不是反义词：“出发”指动身前往，与“成团”的聚拢义无对应关系。", "保持": "不是反义词：“保持”指维持原状，与“成团”没有相对关系。", "修建": "不是反义词：“修建”指建造工程，与“成团”的聚集义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13109, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散", "is_correct": true, "explanation": "正确：“散”与“成团”相对，指分散、散开。"}, {"text": "运输", "is_correct": false, "explanation": "不是反义词：“运输”指运送货物，与“成团”没有相对关系。"}, {"text": "查看", "is_correct": false, "explanation": "不是反义词：“查看”指检查、察看，与“成团”的聚拢义无关。"}, {"text": "栽种", "is_correct": false, "explanation": "不是反义词：“栽种”指种植，与“成团”没有相对关系。"}], "correct_answer": "散", "explanations": {"散": "正确：“散”与“成团”相对，指分散、散开。", "运输": "不是反义词：“运输”指运送货物，与“成团”没有相对关系。", "查看": "不是反义词：“查看”指检查、察看，与“成团”的聚拢义无关。", "栽种": "不是反义词：“栽种”指种植，与“成团”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13109, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指人或事物聚集在一起，形成团体或状态。", "primary_collocate": null, "pronunciation": "chéng tuán", "ipa": "ʈʂʰɤŋ˧˥ tʰuan˧˥", "syllable_count": 2, "sentences": [{"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "成团", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "雪捏一捏就成团了。", "target_word": "成团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面粉加水以后很快成团。", "target_word": "成团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "十个人以上才能成团出发。", "target_word": "成团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报名的人不够，旅游团不能成团。", "target_word": "成团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "泥土太干，很难成团。", "target_word": "成团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "米饭很黏，一捏就成团。", "target_word": "成团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到大水，蚂蚁会成团漂在水面上。", "target_word": "成团", "complexity_tier": "T3", "furigana": "yù dào dà shuǐ, mǎ yǐ huì chéng tuán piāo zài shuǐ miàn shàng.", "sentence_source": "generated"}, {"text": "受惊的鱼群会迅速成团，躲进礁石后面。", "target_word": "成团", "complexity_tier": "T3", "furigana": "shòu jīng de yú qún huì xùn sù chéng tuán, duǒ jìn jiāo shí hòu miàn.", "sentence_source": "generated"}, {"text": "肉馅太松，煮的时候不成团。", "target_word": "成团", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "成团了", "label": "完成体"}, {"form": "成團", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物聚拢后结成一团或达到成团的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799c0aa-2ee0-4905-9cb8-472d94641281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13109, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成团", "is_correct": true, "explanation": "正确：“手握成团”指湿料被握后结成团块，与后文“轻触即散”相呼应。"}, {"text": "散开", "is_correct": false, "explanation": "语义：手握的作用是使其聚拢，手握后“散开”与要求的方向相反，也与“轻触即散”重复。"}, {"text": "发硬", "is_correct": false, "explanation": "语义：湿度控制是为了让材料能手握成团，“发硬”会使材料不再符合“轻触即散”的状态。"}, {"text": "干裂", "is_correct": false, "explanation": "搭配：“干裂”多指表面或土地因干燥而开裂，不说手握干裂。"}], "explanations": {"成团": "正确：“手握成团”指湿料被握后结成团块，与后文“轻触即散”相呼应。", "散开": "语义：手握的作用是使其聚拢，手握后“散开”与要求的方向相反，也与“轻触即散”重复。", "发硬": "语义：湿度控制是为了让材料能手握成团，“发硬”会使材料不再符合“轻触即散”的状态。", "干裂": "搭配：“干裂”多指表面或土地因干燥而开裂，不说手握干裂。"}, "sentence_index": 0, "correct_answer": "成团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块冻肉已经成团了。", "explanation": "这里应该用〈成块〉。成团指松散的东西聚拢成一团，整块的冻肉应说成块。"}, {"text": "这锅汤已经成团了。", "explanation": "这里应该用〈凝固〉。汤变稠、变固体是凝固，成团指松散颗粒聚拢，不用于汤。"}, {"text": "这尊泥人已经成团了。", "explanation": "这里应该用〈成形〉。泥人已有确定的形状，成团指没有形状的松散物聚集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成团", "is_correct": true, "explanation": "正确：“一捏就成团”指米饭黏在一起被捏成一团，与“很黏”相符。"}, {"text": "碎", "is_correct": false, "explanation": "语义：句中说米饭“很黏”，黏的米饭一捏不会碎。"}, {"text": "变干", "is_correct": false, "explanation": "语义：“很黏”说明米饭湿润，一捏不会变干，与语境矛盾。"}, {"text": "撕破", "is_correct": false, "explanation": "搭配：“撕破”多用于纸、布等材料，不说米饭一捏就撕破。"}], "explanations": {"成团": "正确：“一捏就成团”指米饭黏在一起被捏成一团，与“很黏”相符。", "碎": "语义：句中说米饭“很黏”，黏的米饭一捏不会碎。", "变干": "语义：“很黏”说明米饭湿润，一捏不会变干，与语境矛盾。", "撕破": "搭配：“撕破”多用于纸、布等材料，不说米饭一捏就撕破。"}, "sentence_index": 6, "correct_answer": "成团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一个人在房间里成团了。", "explanation": "这里误用了〈成团〉：它指多人或多个松散的物体聚在一起，不能用于单独的个体。"}, {"text": "这首歌的旋律已经成团了。", "explanation": "这里误用了〈成团〉：它指松散的人或物聚拢成团，不能用于抽象的声音。"}, {"text": "这块木头放久了，已经成团了。", "explanation": "木头是整块固体，不会聚拢成团，这里应说“开裂”或“变形”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把湿土捏一捏，很快就成团着。", "corrected_sentence": "把湿土捏一捏，很快就成团了。", "error_description": "体貌错误：“很快就”表示变化已经完成，应用完成的“了”，不能用持续的“着”，应说“成团了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水一淋，这些面粉很快就把成团了。", "corrected_sentence": "雨水一淋，这些面粉很快就成团了。", "error_description": "“把”误加在不及物动词“成团”前：“成团”不带宾语，“把”字句需要处置对象，应说“这些面粉很快就成团了”，不能说“把成团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13110, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13110, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "轻轻地接触或触碰。", "primary_collocate": null, "pronunciation": "qīng chù", "ipa": "tɕʰiŋ˥ tʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "轻触", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "轻触屏幕，手机就亮了。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指轻触花瓣，感觉很软。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轻触这个按钮，灯就会打开。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块面包很脆，轻触就会碎。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请轻触一下屏幕，选择你要的语言。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手轻触湖面，水里泛起了小波纹。", "target_word": "轻触", "complexity_tier": "T3", "furigana": "tā yòng shǒu qīng chù hú miàn, shuǐ lǐ fàn qǐ le xiǎo bō wén.", "sentence_source": "generated"}, {"text": "她轻触了一下我的肩膀，我才醒来。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生轻触伤口周围，问我疼不疼。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你只要轻触图片，就能把它放大。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轻触了", "label": "完成体"}, {"form": "轻触过", "label": "经历体"}, {"form": "轻触着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "轻轻接触、触碰某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799c0aa-2ee0-4905-9cb8-472d94641281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轻触", "is_correct": true, "explanation": "正确答案：轻触（qīng chù）指用手或身体轻轻碰一下。"}, {"text": "清除", "is_correct": false, "explanation": "chú（第二声）与 chù（第四声）声调不同，意思是除去、去掉，与轻轻碰到无关。"}, {"text": "清楚", "is_correct": false, "explanation": "chǔ（第三声）与 chù（第四声）声调不同，意思是明白、清晰。"}, {"text": "请出", "is_correct": false, "explanation": "qǐng（第三声）与 qīng（第一声）、chū（第一声）与 chù（第四声）声调都不同，意思是请某人出来。"}, {"text": "清出", "is_correct": false, "explanation": "chū（第一声）与 chù（第四声）声调不同，意思是清理后移出。"}], "explanations": {"轻触": "正确答案：轻触（qīng chù）指用手或身体轻轻碰一下。", "清除": "chú（第二声）与 chù（第四声）声调不同，意思是除去、去掉，与轻轻碰到无关。", "清楚": "chǔ（第三声）与 chù（第四声）声调不同，意思是明白、清晰。", "请出": "qǐng（第三声）与 qīng（第一声）、chū（第一声）与 chù（第四声）声调都不同，意思是请某人出来。", "清出": "chū（第一声）与 chù（第四声）声调不同，意思是清理后移出。"}, "sentence_index": null, "correct_answer": "轻触"}, "level_3": {"options": [{"text": "轻触", "is_correct": true, "explanation": "正确：“轻触即散”指轻轻一碰就散，与前文“轻”的操作要求一致。"}, {"text": "重击", "is_correct": false, "explanation": "语义：句中强调“轻”的操作，重击与之矛盾，不符合湿度控制的描述。"}, {"text": "踩踏", "is_correct": false, "explanation": "语义：踩踏是用力的动作，与“轻”冲突，也不是操作流程中的步骤。"}, {"text": "注视", "is_correct": false, "explanation": "语义：“注视”只是看，不能使湿土散开，与手感测试的描述不符。"}], "explanations": {"轻触": "正确：“轻触即散”指轻轻一碰就散，与前文“轻”的操作要求一致。", "重击": "语义：句中强调“轻”的操作，重击与之矛盾，不符合湿度控制的描述。", "踩踏": "语义：踩踏是用力的动作，与“轻”冲突，也不是操作流程中的步骤。", "注视": "语义：“注视”只是看，不能使湿土散开，与手感测试的描述不符。"}, "sentence_index": 0, "correct_answer": "轻触"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力轻触门板，把门板撞出了一个洞。", "explanation": "这里误用了〈轻触〉：它只指轻轻接触，不能表示用力碰撞；用力碰撞应说〈碰撞〉。"}, {"text": "汽车轻触了路边的树，树干被撞断了。", "explanation": "这里误用了〈轻触〉：它只指轻轻接触，不能表示碰撞造成的损坏；此处应说〈碰撞〉。"}, {"text": "老师轻触了这份计划，计划很快就批准了。", "explanation": "这里误用了〈轻触〉：它只指身体或物体的轻轻接触，不能用于抽象的计划；审阅计划应说〈审阅〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻触", "is_correct": true, "explanation": "正确：“他用手轻触湖面”指用手轻轻碰一下水面，所以水里泛起了小波纹。"}, {"text": "眺望", "is_correct": false, "explanation": "搭配：“眺望”用眼睛远看，不能说用手眺望湖面。"}, {"text": "打开", "is_correct": false, "explanation": "语义：湖面不能被“打开”，与后文“泛起小波纹”的情形不符。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：湖面被冻结后水里不会再泛起波纹，与后半句矛盾。"}], "explanations": {"轻触": "正确：“他用手轻触湖面”指用手轻轻碰一下水面，所以水里泛起了小波纹。", "眺望": "搭配：“眺望”用眼睛远看，不能说用手眺望湖面。", "打开": "语义：湖面不能被“打开”，与后文“泛起小波纹”的情形不符。", "冻结": "语义：湖面被冻结后水里不会再泛起波纹，与后半句矛盾。"}, "sentence_index": 6, "correct_answer": "轻触"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我轻触了整整一个下午，什么也没做。", "explanation": "这里误用了〈轻触〉：它指瞬间的轻轻接触，不能表示持续数小时的活动；此处应说〈等〉。"}, {"text": "他的发言轻触了问题的核心，大家都听懂了。", "explanation": "这里应该用〈触及〉。轻触只指身体或物体的轻轻接触，用于抽象的问题时应说〈触及〉。"}, {"text": "他狠狠地轻触了对方的脸，对方疼得叫了起来。", "explanation": "这里误用了〈轻触〉：它指轻轻接触，与“狠狠地”矛盾；此处应说〈打〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他轻触一下了我的肩膀，让我小声点。", "corrected_sentence": "他轻触了一下我的肩膀，让我小声点。", "error_description": "“了”位置错误：应说“轻触了一下”，“了”紧跟“轻触”；“轻触一下了”语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用手指把屏幕轻触，屏幕就亮了。", "corrected_sentence": "他用手指把屏幕轻触一下，屏幕就亮了。", "error_description": "“把”字句缺少补语：“把”字句中动词后需带补语，如“一下”，说“把屏幕轻触一下”；只说“把屏幕轻触”语义不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
