INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13113, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13113, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "物体内部所含有的水分或水分的比例。", "primary_collocate": null, "pronunciation": "hán shuǐ liàng", "ipa": "xan˧˥ ʂweɪ˨˩˦ liɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "含水量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这块土的含水量很高。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要测一下木头的含水量。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天雨多，土壤含水量会增加。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包的含水量太少，所以很干。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花时，要注意土的含水量。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西瓜的含水量比苹果高得多。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用仪器检查粮食的含水量。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子的含水量低，不容易长草。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸的含水量太高，容易起皱。", "target_word": "含水量", "complexity_tier": "T3", "furigana": "hán shuǐ liàng", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体所含水分的多少或比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799c0aa-2ee0-4905-9cb8-472d94641281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13113, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "含水量", "is_correct": true, "explanation": "含水量：指物体内所含水分的比例，与句中“相当于50%-60%的”的说法相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是能用百分比衡量的量，句中的比例指的是水分。"}, {"text": "硬度", "is_correct": false, "explanation": "搭配：“相当于50%-60%的”说的是比例，硬度不用百分比来表示。"}, {"text": "长度", "is_correct": false, "explanation": "语义：长度与湿度控制、翻堆无关，句中的比例是水分的多少。"}], "explanations": {"含水量": "含水量：指物体内所含水分的比例，与句中“相当于50%-60%的”的说法相符。", "颜色": "语义：颜色不是能用百分比衡量的量，句中的比例指的是水分。", "硬度": "搭配：“相当于50%-60%的”说的是比例，硬度不用百分比来表示。", "长度": "语义：长度与湿度控制、翻堆无关，句中的比例是水分的多少。"}, "sentence_index": 0, "correct_answer": "含水量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天出汗多，要及时补充含水量。", "explanation": "这里应该用〈水分〉。含水量指物体内所含水分的比例，补充的是水分本身，不能说“补充含水量”。"}, {"text": "这个房间的含水量很高，所以很闷。", "explanation": "这里应该用〈湿度〉。含水量说的是物体所含的水分，形容空气潮湿程度要用湿度。"}, {"text": "今年雨季，全市的含水量比去年多了不少。", "explanation": "这里应该用〈降水量〉。含水量指物体所含水分，一段时间内落下的雨雪多少要用降水量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "含水量", "is_correct": true, "explanation": "含水量：西瓜与苹果比较的是所含水分的比例，“比苹果高得多”符合语义。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有“高得多”的程度，无法用来比较西瓜和苹果的水分。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道一般说“浓”“淡”，不说“高得多”。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：体积通常比“大”“小”，不用“高得多”来比较。"}], "explanations": {"含水量": "含水量：西瓜与苹果比较的是所含水分的比例，“比苹果高得多”符合语义。", "颜色": "语义：颜色没有“高得多”的程度，无法用来比较西瓜和苹果的水分。", "味道": "搭配：味道一般说“浓”“淡”，不说“高得多”。", "体积": "搭配：体积通常比“大”“小”，不用“高得多”来比较。"}, "sentence_index": 6, "correct_answer": "含水量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "实验室测出了两只含水量。", "explanation": "量词“只”用于动物或成对的物件，不能修饰“含水量”这类抽象数值。"}, {"text": "报告里列出了一条含水量。", "explanation": "量词“条”用于细长的事物，“含水量”是数值，不能用“条”来计量。"}, {"text": "他们需要一把含水量作为对照。", "explanation": "量词“把”多用于有柄的器具，不能用来修饰“含水量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批饼干的一只含水量很低，所以很脆。", "corrected_sentence": "这批饼干的含水量很低，所以很脆。", "error_description": "量词错误：“只”用于动物或成对的东西，不能修饰抽象的“含水量”。正确应为不加量词，说“这批饼干的含水量很低”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这袋大米的含水量高很，要晒干再存。", "corrected_sentence": "这袋大米的含水量很高，要晒干再存。", "error_description": "错误：“很”应放在“高”前作状语，说“很高”，不能说“高很”。正确应为“含水量很高”，“很高”作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
