INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13114, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在无氧环境中才能生长或生存的细菌。", "primary_collocate": null, "pronunciation": "yàn yǎng jūn", "ipa": "jɛn˥˩ jɑŋ˨˩˦ tɕyn˥˥", "syllable_count": 3, "sentences": [{"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "厌氧菌", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "厌氧菌不需要氧气，没有空气也能生长。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密封的罐子里没有氧气，容易长出厌氧菌。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说伤口很深，里面可能有厌氧菌。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沼气池里的厌氧菌能把垃圾变成沼气。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厌氧菌怕氧气，一见到空气就会死。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上给我们看了厌氧菌的照片。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水处理厂利用厌氧菌分解有机物。", "target_word": "厌氧菌", "complexity_tier": "T3", "furigana": "wū shuǐ chǔ lǐ chǎng lì yòng yàn yǎng jūn fēn jiě yǒu jī wù", "sentence_source": "generated"}, {"text": "堆肥太湿又不通风，厌氧菌就会变多。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的肠道里也有很多厌氧菌。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "专性厌氧菌", "label": "复合"}, {"form": "兼性厌氧菌", "label": "复合"}, {"form": "厭氧菌", "label": "繁体"}], "register": "书面", "sense_fingerprint": "无氧环境中才能生长的细菌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b564bc7-abf7-40ec-96cb-cfa30e5b9152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厌氧菌", "is_correct": true, "explanation": "“厌氧菌”在无氧环境中生长，“抑制……滋生”针对的是它，符合“引入氧气”的语境。"}, {"text": "好氧菌", "is_correct": false, "explanation": "语义：好氧菌需要氧气才能生长，前文引入氧气会促进它繁殖，不能说“抑制好氧菌滋生”。"}, {"text": "嗜热菌", "is_correct": false, "explanation": "语义：后文说嗜热菌群是要保持活跃的区间，不能与“抑制滋生”搭配。"}, {"text": "花粉", "is_correct": false, "explanation": "搭配：“滋生”指微生物或害虫大量繁殖，花粉不能说“滋生”。"}], "explanations": {"厌氧菌": "“厌氧菌”在无氧环境中生长，“抑制……滋生”针对的是它，符合“引入氧气”的语境。", "好氧菌": "语义：好氧菌需要氧气才能生长，前文引入氧气会促进它繁殖，不能说“抑制好氧菌滋生”。", "嗜热菌": "语义：后文说嗜热菌群是要保持活跃的区间，不能与“抑制滋生”搭配。", "花粉": "搭配：“滋生”指微生物或害虫大量繁殖，花粉不能说“滋生”。"}, "sentence_index": 0, "correct_answer": "厌氧菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水池表层的厌氧菌需要充足的空气。", "explanation": "这里应该用〈好氧菌〉。厌氧菌在无氧环境中才能生长，需要充足空气的是好氧菌。"}, {"text": "医生给病人打了一针厌氧菌。", "explanation": "这里应该用〈抗生素〉。厌氧菌是细菌，不是药物，不能像药一样“打一针”。"}, {"text": "这碗汤很鲜，是因为加了厌氧菌。", "explanation": "这里应该用〈味精〉。厌氧菌是细菌，不能当调料；汤的鲜味要靠味精等调味品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厌氧菌", "is_correct": true, "explanation": "“厌氧菌”是可以拍成照片的微生物，符合“看了……的照片”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“照片”要拍的是可见的事物，“味道”不搭配“看了……的照片”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见，无法拍成照片给学生看。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是可以拍成照片的对象，与“课上给我们看”的语境不符。"}], "explanations": {"厌氧菌": "“厌氧菌”是可以拍成照片的微生物，符合“看了……的照片”。", "味道": "搭配：“照片”要拍的是可见的事物，“味道”不搭配“看了……的照片”。", "声音": "语义：声音看不见，无法拍成照片给学生看。", "温度": "语义：温度不是可以拍成照片的对象，与“课上给我们看”的语境不符。"}, "sentence_index": 6, "correct_answer": "厌氧菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面包放久了，表面会长出厌氧菌。", "explanation": "这里应该用〈霉菌〉。厌氧菌只在无氧环境中生长，面包表面有空气，不会大量长出它。"}, {"text": "酵母在有氧的环境中繁殖得很快，厌氧菌也一样。", "explanation": "这里应该用〈需氧菌〉。厌氧菌不需要空气，不能像需氧菌那样在有氧环境中快速繁殖。"}, {"text": "香菇属于厌氧菌。", "explanation": "这里应该用〈真菌〉。香菇属于真菌，不能归入厌氧菌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个培养皿里长出了一条厌氧菌。", "corrected_sentence": "这个培养皿里长出了一种厌氧菌。", "error_description": "量词错误：“条”用于细长的东西，菌类应用“种”。应改为“一种厌氧菌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沼气池底部聚集着一位厌氧菌。", "corrected_sentence": "沼气池底部聚集着一种厌氧菌。", "error_description": "量词错误：“位”用于人，菌类应用“种”。应改为“一种厌氧菌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
