INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13115, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指负责持续观察、测量和记录特定区域或系统运行状态，并做出相应处理的机构或场所。", "primary_collocate": null, "pronunciation": "jiān cè zhōng xīn", "ipa": "tɕjɛn˥˥ tsʰɤ˥˩ ʈʂʊŋ˥˥ ɕin˥˥", "syllable_count": 4, "sentences": [{"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需由监测中心全程记录，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "监测中心", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "监测中心的工作人员二十四小时看着屏幕。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变脏时，监测中心会马上发出警报。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，监测中心把数据发给了政府。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在监测中心做研究员。", "target_word": "监测中心", "complexity_tier": "T3", "furigana": "wǒ jiě jie zài jiān cè zhōng xīn zuò yán jiū yuán", "sentence_source": "generated"}, {"text": "监测中心每天记录城市的空气质量。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们参观了监测中心。", "target_word": "监测中心", "complexity_tier": "T3", "furigana": "tā men cān guān le jiān cè zhōng xīn", "sentence_source": "generated"}, {"text": "监测中心发现水库的水位太高，就通知了工人。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火山附近的监测中心一直在测量地面的变化。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个监测中心有很多机器，能一直测量温度。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "空气监测中心", "label": "复合"}, {"form": "監測中心", "label": "繁体"}], "register": "书面", "sense_fingerprint": "持续观察测量记录并处理的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b564bc7-abf7-40ec-96cb-cfa30e5b9152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监测中心", "is_correct": true, "explanation": "“监测中心”是负责测量记录的机构，与“温度则需由……全程记录”的语境相符。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：“湿度”是被测的指标，不能作负责记录的机构，“由湿度全程记录”不成立。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：“氧气”是气体，不能作记录的主体，“由氧气全程记录”不成立。"}, {"text": "含水量", "is_correct": false, "explanation": "搭配：“含水量”是数值，不能充当记录的机构。"}], "explanations": {"监测中心": "“监测中心”是负责测量记录的机构，与“温度则需由……全程记录”的语境相符。", "湿度": "语义：“湿度”是被测的指标，不能作负责记录的机构，“由湿度全程记录”不成立。", "氧气": "语义：“氧气”是气体，不能作记录的主体，“由氧气全程记录”不成立。", "含水量": "搭配：“含水量”是数值，不能充当记录的机构。"}, "sentence_index": 0, "correct_answer": "监测中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病人在监测中心里看病。", "explanation": "这里应该用〈医院〉。监测中心负责观察和测量，不负责看病。"}, {"text": "周末我们去监测中心参观了很多古代的文物。", "explanation": "这里应该用〈博物馆〉。监测中心是工作人员盯着设备、记录数据的地方，不展出古代文物。"}, {"text": "监测中心的服务员每天给顾客端上热菜。", "explanation": "这里应该用〈餐厅〉。监测中心负责观察和测量，不提供餐饮服务，端菜的服务员应在餐厅工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监测中心", "is_correct": true, "explanation": "“监测中心”是可以去参观的场所，符合“参观了……”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以参观的对象，与“参观了”不搭。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或设施，“心跳”不搭配。"}, {"text": "数据", "is_correct": false, "explanation": "语义：数据是信息，不能被“参观”。"}], "explanations": {"监测中心": "“监测中心”是可以去参观的场所，符合“参观了……”。", "空气": "语义：空气不是可以参观的对象，与“参观了”不搭。", "心跳": "搭配：“参观”的对象是场所或设施，“心跳”不搭配。", "数据": "语义：数据是信息，不能被“参观”。"}, "sentence_index": 6, "correct_answer": "监测中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "发电厂每天发出大量电力，监测中心也一样。", "explanation": "这里说监测中心也生产电力，但它只负责观察、测量和记录，不生产电力。"}, {"text": "顾客在监测中心取钱。", "explanation": "这里应该用〈银行〉。监测中心不办理取款业务。"}, {"text": "超市里卖很多蔬菜，监测中心里也卖很多蔬菜。", "explanation": "这里说监测中心也有买卖，但它只负责观察、测量和记录，不做买卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "气象员每天在监测中心们值班。", "corrected_sentence": "气象员每天在监测中心值班。", "error_description": "误用“们”：“们”只加在指人的名词后，“监测中心”是机构，不能说“监测中心们”。应去掉“们”，改为“在监测中心值班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想去那张监测中心看看。", "corrected_sentence": "我想去那个监测中心看看。", "error_description": "量词错误：“张”用于平面物品，监测中心应用“个”。应改为“那个监测中心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
