INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13116, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "嗜热菌是指那些在高温环境下（通常在45℃以上）能够正常生长和繁殖的微生物，它们具有特殊的耐热结构。", "primary_collocate": null, "pronunciation": "shì rè jūn", "ipa": "ʂɻ̩˥˩ ɻɤ˥˩ tɕyn˥˥", "syllable_count": 3, "sentences": [{"text": "嗜热菌喜欢高温，在六十度的水里也能生长。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温泉里的水很热，那里有很多嗜热菌。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗜热菌有特殊的结构，不怕高温。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥温度升高时，嗜热菌会变得很活跃。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在火山口附近发现了嗜热菌。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普通细菌受不了高温，嗜热菌却长得很好。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗜热菌的酶很耐热，可以用在工业生产中。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种嗜热菌在四十五度以上才能繁殖。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海底热泉附近生活着一些嗜热菌。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里培养嗜热菌，需要把温度调高。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "超嗜热菌", "label": "复合"}, {"form": "嗜熱菌", "label": "繁体"}], "register": "书面", "sense_fingerprint": "高温环境下正常生长繁殖的耐热微生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b564bc7-abf7-40ec-96cb-cfa30e5b9152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嗜热菌", "is_correct": true, "explanation": "正确：嗜热菌指喜欢高温的微生物，与句中“喜欢高温”“在六十度的水里也能生长”一致。"}, {"text": "嗜冷菌", "is_correct": false, "explanation": "语义：嗜冷菌喜欢低温，与“喜欢高温”正相反。"}, {"text": "冰块", "is_correct": false, "explanation": "配价：“喜欢”和“生长”要求有生命的主语，冰块不能充当。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：雪花是冷的东西，不会在六十度的水里生长，与句意相悖。"}], "explanations": {"嗜热菌": "正确：嗜热菌指喜欢高温的微生物，与句中“喜欢高温”“在六十度的水里也能生长”一致。", "嗜冷菌": "语义：嗜冷菌喜欢低温，与“喜欢高温”正相反。", "冰块": "配价：“喜欢”和“生长”要求有生命的主语，冰块不能充当。", "雪花": "语义：雪花是冷的东西，不会在六十度的水里生长，与句意相悖。"}, "sentence_index": 0, "correct_answer": "嗜热菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "嗜热菌在零度左右的冰水里大量繁殖。", "explanation": "这里应该用〈嗜冷菌〉。嗜热菌喜欢高温，在零度左右的冰水里大量繁殖要说嗜冷菌。"}, {"text": "温泉边的石头上，嗜热菌长出了一片绿色的叶子。", "explanation": "这里应该用〈植物〉。嗜热菌是微生物，没有叶子；长出叶子的是植物。"}, {"text": "嗜热菌在高温下会被杀死，所以煮沸能消毒。", "explanation": "这里应该用〈病原菌〉。嗜热菌在高温下能正常生长，不会被煮沸杀死；能被煮沸杀死、用来消毒的是病原菌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嗜热菌", "is_correct": true, "explanation": "正确：嗜热菌是耐高温的微生物，其酶耐热，可用于工业生产，与句意一致。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是生物，没有酶。"}, {"text": "小孩", "is_correct": false, "explanation": "语域：“小孩”是口语词，句子是科技语体；“小孩的酶用于工业生产”也不成立。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料是人造材料，不含生物酶，与“酶很耐热”不符。"}], "explanations": {"嗜热菌": "正确：嗜热菌是耐高温的微生物，其酶耐热，可用于工业生产，与句意一致。", "玻璃": "语义：玻璃不是生物，没有酶。", "小孩": "语域：“小孩”是口语词，句子是科技语体；“小孩的酶用于工业生产”也不成立。", "塑料": "语义：塑料是人造材料，不含生物酶，与“酶很耐热”不符。"}, "sentence_index": 6, "correct_answer": "嗜热菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "嗜热菌能在零下的冰层里存活。", "explanation": "这里应该用〈耐寒菌〉。嗜热菌喜欢高温，能在零下冰层里存活的应说耐寒菌。"}, {"text": "嗜热菌的个头比大象还大，我们用肉眼就能看见它。", "explanation": "这里应该用〈大型动物〉。嗜热菌是肉眼看不见的微生物，个体很小，不能说它的个头比大象还大。"}, {"text": "嗜热菌在阴冷潮湿的地方很快就长出来了。", "explanation": "这里应该用〈霉菌〉。霉菌常在阴冷潮湿的地方快速长出；嗜热菌喜欢高温，不会在这样的环境里长得快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只嗜热菌能在八十度的热水里生长。", "corrected_sentence": "这种嗜热菌能在八十度的热水里生长。", "error_description": "“嗜热菌”是微生物，量词应用“种”，不能用“只”（“只”多用于动物）。应改为“这种嗜热菌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多嗜热菌们在热泉里繁殖。", "corrected_sentence": "很多嗜热菌在热泉里繁殖。", "error_description": "“嗜热菌”指微生物，不能加“们”表示复数；应说“很多嗜热菌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
