INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13117, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容行动积极、气氛热烈。", "primary_collocate": null, "pronunciation": "huó yuè", "ipa": "xwo˧˥ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他在班里很活跃，常常第一个发言。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的会议气氛很活跃。", "target_word": "活跃", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "网上的讨论越来越活跃。", "target_word": "活跃", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "市场很活跃，每天都有很多人来买东西。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是社团里最活跃的成员。", "target_word": "活跃", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家的发言很活跃，教室里一点也不安静。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人在讨论区里非常活跃。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的夜生活越来越活跃了。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他退休以后还很活跃，常常参加活动。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛一开始，场上的气氛就变得很活跃。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "活跃了", "label": "体标"}, {"form": "活跃度", "label": "复合词"}], "register": "中性", "sense_fingerprint": "行动积极主动、气氛热烈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d26fe1-76de-4d72-b2de-845fecb9db9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活跃", "is_correct": true, "explanation": "“活跃”形容行动积极、发言踊跃，与“常常第一个发言”相合，可以放入空缺。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”与“常常第一个发言”矛盾，不能说在班里很安静又总是最先发言。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”与“第一个发言”的行为相互矛盾。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”与“常常第一个发言”相矛盾，不能既冷淡又最先发言。"}], "explanations": {"活跃": "“活跃”形容行动积极、发言踊跃，与“常常第一个发言”相合，可以放入空缺。", "安静": "语义：“安静”与“常常第一个发言”矛盾，不能说在班里很安静又总是最先发言。", "害羞": "语义：“害羞”与“第一个发言”的行为相互矛盾。", "冷淡": "语义：“冷淡”与“常常第一个发言”相矛盾，不能既冷淡又最先发言。"}, "sentence_index": 0, "correct_answer": "活跃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听完消息后，心情很活跃。", "explanation": "这里应该用〈兴奋〉。“活跃”形容行动或气氛，描述心情要说“兴奋”。"}, {"text": "这个句子很活跃，读起来很有力量。", "explanation": "“活跃”形容人的行动或场面的气氛，不能用来形容句子。"}, {"text": "他的成绩很活跃，每次考试都进步。", "explanation": "这里应该用〈提高〉。“活跃”不形容成绩，说成绩进步要用“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活跃", "is_correct": true, "explanation": "“活跃”形容人在讨论区里发言积极、气氛热烈，与“非常”相合，可以放入空缺。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”多说光线、眼神，不说人在讨论区里“明亮”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来说讨论区里的人。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”形容温度或态度，与“讨论区”里热烈交流的情形矛盾。"}], "explanations": {"活跃": "“活跃”形容人在讨论区里发言积极、气氛热烈，与“非常”相合，可以放入空缺。", "明亮": "搭配：“明亮”多说光线、眼神，不说人在讨论区里“明亮”。", "高大": "体貌：“高大”形容身材，不能用来说讨论区里的人。", "冰冷": "语义：“冰冷”形容温度或态度，与“讨论区”里热烈交流的情形矛盾。"}, "sentence_index": 6, "correct_answer": "活跃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的音量很活跃，听起来很舒服。", "explanation": "这里应该用〈响亮〉。“活跃”形容行动或气氛，不能用来形容音量的大小。"}, {"text": "他很活跃地坐在椅子上，一动不动。", "explanation": "“活跃”形容行动积极，与“一动不动”相互矛盾，搭配不通。"}, {"text": "这块石头很活跃，每天都在跑来跑去。", "explanation": "“活跃”形容人或动物的行动，石头不能用来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在论坛上很活跃过。", "corrected_sentence": "她在论坛上很活跃。", "error_description": "体标错误。形容词“活跃”后面不能直接加“过”，表示“很活跃”这一状态应去掉“过”，说“她在论坛上很活跃。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个活跃地社团。", "corrected_sentence": "这是一个活跃的社团。", "error_description": "结构助词错误。形容词修饰名词时要用“的”，不能用“地”，应说“活跃的社团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13118, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13118, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指两个端点之间的所有数值或时间范围。", "primary_collocate": null, "pronunciation": "qū jiān", "ipa": "tɕʰy˥˥ tɕjɛn˥˥", "syllable_count": 2, "sentences": [{"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "区间", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个数的值在三到五这个区间里。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的气温区间是十八到二十五度。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把答案控制在这个区间内。", "target_word": "区间", "complexity_tier": "T3", "furigana": "qǐng bǎ dá àn kòng zhì zài zhè gè qū jiān nèi", "sentence_source": "generated"}, {"text": "早上七点到九点这个区间，路上车很多。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试成绩在八十到九十的区间里。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区间的数字都比十大。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格区间是一百到两百元。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请选择你的年龄区间。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图上这段区间表示一个星期。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "数值区间", "label": "复合"}, {"form": "時間區間", "label": "繁体"}], "register": "书面", "sense_fingerprint": "区间：两个端点之间的所有数值或时间范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b564bc7-abf7-40ec-96cb-cfa30e5b9152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13118, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "区间", "is_correct": true, "explanation": "正确：区间指两个端点之间的数值或时间范围。"}, {"text": "期间", "is_correct": false, "explanation": "qī 与 qū 韵母不同（i 与 ü），意思是“期间”，指某段时期之内。"}, {"text": "其间", "is_correct": false, "explanation": "qí 与 qū 韵母不同，意思是“其间”，指那段时间或两者之中。"}, {"text": "去见", "is_correct": false, "explanation": "qù 与 qū 声调不同，jiàn 与 jiān 声调不同，意思是“去见”，指前往会见。"}, {"text": "取件", "is_correct": false, "explanation": "qǔ 与 qū 声调不同，jiàn 与 jiān 声调不同，意思是“取件”，指领取物品。"}], "explanations": {"区间": "正确：区间指两个端点之间的数值或时间范围。", "期间": "qī 与 qū 韵母不同（i 与 ü），意思是“期间”，指某段时期之内。", "其间": "qí 与 qū 韵母不同，意思是“其间”，指那段时间或两者之中。", "去见": "qù 与 qū 声调不同，jiàn 与 jiān 声调不同，意思是“去见”，指前往会见。", "取件": "qǔ 与 qū 声调不同，jiàn 与 jiān 声调不同，意思是“取件”，指领取物品。"}, "sentence_index": null, "correct_answer": "区间"}, "level_3": {"options": [{"text": "区间", "is_correct": true, "explanation": "正确：区间指数值范围，与前文“理想范围为55°C至65°C”相呼应。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与温度范围无关，“嗜热菌群活跃颜色”不成立。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：湿度是含水的程度，与“嗜热菌群活跃”后面的范围不合。"}, {"text": "工艺", "is_correct": false, "explanation": "语义：工艺指加工方法，菌群不能“活跃”成工艺。"}], "explanations": {"区间": "正确：区间指数值范围，与前文“理想范围为55°C至65°C”相呼应。", "颜色": "语义：颜色与温度范围无关，“嗜热菌群活跃颜色”不成立。", "湿度": "语义：湿度是含水的程度，与“嗜热菌群活跃”后面的范围不合。", "工艺": "语义：工艺指加工方法，菌群不能“活跃”成工艺。"}, "sentence_index": 0, "correct_answer": "区间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的区间是下午三点。", "explanation": "这里应该用〈时间〉。区间要有两个端点，如三点到五点；只说一个时刻时要用“时间”。"}, {"text": "这个区间是圆形的，很好看。", "explanation": "这里应该用〈形状〉。区间是数值或时间的范围，没有形状，不能说它是圆形的。"}, {"text": "在旅行区间，我们拍了很多照片。", "explanation": "这里应该用〈期间〉。区间指两端之间的范围，“在某段时间里”要说“在旅行期间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区间", "is_correct": true, "explanation": "正确：区间指一段数值范围，“这个区间的数字”与句意一致。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是数值范围，“这个教室的数字”不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有大小之分，“颜色的数字都比十大”说不通。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“数字”不能用来比较性格，“性格的数字”不搭配。"}], "explanations": {"区间": "正确：区间指一段数值范围，“这个区间的数字”与句意一致。", "教室": "语义：教室不是数值范围，“这个教室的数字”不成立。", "颜色": "语义：颜色没有大小之分，“颜色的数字都比十大”说不通。", "性格": "搭配：“数字”不能用来比较性格，“性格的数字”不搭配。"}, "sentence_index": 6, "correct_answer": "区间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班有一个区间的同学都来了。", "explanation": "这里应该用〈同学们〉。区间指数值或时间的范围，是抽象概念，不能用来数人。"}, {"text": "这个区间的声音很大，吵得我睡不着。", "explanation": "这里应该用〈声音〉。区间指数值或时间的范围，没有声音，不能说它很吵。"}, {"text": "这根绳子的区间有三米长。", "explanation": "这里应该用〈长度〉。区间指两端之间的数值或时间范围，说绳子的长短要用长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条区间的起点是三，终点是五。", "corrected_sentence": "这个区间的起点是三，终点是五。", "error_description": "区间是抽象的数值范围，量词应用“个”；“条”用于细长的东西，不能用来数区间。应改为“这个区间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这条区间的上限定在一百。", "corrected_sentence": "我们把这个区间的上限定在一百。", "error_description": "量词误用：“区间”是抽象的数值范围，应配量词“个”，“条”用于细长的东西，不能用来数区间。应把“这条”改为“这个”，说“这个区间的上限”。正确形式是「我们把这个区间的上限定在一百」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
