INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13119, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消灭；杀死。", "primary_collocate": null, "pronunciation": "miè shā", "ipa": "mjɛ˥˩ ʂa˥", "syllable_count": 2, "sentences": [{"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "灭杀", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "高温可以灭杀水里的细菌。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳光能灭杀很多病菌。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用药灭杀田里的害虫。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药水可以灭杀蚊子的幼虫。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开水能灭杀杯子上的细菌。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把垃圾放进高温炉里灭杀病菌。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种光能灭杀空气中的病毒。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的低温灭杀了不少害虫。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每周用热水灭杀床上的小虫。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭杀了", "label": "体标"}, {"form": "灭杀过", "label": "体标"}, {"form": "滅殺", "label": "繁体"}], "register": "书面", "sense_fingerprint": "灭杀：消灭、杀死有害的细菌、害虫等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b564bc7-abf7-40ec-96cb-cfa30e5b9152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灭杀", "is_correct": true, "explanation": "本词：与“可有效”搭配，指消灭病原体和杂草种子，符合句意。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”表示数量变多，用在此处会说病原体增多，与“可有效”的句意相反。"}, {"text": "保护", "is_correct": false, "explanation": "搭配：“保护”的对象是需要照顾的事物，不能与病原体、杂草种子搭配。"}, {"text": "培养", "is_correct": false, "explanation": "语义：“培养”指使其生长，与高温要消除病原体的语境相反。"}], "explanations": {"灭杀": "本词：与“可有效”搭配，指消灭病原体和杂草种子，符合句意。", "增加": "语义：“增加”表示数量变多，用在此处会说病原体增多，与“可有效”的句意相反。", "保护": "搭配：“保护”的对象是需要照顾的事物，不能与病原体、杂草种子搭配。", "培养": "语义：“培养”指使其生长，与高温要消除病原体的语境相反。"}, "sentence_index": 0, "correct_answer": "灭杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天用抹布灭杀桌上的灰尘。", "explanation": "这里应该用〈清除〉。灭杀用于消灭细菌、害虫等有害生物，灰尘不是生物，不能用灭杀。"}, {"text": "拆迁队灭杀了这栋老楼。", "explanation": "这里应该用〈拆除〉。灭杀的对象是敌人或有害生物，楼房不是，不能用灭杀。"}, {"text": "政府决心灭杀贫困。", "explanation": "这里应该用〈消除〉。灭杀用于消灭有害生物，贫困是抽象的社会问题，不能用灭杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灭杀", "is_correct": true, "explanation": "本词：指消灭病菌，与“把垃圾放进高温炉里”的语境搭配，符合句意。"}, {"text": "收集", "is_correct": false, "explanation": "语义：“收集”是聚拢、搜集，与高温炉中消灭病菌的语境相反。"}, {"text": "传播", "is_correct": false, "explanation": "语义：“传播”指扩散开，放进高温炉里不会传播病菌，与句意相反。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”多用于动物，不能以病菌作宾语。"}], "explanations": {"灭杀": "本词：指消灭病菌，与“把垃圾放进高温炉里”的语境搭配，符合句意。", "收集": "语义：“收集”是聚拢、搜集，与高温炉中消灭病菌的语境相反。", "传播": "语义：“传播”指扩散开，放进高温炉里不会传播病菌，与句意相反。", "饲养": "搭配：“饲养”多用于动物，不能以病菌作宾语。"}, "sentence_index": 6, "correct_answer": "灭杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每周用洗衣机灭杀床单上的污渍。", "explanation": "这里应该用〈去除〉。灭杀的对象是有害生物，污渍不是生物，不能用灭杀。"}, {"text": "消防员用水灭杀了厨房里的火。", "explanation": "这里应该用〈扑灭〉。火不是生物，灭杀用于消灭有害生物，不能用于火。"}, {"text": "他们每天用扫帚灭杀楼道里的垃圾。", "explanation": "这里应该用〈清理〉。垃圾不是生物，灭杀用于消灭有害生物，不能用于垃圾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民用药灭杀着田里的害虫。", "corrected_sentence": "农民用药灭杀了田里的害虫。", "error_description": "“了”误作“着”。灭杀是有结果的动作，表示动作已完成时应用“了”，“着”表示动作持续，与“灭杀”的完成义不合。应把“灭杀着”改为“灭杀了”。正确形式是「农民用药灭杀了田里的害虫」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用高温把灭杀了病菌。", "corrected_sentence": "他们用高温灭杀了病菌。", "error_description": "“把”字误放在动词“灭杀”之前。“把”字句要把宾语“病菌”提到“把”后，此处不用“把”字句，应删去“把”，说“他们用高温灭杀了病菌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
