INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13120, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13120, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指事情经过的时间；持续的时间。", "primary_collocate": null, "pronunciation": "lì shí", "ipa": "li˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "整个过程历时三至六个月，视气候与管理精度而定，终产物呈深褐色、质地疏松、具森林土壤特有清香，即标志腐熟完成。", "target_word": "历时", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这次修路历时两年。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛历时三个小时才结束。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个会议历时一天。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座桥历时五年建成。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书历时十年才写完。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行历时二十天。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家历时一个星期。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的谈判历时很久。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雨历时三天三夜。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷時", "label": "繁体"}], "register": "书面", "sense_fingerprint": "历时：事情从开始到结束持续了一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b564bc7-abf7-40ec-96cb-cfa30e5b9152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13120, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "历时", "is_correct": true, "explanation": "本词：指事情经过的时间，即从开始到结束持续的时长。"}, {"text": "历史", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是历史。"}, {"text": "理事", "is_correct": false, "explanation": "lǐ 与 lì、shì 与 shí 声调都不同，意思是理事，即管理事务的人。"}, {"text": "离世", "is_correct": false, "explanation": "lí 与 lì、shì 与 shí 声调都不同，意思是去世。"}, {"text": "力士", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是力气大的人。"}], "explanations": {"历时": "本词：指事情经过的时间，即从开始到结束持续的时长。", "历史": "shǐ（第三声）与 shí（第二声）声调不同，意思是历史。", "理事": "lǐ 与 lì、shì 与 shí 声调都不同，意思是理事，即管理事务的人。", "离世": "lí 与 lì、shì 与 shí 声调都不同，意思是去世。", "力士": "shì（第四声）与 shí（第二声）声调不同，意思是力气大的人。"}, "sentence_index": null, "correct_answer": "历时"}, "level_3": {"options": [{"text": "历时", "is_correct": true, "explanation": "本词：指整个过程所经过的时间，与“三至六个月”搭配，符合句意。"}, {"text": "发生", "is_correct": false, "explanation": "搭配：“发生”指事件出现，不能以时间段作宾语。"}, {"text": "改善", "is_correct": false, "explanation": "语义：“改善”表示变好，与“三至六个月”的时长不相符。"}, {"text": "检测", "is_correct": false, "explanation": "搭配：“检测”的宾语是检测对象，不能以时间段作宾语。"}], "explanations": {"历时": "本词：指整个过程所经过的时间，与“三至六个月”搭配，符合句意。", "发生": "搭配：“发生”指事件出现，不能以时间段作宾语。", "改善": "语义：“改善”表示变好，与“三至六个月”的时长不相符。", "检测": "搭配：“检测”的宾语是检测对象，不能以时间段作宾语。"}, "sentence_index": 0, "correct_answer": "历时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的历时很悠久。", "explanation": "这里应该用〈历史〉。历时是动词，指事情经过的时间，不能作主语表示过去的发展过程；“历史”才是名词。"}, {"text": "这条路历时五公里。", "explanation": "这里应该用〈长达〉。历时说事情经过的时间，不能用来表示长度。"}, {"text": "会议历时上午十点到十二点。", "explanation": "这里应该用〈从……到……〉。历时只接表示时长的词，如“一天”，不接时间点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历时", "is_correct": true, "explanation": "本词：指旅行经过的时间，与“二十天”搭配，符合句意。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指建造工程，不能用于旅行。"}, {"text": "下载", "is_correct": false, "explanation": "搭配：“下载”的宾语是文件或软件，不能以旅行作宾语。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”指制造物品，与“旅行”和时间段的句意不相符。"}], "explanations": {"历时": "本词：指旅行经过的时间，与“二十天”搭配，符合句意。", "修建": "语义：“修建”指建造工程，不能用于旅行。", "下载": "搭配：“下载”的宾语是文件或软件，不能以旅行作宾语。", "生产": "语义：“生产”指制造物品，与“旅行”和时间段的句意不相符。"}, "sentence_index": 6, "correct_answer": "历时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大雨历时五厘米。", "explanation": "这里应该用〈降水量〉。历时只说事情经过的时间，不能用长度单位计量。"}, {"text": "这场大雨每天历时三次。", "explanation": "这里应该用〈下〉。历时说一件事持续的时间，不能用来计算次数。"}, {"text": "这件衣服历时五百元。", "explanation": "这里应该用〈售价〉。历时只说事情经过的时长，不能表示金额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座大楼的建设历时着六年。", "corrected_sentence": "这座大楼的建设历时六年。", "error_description": "错误形式是“历时着”。“历时”是动词，表示经过的时间，后面不能加表示持续的“着”。正确形式是「这座大楼的建设历时六年」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考察很历时三个星期。", "corrected_sentence": "这次考察历时三个星期。", "error_description": "错误形式是在“历时”前加了程度副词“很”。“历时”是动词，不能受“很”修饰。正确形式是「这次考察历时三个星期」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
