INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指测量、计算或制造中达到的准确程度。", "primary_collocate": null, "pronunciation": "jīng dù", "ipa": "tɕiŋ˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这台天平的精度很高，每次称量都很可靠。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把尺子的精度很高，量得很准。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人要提高机器的精度，零件才合格。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种秤的精度只有一克，不能称药。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机的定位精度不够，我走错了路。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂要求零件的加工精度必须很高。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气不好，测量的精度会受到影响。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，实验数据的精度比速度更重要。", "target_word": "精度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台新仪器的测量精度提高了，误差更小。", "target_word": "精度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用精度更高的卡尺重新量了一遍零件。", "target_word": "精度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高精度", "label": "复合"}, {"form": "低精度", "label": "复合"}], "register": "中性", "sense_fingerprint": "测量、计算或制造达到的准确程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c243019-86a3-4adf-869e-dc4043fc4b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13121, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精度", "is_correct": true, "explanation": "正确。精度指测量、计算或制造中达到的准确程度。"}, {"text": "精读", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，精读是仔细阅读的意思。"}, {"text": "进度", "is_correct": false, "explanation": "jìn 与 jīng 的韵母不同（in 与 ing），声调也不同，进度指事情进行的程度。"}, {"text": "净度", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，净度指宝石等的纯净程度。"}], "explanations": {"精度": "正确。精度指测量、计算或制造中达到的准确程度。", "精读": "dú（第二声）与 dù（第四声）声调不同，精读是仔细阅读的意思。", "进度": "jìn 与 jīng 的韵母不同（in 与 ing），声调也不同，进度指事情进行的程度。", "净度": "jìng（第四声）与 jīng（第一声）声调不同，净度指宝石等的纯净程度。"}, "sentence_index": null, "correct_answer": "精度"}, "level_3": {"options": [{"text": "精度", "is_correct": true, "explanation": "正确。精度指管理的准确程度，与“视……而定”的语境相符。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：口味指食物或饮料的味道，不能用“很高”来形容天平。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的心理特征，天平没有性格，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指存在的时间长短，与腐熟过程的管理方式无关。"}], "explanations": {"精度": "正确。精度指管理的准确程度，与“视……而定”的语境相符。", "口味": "搭配：口味指食物或饮料的味道，不能用“很高”来形容天平。", "性格": "语义：性格是人的心理特征，天平没有性格，句意不通。", "年龄": "语义：年龄指存在的时间长短，与腐熟过程的管理方式无关。"}, "sentence_index": 0, "correct_answer": "精度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次测验他的精度很高，只错了一道题。", "explanation": "这里应该用〈准确率〉。精度指测量、计算或制造达到的准确程度，说答题的正确比例要用〈准确率〉。"}, {"text": "这条生产线的精度很高，每月能出五万件。", "explanation": "这里应该用〈产量〉。精度指测量、计算或制造的准确程度，说产品的数量要用〈产量〉。"}, {"text": "他游泳的精度很高，动作很标准。", "explanation": "这里应该用〈水平〉。精度只用于测量、计算或制造，说人的技术要用〈水平〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精度", "is_correct": true, "explanation": "正确。精度指测量的准确程度，天气会影响它。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：测量的颜色不会因天气而变化，句意不通。"}, {"text": "口感", "is_correct": false, "explanation": "搭配：“口感”指食物入口的感觉，不能用来修饰“测量”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指人的性情，测量没有脾气，句意不通。"}], "explanations": {"精度": "正确。精度指测量的准确程度，天气会影响它。", "颜色": "语义：测量的颜色不会因天气而变化，句意不通。", "口感": "搭配：“口感”指食物入口的感觉，不能用来修饰“测量”。", "脾气": "语义：脾气指人的性情，测量没有脾气，句意不通。"}, "sentence_index": 6, "correct_answer": "精度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台仪器的精度很小，测出的数很准。", "explanation": "这里应该用〈误差〉。精度高时误差就小，精度不能用“小”来形容。"}, {"text": "这台机床的精度很快，一小时能做五十个。", "explanation": "这里应该用〈速度〉。精度说准确程度，说快慢要用〈速度〉。"}, {"text": "这篇文章的精度很高，逻辑很清楚。", "explanation": "用错对象：精度只用于测量、计算或制造，说文章的好坏要用〈质量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把精度只够量布，称药还不行。", "corrected_sentence": "这种精度只够量布，称药还不行。", "error_description": "量词错误：“精度”是抽象名词，不能用量词“把”（“把”用于有柄的器具）。正确说法是“这种精度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台天平的精度高很，称药很准。", "corrected_sentence": "这台天平的精度很高，称药很准。", "error_description": "语序错误：副词“很”应放在形容词“高”前作状语，说成“高很”不通，应说“很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
