INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13122, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示使稳定、使固定，或经过考虑后做出的决定。", "primary_collocate": null, "pronunciation": "dìng", "ipa": "tiŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我们先定一个见面的时间吧。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们已经定了下个月的旅行计划。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给班里定了三条规矩。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末的会议时间还没定。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把结婚的日子定在了十月。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们定好价钱，再签合同。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了很久，最后定了去北京读书。", "target_word": "定", "complexity_tier": "T3", "furigana": "tā xiǎng le hěn jiǔ, zuìhòu dìng le qù Běijīng dúshū.", "sentence_source": "generated"}, {"text": "他给自己定了一个学习目标。", "target_word": "定", "complexity_tier": "T3", "furigana": "tā gěi zìjǐ dìng le yí gè xuéxí mùbiāo.", "sentence_source": "generated"}, {"text": "婚礼的日期，两家人商量后定了。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明年我们要定一个新目标。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "定了", "label": "体标"}, {"form": "定过", "label": "体标"}, {"form": "定下来", "label": "复合"}], "register": "中性", "sense_fingerprint": "定：使稳定固定，或经考虑后做出决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c243019-86a3-4adf-869e-dc4043fc4b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13122, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "定", "is_correct": true, "explanation": "正确。定（dìng）表示确定、决定，或使稳定、固定。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng（第三声）与 dìng（第四声）声调不同，顶是顶住的意思。"}, {"text": "盯", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，盯是注视的意思。"}, {"text": "钉", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，钉是钉子的意思。"}], "explanations": {"定": "正确。定（dìng）表示确定、决定，或使稳定、固定。", "顶": "dǐng（第三声）与 dìng（第四声）声调不同，顶是顶住的意思。", "盯": "dīng（第一声）与 dìng（第四声）声调不同，盯是注视的意思。", "钉": "dīng（第一声）与 dìng（第四声）声调不同，钉是钉子的意思。"}, "sentence_index": null, "correct_answer": "定"}, "level_3": {"options": [{"text": "定", "is_correct": true, "explanation": "正确。“先定一个见面的时间”指先确定时间，与语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不跟“时间”搭配，“吃一个时间”说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌与安排见面的时间无关，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“时间”搭配，句中要的是确定时间的动作。"}], "explanations": {"定": "正确。“先定一个见面的时间”指先确定时间，与语境相符。", "吃": "搭配：“吃”不跟“时间”搭配，“吃一个时间”说不通。", "唱": "语义：唱歌与安排见面的时间无关，句意不通。", "洗": "搭配：“洗”不能与“时间”搭配，句中要的是确定时间的动作。"}, "sentence_index": 0, "correct_answer": "定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨晚定了一首诗。", "explanation": "这里应该用〈写〉。定是确定或预订的意思，写诗要用〈写〉，不能说“定诗”。"}, {"text": "我昨天定了一封信。", "explanation": "这里应该用〈寄〉。定是确定或预订的意思，寄信要用〈寄〉。"}, {"text": "听到消息后，我定了很生气。", "explanation": "这里应该用〈感到〉。定是确定或决定，不能与“很生气”这类心情搭配，应说“感到很生气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13122, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "定", "is_correct": true, "explanation": "正确。定（dìng）表示确定、决定，或使稳定、固定。"}, {"text": "丁", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，丁指天干第四位或成年男子。"}, {"text": "鼎", "is_correct": false, "explanation": "dǐng（第三声）与 dìng（第四声）声调不同，鼎是古代烹煮用的器具。"}, {"text": "叮", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，叮是叮咬或叮嘱的意思。"}], "explanations": {"定": "正确。定（dìng）表示确定、决定，或使稳定、固定。", "丁": "dīng（第一声）与 dìng（第四声）声调不同，丁指天干第四位或成年男子。", "鼎": "dǐng（第三声）与 dìng（第四声）声调不同，鼎是古代烹煮用的器具。", "叮": "dīng（第一声）与 dìng（第四声）声调不同，叮是叮咬或叮嘱的意思。"}, "sentence_index": null, "correct_answer": "定"}, "level_3": {"options": [{"text": "定", "is_correct": true, "explanation": "正确。“最后定了去北京读书”指最后做出决定，与语境相符。"}, {"text": "逛", "is_correct": false, "explanation": "语义：逛是随意走走看看，与“想了很久”之后做出的决定不符，句意不通。"}, {"text": "咳", "is_correct": false, "explanation": "语义：咳嗽与决定去北京读书无关，句意不通。"}, {"text": "摇", "is_correct": false, "explanation": "搭配：“摇”不能直接带“去北京读书”作宾语，句中要的是表示做决定的动词。"}], "explanations": {"定": "正确。“最后定了去北京读书”指最后做出决定，与语境相符。", "逛": "语义：逛是随意走走看看，与“想了很久”之后做出的决定不符，句意不通。", "咳": "语义：咳嗽与决定去北京读书无关，句意不通。", "摇": "搭配：“摇”不能直接带“去北京读书”作宾语，句中要的是表示做决定的动词。"}, "sentence_index": 6, "correct_answer": "定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的孩子定上了大学。", "explanation": "这里应该用〈考〉。定是确定或预订的意思，考上大学要用〈考〉。"}, {"text": "他听完后，定得直发抖。", "explanation": "这里应该用〈吓〉。定是确定或决定，不能描述身体反应，表示害怕应说“吓得直发抖”。"}, {"text": "他的脸定得很红，像喝了酒。", "explanation": "这里应该用〈脸红〉。定是确定或决定，不能用来形容脸色，应说“脸红得像喝了酒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经把时间定下去了。", "corrected_sentence": "我们已经把时间定下来了。", "error_description": "补语错误：表示“定”的结果应用“下来”，“下去”表示持续，不能表示确定。正确为“定下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们还没好定去哪儿吃饭。", "corrected_sentence": "我们还没定好去哪儿吃饭。", "error_description": "补语位置错误：结果补语“好”应紧跟在“定”后面，说成“好定”改变了结构，应说“定好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
