INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13123, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13123, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在化学反应或生物过程中，经过一系列步骤最终产生的物质。", "primary_collocate": null, "pronunciation": "zhōng chǎn wù", "ipa": "ʈʂʊŋ˥ ʈʂʰan˨˩˦ u˥˩", "syllable_count": 3, "sentences": [{"text": "整个过程历时三至六个月，视气候与管理精度而定，终产物呈深褐色、质地疏松、具森林土壤特有清香，即标志腐熟完成。", "target_word": "终产物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "酿酒的终产物是酒精和二氧化碳。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "堆肥的终产物像黑色的土，没有臭味。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个实验的终产物是一种白色的粉末。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "食物在身体里变化，终产物会排出体外。", "target_word": "终产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光合作用的终产物包括氧气和葡萄糖。", "target_word": "终产物", "complexity_tier": "T3", "furigana": "guāng hé zuòyòng de zhōng chǎn wù bāokuò yǎngqì hé pútáo táng", "sentence_source": "generated"}, {"text": "反应结束后，我们称了称终产物的重量。", "target_word": "终产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写出这个反应的终产物。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋白质分解的终产物里有氨。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发酵三天后，终产物的味道有点酸。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "終產物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "化学反应或生物过程最终产生的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c243019-86a3-4adf-869e-dc4043fc4b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13123, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原料", "is_correct": false, "explanation": "语义：原料是投入反应的材料，不是过程结束时得到的东西，不能标志腐熟完成。"}, {"text": "菌种", "is_correct": false, "explanation": "语义：菌种是促使分解的微生物，不是过程的产物，与“标志腐熟完成”相矛盾。"}, {"text": "添加剂", "is_correct": false, "explanation": "语义：添加剂是加入的辅助物质，不是过程的产物，不能标志腐熟完成。"}, {"text": "终产物", "is_correct": true, "explanation": "正确：指腐熟过程最终产生的物质，句中的深褐色、疏松、清香正是它的特征。"}], "explanations": {"原料": "语义：原料是投入反应的材料，不是过程结束时得到的东西，不能标志腐熟完成。", "菌种": "语义：菌种是促使分解的微生物，不是过程的产物，与“标志腐熟完成”相矛盾。", "添加剂": "语义：添加剂是加入的辅助物质，不是过程的产物，不能标志腐熟完成。", "终产物": "正确：指腐熟过程最终产生的物质，句中的深褐色、疏松、清香正是它的特征。"}, "sentence_index": 0, "correct_answer": "终产物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个实验开始前，先把终产物倒进量筒里。", "explanation": "这里应该用〈试剂〉。终产物是反应结束后才生成的，实验开始前不可能拿来量取。"}, {"text": "这个实验得到了一只终产物。", "explanation": "量词用错：终产物是物质，量词应用〈种〉，不用〈只〉（只多用于动物或成对器官中的一个）。"}, {"text": "这个反应需要加入一些终产物来加快速度。", "explanation": "这里应该用〈催化剂〉。终产物是反应生成的物质，不能用来加快反应；加快反应的是催化剂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说明书", "is_correct": false, "explanation": "语义：称重的对象应是反应生成的物质，说明书不是这一过程中的物质。"}, {"text": "配方", "is_correct": false, "explanation": "搭配：“配方”是书面的步骤和比例，不能说称配方的重量。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度没有重量，不能用来称重，句意不通。"}, {"text": "终产物", "is_correct": true, "explanation": "正确：反应结束后称得的是反应生成的物质，即终产物。"}], "explanations": {"说明书": "语义：称重的对象应是反应生成的物质，说明书不是这一过程中的物质。", "配方": "搭配：“配方”是书面的步骤和比例，不能说称配方的重量。", "温度": "语义：温度没有重量，不能用来称重，句意不通。", "终产物": "正确：反应结束后称得的是反应生成的物质，即终产物。"}, "sentence_index": 6, "correct_answer": "终产物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个反应开始前要先加入终产物，再开始加热。", "explanation": "这里应该用〈原料〉。终产物是反应结束后才得到的，不能在反应开始前加入。"}, {"text": "滴定到终产物时，溶液变成了红色。", "explanation": "这里应该用〈终点〉。终产物是反应生成的物质；滴定时指示剂变色、反应刚好完成的那一刻叫终点，不能说终产物。"}, {"text": "这台电脑的终产物已经升级到了最新版本。", "explanation": "这里应该用〈版本〉。终产物指化学或生物过程的产物，电脑升级的结果要用〈版本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个反应生成了一颗终产物。", "corrected_sentence": "这个反应生成了一种终产物。", "error_description": "“终产物”是物质，量词应用“种”；用“颗”（多指粒状小物）不对。应改为：这个反应生成了一种终产物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些终产物们都很纯净。", "corrected_sentence": "这些终产物都很纯净。", "error_description": "“终产物”是物质，不能加“们”表示复数；“这些”已表示复数，应去掉“们”。应改为：这些终产物都很纯净。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13124, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
