INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13124, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "显现出某种颜色、形状或趋势。", "primary_collocate": null, "pronunciation": "chéng", "ipa": "ʈʂʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这朵花呈红色，非常好看。", "target_word": "呈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "湖水呈绿色，像一块玉。", "target_word": "呈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房间呈长方形。", "target_word": "呈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山路呈之字形，很不好走。", "target_word": "呈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年的销量呈上升趋势。", "target_word": "呈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的脸色呈灰白色，看起来很累。", "target_word": "呈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个岛呈月牙形，很特别。", "target_word": "呈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秋天，树叶呈金黄色。", "target_word": "呈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "病人的血压呈下降趋势。", "target_word": "呈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夕阳下，海面呈橙红色。", "target_word": "呈", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "呈现", "label": "复合"}], "register": "书面语", "sense_fingerprint": "显现出某种颜色、形状或趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108d68a3-9e9d-4db4-87ac-576670149e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13124, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呈", "is_correct": true, "explanation": "呈 chéng 即目标词，意思是显现、露出。"}, {"text": "撑", "is_correct": false, "explanation": "撑 chēng（第一声）与 chéng（第二声）声调不同，意思是支撑。"}, {"text": "陈", "is_correct": false, "explanation": "陈 chén 韵母不同（-n 与 -ng），意思是陈旧。"}, {"text": "长", "is_correct": false, "explanation": "长 cháng 韵母不同（-ang 与 -eng），意思是长短。"}, {"text": "秤", "is_correct": false, "explanation": "秤 chèng（第四声）与 chéng 声调不同，意思是称重的器具。"}], "explanations": {"呈": "呈 chéng 即目标词，意思是显现、露出。", "撑": "撑 chēng（第一声）与 chéng（第二声）声调不同，意思是支撑。", "陈": "陈 chén 韵母不同（-n 与 -ng），意思是陈旧。", "长": "长 cháng 韵母不同（-ang 与 -eng），意思是长短。", "秤": "秤 chèng（第四声）与 chéng 声调不同，意思是称重的器具。"}, "sentence_index": null, "correct_answer": "呈"}, "level_3": {"options": [{"text": "呈", "is_correct": true, "explanation": "呈是动词，表示显现出红色这一状态，与“这朵花……红色”相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣物，花不能穿颜色。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于头饰、手套等，不用于花的颜色。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”指悬挂，与表示显露颜色的语境不合。"}], "explanations": {"呈": "呈是动词，表示显现出红色这一状态，与“这朵花……红色”相合。", "穿": "搭配：“穿”用于衣物，花不能穿颜色。", "戴": "搭配：“戴”用于头饰、手套等，不用于花的颜色。", "挂": "语义：“挂”指悬挂，与表示显露颜色的语境不合。"}, "sentence_index": 0, "correct_answer": "呈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告呈了去年的销售数据。", "explanation": "这里应该用〈显示〉。呈指颜色、形状、趋势等外在状态，报告数据要用显示。"}, {"text": "墙上呈着一幅画。", "explanation": "这里应该用〈挂〉。呈表示显现颜色或形状，不表示把画挂在墙上。"}, {"text": "他的眼泪呈下来。", "explanation": "这里应该用〈流〉。呈表示显现颜色或形状，眼泪往下淌要用流，不能用呈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13124, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "呈", "is_correct": true, "explanation": "呈 chéng 即目标词，意思是显现、露出。"}, {"text": "称", "is_correct": false, "explanation": "称 chēng（第一声）与 chéng 声调不同，意思是称量。"}, {"text": "晨", "is_correct": false, "explanation": "晨 chén 韵母不同（-n 与 -ng），意思是早晨。"}, {"text": "常", "is_correct": false, "explanation": "常 cháng 韵母不同（-ang 与 -eng），意思是经常。"}, {"text": "逞", "is_correct": false, "explanation": "逞 chěng（第三声）与 chéng 声调不同，意思是逞强。"}], "explanations": {"呈": "呈 chéng 即目标词，意思是显现、露出。", "称": "称 chēng（第一声）与 chéng 声调不同，意思是称量。", "晨": "晨 chén 韵母不同（-n 与 -ng），意思是早晨。", "常": "常 cháng 韵母不同（-ang 与 -eng），意思是经常。", "逞": "逞 chěng（第三声）与 chéng 声调不同，意思是逞强。"}, "sentence_index": null, "correct_answer": "呈"}, "level_3": {"options": [{"text": "呈", "is_correct": true, "explanation": "呈表示显现出月牙形这一形状，与“这个岛……月牙形”相合。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”指拍打，与岛屿的形状无关。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说岛屿“吃”形状。"}, {"text": "咬", "is_correct": false, "explanation": "配价：“咬”需要可被咬的对象，岛屿的形状不能被咬。"}], "explanations": {"呈": "呈表示显现出月牙形这一形状，与“这个岛……月牙形”相合。", "拍": "语义：“拍”指拍打，与岛屿的形状无关。", "吃": "搭配：“吃”的对象是食物，不能说岛屿“吃”形状。", "咬": "配价：“咬”需要可被咬的对象，岛屿的形状不能被咬。"}, "sentence_index": 6, "correct_answer": "呈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钱呈给了朋友。", "explanation": "这里应该用〈交给〉。呈指显现颜色、形状或趋势，不能表示把钱交给朋友。"}, {"text": "他的话呈了一个秘密。", "explanation": "这里应该用〈透露〉。呈只用于颜色、形状、趋势等外在状态，不能表示说出一个秘密。"}, {"text": "天空呈了一场大雨。", "explanation": "这里应该用〈下〉。呈表示显现颜色或形状，下雨要用下，不能用呈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片叶子呈了深绿色。", "corrected_sentence": "这片叶子呈深绿色。", "error_description": "“呈”表示显现出的状态，后面不加“了”；应说“这片叶子呈深绿色”，不说“呈了深绿色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天空呈得灰色。", "corrected_sentence": "天空呈灰色。", "error_description": "“呈”后面直接接颜色，不能用“得”；应说“呈灰色”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
