INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指水流发源的地方；比喻事物的根源或起源。", "primary_collocate": null, "pronunciation": "yuán tóu", "ipa": "ɥɛn˧˥ tʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "首先，它从源头显著减少垃圾清运量，缓解市政处理压力，是公民践行环境责任的具体表达。", "target_word": "源头", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河的源头在高高的山上。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江的源头在青藏高原。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要解决问题，先要找到问题的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水污染的源头是上游的工厂。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们沿着小溪向上走，想找到溪水的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谣言的源头很难查清楚。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种思想的源头可以追到两千年前。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要把污染的源头管好。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水清不清，要看源头干不干净。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "源頭", "label": "繁体"}, {"form": "源头活水", "label": "四字格"}, {"form": "一个源头", "label": "量词搭配"}], "register": "书面", "sense_fingerprint": "源头：河流发源之处；比喻事物的根源、起源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755d8dfd-b59d-4c6c-9903-4203478bf4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "源头", "is_correct": true, "explanation": "源头指事情的起始之处，这里说垃圾从源头减少，与句意相符。"}, {"text": "结局", "is_correct": false, "explanation": "语义：“结局”是结果，不能作为减少垃圾的起点，与“从……减少”矛盾。"}, {"text": "大气", "is_correct": false, "explanation": "语义：大气不是产生垃圾的地方，“从大气减少垃圾清运量”说不通。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：“利润”不能作为减少垃圾的来源，“从利润减少垃圾清运量”搭配不当。"}], "explanations": {"源头": "源头指事情的起始之处，这里说垃圾从源头减少，与句意相符。", "结局": "语义：“结局”是结果，不能作为减少垃圾的起点，与“从……减少”矛盾。", "大气": "语义：大气不是产生垃圾的地方，“从大气减少垃圾清运量”说不通。", "利润": "搭配：“利润”不能作为减少垃圾的来源，“从利润减少垃圾清运量”搭配不当。"}, "sentence_index": 0, "correct_answer": "源头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影院的源头在大厅左边，走过去就能出去。", "explanation": "这里应该用〈出口〉。源头指水流发源之处或事物的根源，建筑的出入口要说出口，不能说源头。"}, {"text": "这次比赛的源头很精彩，球迷们都兴奋起来。", "explanation": "这里应该用〈开端〉。源头指事物的来源，比赛刚开始的阶段要说开端，不能说源头。"}, {"text": "这场雨的源头很大，下了一整天。", "explanation": "这里应该用〈雨势〉。源头指事物的来源，雨下得大还是小要说雨势，不能说源头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "源头", "is_correct": true, "explanation": "源头指事情的起始之处，谣言的起始之处难以查清，符合句意。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”不能说“查清楚”，“谣言的速度很难查清楚”搭配不当。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能被查清楚，句子不成立。"}, {"text": "重量", "is_correct": false, "explanation": "语义：谣言没有重量，无法说它的重量很难查清楚。"}], "explanations": {"源头": "源头指事情的起始之处，谣言的起始之处难以查清，符合句意。", "速度": "搭配：“速度”不能说“查清楚”，“谣言的速度很难查清楚”搭配不当。", "颜色": "搭配：“颜色”不能被查清楚，句子不成立。", "重量": "语义：谣言没有重量，无法说它的重量很难查清楚。"}, "sentence_index": 6, "correct_answer": "源头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "句子的源头要加标点。", "explanation": "这里应该用〈句末〉。源头指事物的来源，标点要加在句子末尾，应说句末，不能说源头。"}, {"text": "这次会议的源头很长，大家都累了。", "explanation": "这里应该用〈时长〉。源头指事物的来源，会议持续的时间要说时长，不能说源头。"}, {"text": "这条河的源头在大海，很长很长。", "explanation": "这里应该用〈终点〉。源头指水流发源之处，流入大海的地方是河流的终点，不能说源头在大海。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在河边找到了一条源头，水很清。", "corrected_sentence": "我在河边找到了一个源头，水很清。", "error_description": "量词错误：“源头”作名词时用“个”，不能用长条形事物的量词“条”，应改为“一个源头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "调查人员终于找到了事故的一把源头。", "corrected_sentence": "调查人员终于找到了事故的一个源头。", "error_description": "量词错误：“源头”作名词时用“个”，“把”多用于有柄的器具，不能用来计量源头，应改为“一个源头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "将居民日常生活产生的废弃物集中收集并运输到处理场所的过程。", "primary_collocate": null, "pronunciation": "lā jī qīng yùn", "ipa": "la˥ tɕi˥ tɕʰiŋ˥ yn˥˩", "syllable_count": 4, "sentences": [{"text": "首先，它从源头显著减少垃圾清运量，缓解市政处理压力，是公民践行环境责任的具体表达。", "target_word": "垃圾清运", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们小区的垃圾清运每天早上六点开始。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雪以后，垃圾清运变慢了。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政部门负责全市的垃圾清运工作。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的垃圾清运很及时。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾清运不及时，街道就会很脏。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，垃圾清运也不停。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了做好垃圾清运，工人们半夜就起床了。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾清运一停，楼下马上就有味道了。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的垃圾清运做得很好。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "垃圾清運", "label": "繁体"}], "register": "中性", "sense_fingerprint": "垃圾收集并运往处理场所的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78fdf4f0-324a-48ce-8d2c-3732d912f7c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾清运", "is_correct": true, "explanation": "正确：指收集并运走居民垃圾的过程，可与“减少……量”搭配，且符合“从源头减量”的语境。"}, {"text": "公园绿地", "is_correct": false, "explanation": "语义：减少公园绿地与“从源头减量”“践行环境责任”的语境相悖。"}, {"text": "图书借阅", "is_correct": false, "explanation": "语义：借阅量与“缓解市政处理压力”和环境责任无关。"}, {"text": "游客接待", "is_correct": false, "explanation": "搭配：“减少”虽可接“接待量”，但与前文环境处理语境不搭。"}], "explanations": {"垃圾清运": "正确：指收集并运走居民垃圾的过程，可与“减少……量”搭配，且符合“从源头减量”的语境。", "公园绿地": "语义：减少公园绿地与“从源头减量”“践行环境责任”的语境相悖。", "图书借阅": "语义：借阅量与“缓解市政处理压力”和环境责任无关。", "游客接待": "搭配：“减少”虽可接“接待量”，但与前文环境处理语境不搭。"}, "sentence_index": 0, "correct_answer": "垃圾清运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "楼下堆满了垃圾清运，臭味一直飘到楼上。", "explanation": "清运是把垃圾运走的动作或过程，不是堆在地上的废物本身，所以不能说“堆满”。"}, {"text": "这条河被垃圾清运淹没了。", "explanation": "清运是把垃圾运走的过程，不能指淹没河道的垃圾本身。"}, {"text": "他是个很认真的垃圾清运。", "explanation": "指人时应说〈垃圾清运工〉。“垃圾清运”表示行为，不能直接用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾清运", "is_correct": true, "explanation": "正确：指垃圾收运的工作，可以在“过年的时候……也不停”中作主语。"}, {"text": "春节", "is_correct": false, "explanation": "语义：春节是节日，不是可以“不停”的工作或活动。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不能“不停”运转，与句意不合。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“礼物也不停”搭配不当，礼物不是持续进行的过程。"}], "explanations": {"垃圾清运": "正确：指垃圾收运的工作，可以在“过年的时候……也不停”中作主语。", "春节": "语义：春节是节日，不是可以“不停”的工作或活动。", "饺子": "语义：饺子是食物，不能“不停”运转，与句意不合。", "礼物": "搭配：“礼物也不停”搭配不当，礼物不是持续进行的过程。"}, "sentence_index": 6, "correct_answer": "垃圾清运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都对书架进行垃圾清运。", "explanation": "清运的对象必须是垃圾，不能用来指整理书架。"}, {"text": "这首歌的垃圾清运很好听。", "explanation": "清运是把垃圾运走的过程，不能用来形容歌曲。"}, {"text": "我们明天去垃圾清运玩儿。", "explanation": "清运是过程，不是地点，不能用来指游玩的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区每天早上把垃圾清运很及时。", "corrected_sentence": "我们小区每天早上垃圾清运很及时。", "error_description": "误用“把”字句：“把”字句需要动作补足语（如“把垃圾清运完”），此处“把垃圾清运”后只接形容词，应删去“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只垃圾清运很及时。", "corrected_sentence": "这次垃圾清运很及时。", "error_description": "量词错误：垃圾清运是一次行为，应说“这次”，不能用量词“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
