INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "化学肥料是一种通过化学方法制造的、含有植物生长所需营养的物质，用来提高农作物产量。", "primary_collocate": null, "pronunciation": "huà xué féi liào", "ipa": "xua˥˩ ɕɥe˧˥ fei˧˥ liɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "其次，所得有机肥用于家庭园艺，可改良土壤团粒结构，提升保水保肥能力，减少对化学肥料的依赖，形成“厨房—土壤—餐桌”的营养回路。", "target_word": "化学肥料", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民在地里撒了化学肥料。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学肥料用得太多，土地会变硬。", "target_word": "化学肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们买了三袋化学肥料。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种化学肥料对水稻很有用。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在很多农场少用化学肥料。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学肥料能让玉米长得更高。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老张把化学肥料放在仓库里。", "target_word": "化学肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年化学肥料的价格比去年贵了。", "target_word": "化学肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用化学肥料以前，要先看说明书。", "target_word": "化学肥料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "袋", "label": "量词"}, {"form": "化學肥料", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人工制造、用来提高产量的农业肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78fdf4f0-324a-48ce-8d2c-3732d912f7c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13137, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化学肥料", "is_correct": true, "explanation": "正确。“对……的依赖”指依赖人工化肥，与前文“所得有机肥”形成对照，符合句意。"}, {"text": "土壤", "is_correct": false, "explanation": "语义：句中“土壤”是被改良的对象，人们不会说依赖土壤，与“改良土壤团粒结构”的语境冲突。"}, {"text": "园艺", "is_correct": false, "explanation": "语义：“园艺”是一种活动，不是可以依赖的物质，且句中“家庭园艺”已作为有机肥的用途出现。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“依赖”后接的应是可以依靠的事物，“厨房”是场所，不能作为依赖的对象。"}], "explanations": {"化学肥料": "正确。“对……的依赖”指依赖人工化肥，与前文“所得有机肥”形成对照，符合句意。", "土壤": "语义：句中“土壤”是被改良的对象，人们不会说依赖土壤，与“改良土壤团粒结构”的语境冲突。", "园艺": "语义：“园艺”是一种活动，不是可以依赖的物质，且句中“家庭园艺”已作为有机肥的用途出现。", "厨房": "搭配：“依赖”后接的应是可以依靠的事物，“厨房”是场所，不能作为依赖的对象。"}, "sentence_index": 0, "correct_answer": "化学肥料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们买了三只化学肥料。", "explanation": "这里应该用〈袋〉。肥料多按袋计量，“只”用于动物或成对的东西，不用于化学肥料。"}, {"text": "农民在地里喷化学肥料治虫。", "explanation": "这里应该用〈农药〉。治虫要用农药；化学肥料是给庄稼补充养分的，不能用来杀虫。"}, {"text": "农场用化学肥料喂猪。", "explanation": "这里应该用〈饲料〉。喂养牲畜用饲料；化学肥料是施在土里给植物用的，不能用来喂猪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化学肥料", "is_correct": true, "explanation": "正确。句子主语是用于增产的化学肥料，“能让玉米长得更高”符合它的作用。"}, {"text": "餐桌", "is_correct": false, "explanation": "语义：餐桌是供人吃饭用的家具，不能让玉米长高。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机与玉米的生长无关，不能使玉米长高。"}, {"text": "学校", "is_correct": false, "explanation": "配价：“让”的主语要能对植物施加作用，“学校”不具备这种作用。"}], "explanations": {"化学肥料": "正确。句子主语是用于增产的化学肥料，“能让玉米长得更高”符合它的作用。", "餐桌": "语义：餐桌是供人吃饭用的家具，不能让玉米长高。", "手机": "语义：手机与玉米的生长无关，不能使玉米长高。", "学校": "配价：“让”的主语要能对植物施加作用，“学校”不具备这种作用。"}, "sentence_index": 6, "correct_answer": "化学肥料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们买了一个化学肥料。", "explanation": "这里应该用〈袋〉。肥料多按袋计量，“个”不适用于化学肥料。"}, {"text": "妈妈用化学肥料洗衣服。", "explanation": "这里应该用〈洗衣粉〉。洗衣服要用洗衣粉；化学肥料是施给庄稼的，不能用来洗衣服。"}, {"text": "妈妈用化学肥料做饺子皮。", "explanation": "这里应该用〈面粉〉。做饺子皮要用面粉；化学肥料不能用来做食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民把化学肥料撒很均匀。", "corrected_sentence": "农民把化学肥料撒得很均匀。", "error_description": "补语错误：“撒”后面的状态补语“很均匀”要用“得”连接，应说“撒得很均匀”，不能直接说“撒很均匀”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农场上个月买了两根化学肥料。", "corrected_sentence": "农场上个月买了两袋化学肥料。", "error_description": "量词错误：化学肥料应用量词“袋”计量，“根”用于细长的东西，不能用于化学肥料。应说“两袋化学肥料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
