INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人们用餐时使用的桌子。", "primary_collocate": null, "pronunciation": "cān zhuō", "ipa": "tsʰan˥ ʈʂuo˥", "syllable_count": 2, "sentences": [{"text": "其次，所得有机肥用于家庭园艺，可改良土壤团粒结构，提升保水保肥能力，减少对化学肥料的依赖，形成“厨房—土壤—餐桌”的营养回路。", "target_word": "餐桌", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "全家人围坐在餐桌旁吃饭。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把菜端到餐桌上。", "target_word": "餐桌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张餐桌可以坐六个人。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐桌上放着一束花。", "target_word": "餐桌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，他擦了擦餐桌。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家的餐桌是木头做的。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在餐桌前等着开饭。", "target_word": "餐桌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在餐桌上摆好了碗筷。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的餐桌太大，放不进厨房。", "target_word": "餐桌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "餐桌布", "label": "复合"}], "register": "中性", "sense_fingerprint": "供人们用餐的桌子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78fdf4f0-324a-48ce-8d2c-3732d912f7c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐桌", "is_correct": true, "explanation": "正确。“厨房—土壤—餐桌”指营养循环的终点，餐桌是人们吃饭用的桌子，符合句意。"}, {"text": "垃圾箱", "is_correct": false, "explanation": "语义：垃圾箱不是吃饭的地方，不能构成“营养回路”中从食物到人的一环。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是存放食物的电器，不属于食物被食用、营养回到土壤的循环。"}, {"text": "水池", "is_correct": false, "explanation": "搭配：“回路”中的节点应是人吃进食物的地方，“水池”与“营养回路”的节点不搭配。"}], "explanations": {"餐桌": "正确。“厨房—土壤—餐桌”指营养循环的终点，餐桌是人们吃饭用的桌子，符合句意。", "垃圾箱": "语义：垃圾箱不是吃饭的地方，不能构成“营养回路”中从食物到人的一环。", "冰箱": "语义：冰箱是存放食物的电器，不属于食物被食用、营养回到土壤的循环。", "水池": "搭配：“回路”中的节点应是人吃进食物的地方，“水池”与“营养回路”的节点不搭配。"}, "sentence_index": 0, "correct_answer": "餐桌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把餐桌可以坐六个人。", "explanation": "这里应该用〈张〉。桌子用“张”计量，“把”多用于椅子、伞等有柄的东西。"}, {"text": "妈妈在餐桌前炒菜。", "explanation": "这里应该用〈灶台〉。炒菜要在灶台前进行；餐桌是供人吃饭用的桌子，不能当灶台用。"}, {"text": "医生在餐桌上给病人做手术。", "explanation": "这里应该用〈手术台〉。做手术要在手术台上进行；餐桌是供人吃饭用的，不能用来做手术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐桌", "is_correct": true, "explanation": "正确。“我们家的……是木头做的”说的是家里一件用木头做的家具，餐桌符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是用木头做成的，也不是家具，与“是木头做的”的语境冲突。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不在家中，也不可能是木头做的，与句子的语境冲突。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”是石质材料，与“是木头做的”的材料搭配不合理。"}], "explanations": {"餐桌": "正确。“我们家的……是木头做的”说的是家里一件用木头做的家具，餐桌符合句意。", "空气": "语义：空气不是用木头做成的，也不是家具，与“是木头做的”的语境冲突。", "月亮": "语义：月亮不在家中，也不可能是木头做的，与句子的语境冲突。", "石头": "搭配：“石头”是石质材料，与“是木头做的”的材料搭配不合理。"}, "sentence_index": 6, "correct_answer": "餐桌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们买了一个餐桌，放在客厅里。", "explanation": "这里应该用〈张〉。桌子用“张”计量，“个”不能用于餐桌。"}, {"text": "孩子们躺在餐桌上看电视。", "explanation": "这里应该用〈沙发〉。看电视可以坐或躺在沙发上；餐桌是用来吃饭的，不能躺着用。"}, {"text": "妈妈把牛奶放在餐桌上冷藏。", "explanation": "这里应该用〈冰箱〉。冷藏要用冰箱；餐桌是供人吃饭用的，不能用来冷藏食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家买了一个新餐桌。", "corrected_sentence": "我家买了一张新餐桌。", "error_description": "量词错误：餐桌应用量词“张”计量，“个”不能用于桌子，应说“一张新餐桌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把餐桌擦很干净。", "corrected_sentence": "他把餐桌擦得很干净。", "error_description": "补语错误：“擦”后面的状态补语“很干净”要用“得”连接，应说“擦得很干净”，不能直接说“擦很干净”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
