INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13139, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指食物或物质中含有的，对生命活动必需或有益的成分。", "primary_collocate": null, "pronunciation": "yíng yǎng", "ipa": "iŋ˧˥ jɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "其次，所得有机肥用于家庭园艺，可改良土壤团粒结构，提升保水保肥能力，减少对化学肥料的依赖，形成“厨房—土壤—餐桌”的营养回路。", "target_word": "营养", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "牛奶里有很多营养。", "target_word": "营养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蔬菜和水果的营养很丰富。", "target_word": "营养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种食物没有什么营养。", "target_word": "营养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说孕妇要补充营养。", "target_word": "营养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鸡蛋含有蛋白质等营养。", "target_word": "营养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "煮太久，菜里的营养会流失。", "target_word": "营养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "豆腐里的营养主要是蛋白质和钙。", "target_word": "营养", "complexity_tier": "T3", "furigana": "dòu fu lǐ de yíng yǎng zhǔ yào shì dàn bái zhì hé gài", "sentence_source": "generated"}, {"text": "早餐要吃够蛋白质等多种营养。", "target_word": "营养", "complexity_tier": "T3", "furigana": "zǎo cān yào chī gòu dàn bái zhì děng duō zhǒng yíng yǎng", "sentence_source": "generated"}, {"text": "专家说，这种米含有的营养很全面。", "target_word": "营养", "complexity_tier": "T3", "furigana": "zhuān jiā shuō, zhè zhǒng mǐ hán yǒu de yíng yǎng hěn quán miàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "营养品", "label": "复合"}, {"form": "营养价值", "label": "复合"}, {"form": "营养成分", "label": "复合"}], "register": "中性", "sense_fingerprint": "食物中对生命活动有益的成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13139, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "营养", "is_correct": true, "explanation": "正确：“营养回路”指食物中养分的循环，符合语境。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是可以循环利用的物质成分，“阳光回路”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“回路”搭配表示物质循环。"}, {"text": "节奏", "is_correct": false, "explanation": "语义：节奏与厨房、土壤、餐桌之间的物质循环无关。"}], "explanations": {"营养": "正确：“营养回路”指食物中养分的循环，符合语境。", "阳光": "语义：阳光不是可以循环利用的物质成分，“阳光回路”说不通。", "颜色": "搭配：“颜色”不能与“回路”搭配表示物质循环。", "节奏": "语义：节奏与厨房、土壤、餐桌之间的物质循环无关。"}, "sentence_index": 0, "correct_answer": "营养"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喝了一杯营养。", "explanation": "这里应该用〈种〉或〈份〉。营养不能用“杯”计量，杯只用于装液体的容器。"}, {"text": "我每天吃很多营养。", "explanation": "这里应该用〈食物〉。营养是食物里的成分，不是可以直接当作食物来吃的东西。"}, {"text": "这碗汤的营养很鲜。", "explanation": "这里应该用〈味道〉。“鲜”用于描述味道，营养不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营养", "is_correct": true, "explanation": "正确：“菜里的营养会流失”描述煮太久导致养分损失，符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不会因为煮太久而流失。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不会因为煮太久而流失，语境不合。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”与“流失”搭配不当，尺寸不会随烹煮而流失。"}], "explanations": {"营养": "正确：“菜里的营养会流失”描述煮太久导致养分损失，符合语境。", "价格": "语义：价格不会因为煮太久而流失。", "声音": "语义：声音不会因为煮太久而流失，语境不合。", "尺寸": "搭配：“尺寸”与“流失”搭配不当，尺寸不会随烹煮而流失。"}, "sentence_index": 6, "correct_answer": "营养"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家药店卖各种营养。", "explanation": "这里应该用〈营养品〉。营养是食物里的成分，不能拿来出售，可以卖的是营养品。"}, {"text": "这袋米里有一颗营养。", "explanation": "量词错误：营养不能用“颗”计量，应该用〈种〉。"}, {"text": "这种米的营养很香。", "explanation": "这里应该用〈口感〉。“香”用于描述气味或口感，营养不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份食物含有一个营养。", "corrected_sentence": "这份食物含有一种营养。", "error_description": "量词错误：“营养”应该用“种”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鱼的营养的全面。", "corrected_sentence": "这种鱼的营养很全面。", "error_description": "结构错误：“营养”后应接程度副词“很”再接形容词“全面”作谓语，“的”不能代替“很”，应为“这种鱼的营养很全面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
