INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13140, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为达到某个目标，通过反复练习或指导，使人或动物掌握某种技能或形成某种习惯。", "primary_collocate": null, "pronunciation": "xùn liàn", "ipa": "ɕyn˥˩ ljɛn˥˩", "syllable_count": 2, "sentences": [{"text": "教练每天训练球员两个小时。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在操场上训练。", "target_word": "训练", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要训练狗坐下和握手。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过三个月训练，她游得很快。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生让他每天训练走路。", "target_word": "训练", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位老师训练学生怎样演讲。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司训练新员工用新系统。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把小狗训练得很听话。", "target_word": "训练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人要先训练，才能上战场。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈训练我每天自己整理书包。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "训练了", "label": "体标"}, {"form": "训练过", "label": "体标"}, {"form": "训练着", "label": "体标"}, {"form": "训练营", "label": "复合"}], "register": "中性", "sense_fingerprint": "通过反复练习使人或动物掌握技能或习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "训练", "is_correct": true, "explanation": "正确：教练通过反复指导使球员提高，“训练球员”符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或房间，不能用于球员。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理是把坏的东西弄好，不是对球员的培养。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于人。"}], "explanations": {"训练": "正确：教练通过反复指导使球员提高，“训练球员”符合语境。", "打扫": "搭配：“打扫”的对象是场地或房间，不能用于球员。", "修理": "语义：修理是把坏的东西弄好，不是对球员的培养。", "煮": "搭配：“煮”的对象是食物，不能用于人。"}, "sentence_index": 0, "correct_answer": "训练"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他训练了一下午的作业。", "explanation": "这里应该用〈做〉。训练指培养人或动物的技能，不能与“作业”搭配。"}, {"text": "她训练了一封信就寄走了。", "explanation": "这里应该用〈写〉。训练的对象是人或动物，不能用于信件。"}, {"text": "他训练了一场比赛。", "explanation": "这里应该用〈参加〉。训练的对象是人或动物，比赛是一种活动，不能被训练，应说“参加比赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "训练", "is_correct": true, "explanation": "正确：公司培养新员工使用新系统，“训练新员工”符合语境。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”的对象是商品，不能用于员工。"}, {"text": "烘焙", "is_correct": false, "explanation": "搭配：“烘焙”的对象是食物，不能用于员工。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧不是培养员工用新系统的行为，语境不合。"}], "explanations": {"训练": "正确：公司培养新员工使用新系统，“训练新员工”符合语境。", "包装": "搭配：“包装”的对象是商品，不能用于员工。", "烘焙": "搭配：“烘焙”的对象是食物，不能用于员工。", "烧": "语义：烧不是培养员工用新系统的行为，语境不合。"}, "sentence_index": 6, "correct_answer": "训练"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈训练我的兴趣。", "explanation": "这里应该用〈培养〉。训练是有目标地教人做事，兴趣要用“培养”。"}, {"text": "奶奶训练了一下午的面包。", "explanation": "这里应该用〈烤〉。训练的对象是人或动物，面包不能被训练。"}, {"text": "我训练了一张旧桌子。", "explanation": "这里应该用〈修〉。训练只用于人或动物，旧桌子是物品，应该修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教练每天训练了运动员跑步。", "corrected_sentence": "教练每天训练运动员跑步。", "error_description": "体标错误：“每天”表示经常性的动作，不能与“了”搭配，应为“每天训练运动员跑步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们训练了着三天。", "corrected_sentence": "我们训练了三天。", "error_description": "体标错误：“了”与“着”不能同时使用，应为“我们训练了三天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
