INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13141, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指亲自用手（做某事），强调动作由自己完成。", "primary_collocate": null, "pronunciation": "qīn shǒu", "ipa": "tɕʰin˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "更深层次而言，堆肥行为本身构成一种生态认知的具身化训练：当人们亲手将果皮菜叶投入发酵箱，目击其从腐败到重生的蜕变，便不得不重新审视“废弃物”的定义边界——所谓垃圾，或许只是错置位置的资源。", "target_word": "亲手", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个蛋糕是我亲手做的。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他亲手把礼物交给了妈妈。", "target_word": "亲手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈亲手给我织了一件毛衣。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张卡片是孩子亲手画的。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷亲手在院子里种了一棵树。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她亲手写了一封信给朋友。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨师亲手为客人做了一碗面。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想亲手送他这份礼物。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他亲手修好了那辆旧自行车。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "亲自动手做，强调动作由自己完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13141, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲手", "is_correct": true, "explanation": "正确。亲手（qīn shǒu）指亲自用手做，与听到的读音一致。"}, {"text": "亲口", "is_correct": false, "explanation": "亲口（qīn kǒu）的第二音节是 kǒu，与 shǒu 的声母不同（k 与 sh），意思是用嘴说。"}, {"text": "亲友", "is_correct": false, "explanation": "亲友（qīn yǒu）的第二音节声母是 y，与 shǒu 的 sh 不同，意思是亲人和朋友。"}, {"text": "亲属", "is_correct": false, "explanation": "亲属（qīn shǔ）的第二音节韵母是 u，与 shǒu 的 ou 不同，意思是有血缘或婚姻关系的人。"}], "explanations": {"亲手": "正确。亲手（qīn shǒu）指亲自用手做，与听到的读音一致。", "亲口": "亲口（qīn kǒu）的第二音节是 kǒu，与 shǒu 的声母不同（k 与 sh），意思是用嘴说。", "亲友": "亲友（qīn yǒu）的第二音节声母是 y，与 shǒu 的 sh 不同，意思是亲人和朋友。", "亲属": "亲属（qīn shǔ）的第二音节韵母是 u，与 shǒu 的 ou 不同，意思是有血缘或婚姻关系的人。"}, "sentence_index": null, "correct_answer": "亲手"}, "level_3": {"options": [{"text": "亲手", "is_correct": true, "explanation": "正确。这里指人们亲自用手把果皮菜叶投入发酵箱，符合句意。"}, {"text": "亲口", "is_correct": false, "explanation": "搭配：“亲口”指用嘴说，不能修饰“投入”这一手上的动作。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与后文“目击其……蜕变”的观察结果相矛盾。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳无益，与句末“重生”“资源”的积极结果冲突。"}], "explanations": {"亲手": "正确。这里指人们亲自用手把果皮菜叶投入发酵箱，符合句意。", "亲口": "搭配：“亲口”指用嘴说，不能修饰“投入”这一手上的动作。", "从不": "语义：“从不”表示从来没有，与后文“目击其……蜕变”的观察结果相矛盾。", "白白": "语义：“白白”表示徒劳无益，与句末“重生”“资源”的积极结果冲突。"}, "sentence_index": 0, "correct_answer": "亲手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他亲手读完了这本书。", "explanation": "这里应该用〈亲自〉。亲手强调动作由手完成，读书不靠手，应说“亲自读完”。"}, {"text": "我亲手经历了那场地震。", "explanation": "这里应该用〈亲身〉。亲手指手上的动作，经历事件不用手，应说“亲身经历”。"}, {"text": "我亲手看见了那场比赛。", "explanation": "这里应该用〈亲眼〉。看见靠眼睛，“亲手”不能用于视觉动作，应说“亲眼看见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲手", "is_correct": true, "explanation": "正确。这里表示她自己动手写信，符合句意。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：写信不能“大声”，“大声”修饰的是说话或喊叫。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：“随口”指随便说出，不能修饰书写动作。"}, {"text": "当面", "is_correct": false, "explanation": "语义：写信给朋友表示不当面交流，“当面”与“写信给朋友”相矛盾。"}], "explanations": {"亲手": "正确。这里表示她自己动手写信，符合句意。", "大声": "搭配：写信不能“大声”，“大声”修饰的是说话或喊叫。", "随口": "搭配：“随口”指随便说出，不能修饰书写动作。", "当面": "语义：写信给朋友表示不当面交流，“当面”与“写信给朋友”相矛盾。"}, "sentence_index": 6, "correct_answer": "亲手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他亲手说了这件事。", "explanation": "这里应该用〈亲口〉。说话用嘴，“亲手”不能修饰说话这一动作，应说“亲口说”。"}, {"text": "我亲手听到了这个消息。", "explanation": "这里应该用〈亲耳〉。听靠耳朵，“亲手”不适用于听觉，应说“亲耳听到”。"}, {"text": "我亲手见过那座古城。", "explanation": "这里应该用〈亲见〉。见到景物靠眼睛，“亲手”不能用于这种感知，应说“亲见过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告是他亲手整理了。", "corrected_sentence": "这份报告是他亲手整理的。", "error_description": "句式错误：“是……的”强调句应以“的”结尾，不能用“了”，应为“这份报告是他亲手整理的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我亲手修好在那把旧椅子。", "corrected_sentence": "我亲手修好了那把旧椅子。", "error_description": "错误：结果补语“好”之后不能接介词“在”，应为“我亲手修好了那把旧椅子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
