INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亲眼看见某件事情的发生。", "primary_collocate": null, "pronunciation": "mù jī", "ipa": "mu˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "更深层次而言，堆肥行为本身构成一种生态认知的具身化训练：当人们亲手将果皮菜叶投入发酵箱，目击其从腐败到重生的蜕变，便不得不重新审视“废弃物”的定义边界——所谓垃圾，或许只是错置位置的资源。", "target_word": "目击", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在路口目击了一场车祸。", "target_word": "目击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在找目击这起事故的人。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上，我目击了小偷翻墙。", "target_word": "目击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老人目击了整个抢劫过程。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有目击事情发生，所以不能作证。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在海边目击了一次海上救援。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当时就在现场，目击了爆炸的全过程。", "target_word": "目击", "complexity_tier": "T3", "furigana": "tā dāng shí jiù zài xiàn chǎng, mù jī le bào zhà de quán guò chéng.", "sentence_source": "generated"}, {"text": "邻居目击小偷从窗户爬进了他家。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己目击的经过都告诉了警察。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "目击了", "label": "体标"}, {"form": "目击过", "label": "体标"}, {"form": "目击者", "label": "复合"}, {"form": "目擊", "label": "繁体"}], "register": "书面", "sense_fingerprint": "亲眼看见某件事情发生，多用于事故、案件等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14c65f7f-0b0a-4240-89c9-7a856accbf3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目击", "is_correct": true, "explanation": "目击：亲眼看见事情发生。此处指亲眼看到堆肥中物质从腐败到重生的蜕变过程。"}, {"text": "扼杀", "is_correct": false, "explanation": "语义：「扼杀」指压制使其消亡，与「从腐败到重生」的转化以及后文「重新审视」的因果不符。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：「购买」的宾语是商品，不能说购买一个蜕变的过程。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」是讥讽他人，与人们认真投入堆肥、重新审视废弃物定义的语境不符。"}], "explanations": {"目击": "目击：亲眼看见事情发生。此处指亲眼看到堆肥中物质从腐败到重生的蜕变过程。", "扼杀": "语义：「扼杀」指压制使其消亡，与「从腐败到重生」的转化以及后文「重新审视」的因果不符。", "购买": "搭配：「购买」的宾语是商品，不能说购买一个蜕变的过程。", "嘲笑": "语义：「嘲笑」是讥讽他人，与人们认真投入堆肥、重新审视废弃物定义的语境不符。"}, "sentence_index": 0, "correct_answer": "目击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去医院目击生病的奶奶。", "explanation": "这里应该用〈看望〉。看望是去探问人，目击的宾语必须是正在发生的事情，不能是人。"}, {"text": "我在屋里目击了他们的吵架声。", "explanation": "这里应该用〈听到〉。目击靠视觉，只能用于亲眼看见的事情，不能用来表示听见的声音。"}, {"text": "我常常目击未来的生活。", "explanation": "这里应该用〈想象〉。目击指亲眼看见已经发生的事，未来尚未发生，不能被目击。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目击", "is_correct": true, "explanation": "目击：亲眼看见事情发生。此处指孩子们亲眼看到海上救援的发生。"}, {"text": "支付", "is_correct": false, "explanation": "搭配：「支付」的宾语是费用或款项，不能说支付一次救援。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：「收藏」的宾语是物品，救援这种事件不能被收藏。"}, {"text": "咒骂", "is_correct": false, "explanation": "语义：「咒骂」是骂人，与孩子们在海边见证救人的情景不符。"}], "explanations": {"目击": "目击：亲眼看见事情发生。此处指孩子们亲眼看到海上救援的发生。", "支付": "搭配：「支付」的宾语是费用或款项，不能说支付一次救援。", "收藏": "搭配：「收藏」的宾语是物品，救援这种事件不能被收藏。", "咒骂": "语义：「咒骂」是骂人，与孩子们在海边见证救人的情景不符。"}, "sentence_index": 6, "correct_answer": "目击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我目击这个秘密，但是没告诉别人。", "explanation": "这里应该用〈知道〉。目击指亲眼看见事件，秘密不是能被看见的事情，不能用目击。"}, {"text": "他的笑容让我目击了快乐。", "explanation": "这里应该用〈感受〉。目击是亲眼看见事情，快乐是一种感觉，不能被目击。"}, {"text": "我在图书馆目击了一本书。", "explanation": "这里应该用〈看〉。目击的对象必须是发生的事件，一本书只能看，不能目击。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨晚在巷口目击了一只打斗。", "corrected_sentence": "我昨晚在巷口目击了一场打斗。", "error_description": "「目击」的宾语「打斗」是事件，量词应用「场」，不能用「只」。正确应说「目击了一场打斗」。「只」多用于动物或成对物品中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没有目击了那次事故。", "corrected_sentence": "我没有目击那次事故。", "error_description": "否定句中「目击」后不能再加「了」。「没有」已经表示未发生，应说「我没有目击那次事故」，去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
