INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指生命或状态重新开始，比如死后复活或改过自新。", "primary_collocate": null, "pronunciation": "chóng shēng", "ipa": "ʈʂʰʊŋ˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "更深层次而言，堆肥行为本身构成一种生态认知的具身化训练：当人们亲手将果皮菜叶投入发酵箱，目击其从腐败到重生的蜕变，便不得不重新审视“废弃物”的定义边界——所谓垃圾，或许只是错置位置的资源。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这场大病之后，他觉得自己像经历了一次重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这家老工厂来说，转型就是一次重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，森林迎来了新的重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离婚让她痛苦，也给了她一次重生的机会。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市在战争后获得了重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一个人的重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这次失败看作重生的开始。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧楼变成了图书馆，也是一种重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经历痛苦以后，很多人会有重生的感觉。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次重生", "label": "量词"}], "register": "中性", "sense_fingerprint": "生命或状态的重新开始（名词用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重生", "is_correct": true, "explanation": "正确。“从腐败到重生的蜕变”指从腐烂变为新生，符合句意。"}, {"text": "死亡", "is_correct": false, "explanation": "语义：“蜕变”的结果是新生，“死亡”与之相反，不能作为蜕变的终点。"}, {"text": "衰老", "is_correct": false, "explanation": "语义：“衰老”是走向终结的过程，与“蜕变”所指的新生方向不合。"}, {"text": "乐曲", "is_correct": false, "explanation": "搭配：“从腐败到乐曲的蜕变”不成立，乐曲与物质的分解和更新无关。"}], "explanations": {"重生": "正确。“从腐败到重生的蜕变”指从腐烂变为新生，符合句意。", "死亡": "语义：“蜕变”的结果是新生，“死亡”与之相反，不能作为蜕变的终点。", "衰老": "语义：“衰老”是走向终结的过程，与“蜕变”所指的新生方向不合。", "乐曲": "搭配：“从腐败到乐曲的蜕变”不成立，乐曲与物质的分解和更新无关。"}, "sentence_index": 0, "correct_answer": "重生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个婴儿在一个寒冷的冬天重生了。", "explanation": "这里应该用〈出生〉。重生指生命或状态重新开始，婴儿来到世界应说“出生”。"}, {"text": "这次考试是新学期的重生。", "explanation": "这里应该用〈开端〉。重生强调旧状态结束后重新开始，学期的起点应说“开端”。"}, {"text": "他刚进大学，是重生。", "explanation": "这里应该用〈新生〉。重生指生命或状态重新开始，刚入学的学生应说“新生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重生", "is_correct": true, "explanation": "正确。“讲的是一个人的重生”说明电影主题是人的重新开始，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与电影的主题无关，不能作为电影讲述的内容。"}, {"text": "电量", "is_correct": false, "explanation": "语义：“电量”是电器的概念，不能作为电影讲述的人物主题。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“讲的是……的体温”不成立，体温不能作为电影的主题。"}], "explanations": {"重生": "正确。“讲的是一个人的重生”说明电影主题是人的重新开始，符合句意。", "价格": "语义：“价格”与电影的主题无关，不能作为电影讲述的内容。", "电量": "语义：“电量”是电器的概念，不能作为电影讲述的人物主题。", "体温": "搭配：“讲的是……的体温”不成立，体温不能作为电影的主题。"}, "sentence_index": 6, "correct_answer": "重生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "民主制度的重生始于古希腊。", "explanation": "这里应该用〈诞生〉。民主制度在古希腊首次出现，应说“诞生”；重生指旧事物重新开始，不能用于首次出现。"}, {"text": "我们学校的重生在下周一。", "explanation": "这里应该用〈开学〉。重生指旧状态结束后重新开始，学校新学期开始应说“开学”。"}, {"text": "这台电脑昨天就重生了。", "explanation": "这里应该用〈重启〉。重生指生命或状态重新开始，电脑重新启动应说“重启”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他经历了一把重生。", "corrected_sentence": "他经历了一次重生。", "error_description": "量词错误：“重生”是一次性的经历，应说“一次重生”，这里误用了“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在大病后经历了一棵重生。", "corrected_sentence": "她在大病后经历了一次重生。", "error_description": "量词错误：“重生”是一次性的经历，应说“一次重生”，这里误用了指植物的“棵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
