INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13145, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "错误地放置或安排，放在不该放的位置。", "primary_collocate": null, "pronunciation": "cuò zhì", "ipa": "tsʰuo˥˩ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "更深层次而言，堆肥行为本身构成一种生态认知的具身化训练：当人们亲手将果皮菜叶投入发酵箱，目击其从腐败到重生的蜕变，便不得不重新审视“废弃物”的定义边界——所谓垃圾，或许只是错置位置的资源。", "target_word": "错置", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他把书错置在了别人的书架上。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到钥匙，可能是自己错置了。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件错置后，大家找了很久。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李把手机错置在冰箱里了。", "target_word": "错置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员把这几本杂志错置在了文学类书架上。", "target_word": "错置", "complexity_tier": "T3", "furigana": "gōngzuò rényuán bǎ zhè jǐ běn zázhì cuòzhì zài le wénxué lèi shūjià shàng", "sentence_source": "generated"}, {"text": "档案错置会给工作带来麻烦。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员错置了商品，顾客找不到。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里有些书错置了，需要整理。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发现自己把票错置在旧包里。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "错置了", "label": "体标"}, {"form": "错置过", "label": "体标"}, {"form": "錯置", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把事物放错位置或安排错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14c65f7f-0b0a-4240-89c9-7a856accbf3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13145, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "错置", "is_correct": true, "explanation": "错置：错误地放置，放在不该放的位置。"}, {"text": "错指", "is_correct": false, "explanation": "声调混淆：cuò zhǐ 与 cuò zhì 只差声调（指为第三声）。"}, {"text": "错字", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），意思是写错的字。"}, {"text": "错事", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是做错的事。"}], "explanations": {"错置": "错置：错误地放置，放在不该放的位置。", "错指": "声调混淆：cuò zhǐ 与 cuò zhì 只差声调（指为第三声）。", "错字": "zì 与 zhì 声母不同（z 与 zh），意思是写错的字。", "错事": "shì 与 zhì 声母不同（sh 与 zh），意思是做错的事。"}, "sentence_index": null, "correct_answer": "错置"}, "level_3": {"options": [{"text": "错置", "is_correct": true, "explanation": "正确：错置指东西被放在不该放的位置，与「错置位置的资源」的语境相符。"}, {"text": "丢失", "is_correct": false, "explanation": "搭配：「丢失」的对象是东西本身，不能说「丢失位置」。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：「咀嚼」指用牙齿嚼碎，与「放在不该放的位置」毫无关联。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：「欣赏」的对象是作品或风景，不能用来修饰「位置」。"}], "explanations": {"错置": "正确：错置指东西被放在不该放的位置，与「错置位置的资源」的语境相符。", "丢失": "搭配：「丢失」的对象是东西本身，不能说「丢失位置」。", "咀嚼": "语义：「咀嚼」指用牙齿嚼碎，与「放在不该放的位置」毫无关联。", "欣赏": "搭配：「欣赏」的对象是作品或风景，不能用来修饰「位置」。"}, "sentence_index": 0, "correct_answer": "错置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题太复杂，我们先把它错置一段时间，以后再说。", "explanation": "这里应该用〈搁置〉。错置指把东西放错地方，不指暂时不处理的问题。"}, {"text": "我特意把花瓶错置在桌子中央，好让客人一进门就看见。", "explanation": "这里应该用〈摆放〉。错置指无意中放错地方，与「特意」矛盾；有意安置要说摆放。"}, {"text": "他把大量的时间错置到了学习上。", "explanation": "这里应该用〈投入〉。错置只用于东西放错位置，把时间用在某事上要说投入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13145, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错置", "is_correct": true, "explanation": "正确：「档案错置」指档案被放错了地方，会给工作带来麻烦。"}, {"text": "抚养", "is_correct": false, "explanation": "配价：「抚养」的受事是子女或需要照顾的人，不能以「档案」为受事。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：「拥抱」是人与人之间的亲密动作，档案不能被拥抱。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：「烤」的对象是食物，不能用于档案。"}], "explanations": {"错置": "正确：「档案错置」指档案被放错了地方，会给工作带来麻烦。", "抚养": "配价：「抚养」的受事是子女或需要照顾的人，不能以「档案」为受事。", "拥抱": "语义：「拥抱」是人与人之间的亲密动作，档案不能被拥抱。", "烤": "搭配：「烤」的对象是食物，不能用于档案。"}, "sentence_index": 6, "correct_answer": "错置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把客厅错置得很整洁，朋友都夸他会收拾。", "explanation": "这里应该用〈布置〉。错置只表示放错位置，不能用来形容整洁的状态。"}, {"text": "他把文件错置给了秘书，让秘书去整理。", "explanation": "这里应该用〈交给〉。错置表示放错地方，不能带「给」引出接收的人。"}, {"text": "他把妈妈错置在沙发上，让她休息。", "explanation": "这里应该用〈搀扶〉。错置只用于物品放错地方，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把文件错置了在档案柜里。", "corrected_sentence": "她把文件错置在了档案柜里。", "error_description": "错误：「错置了在」，动态助词「了」被放在了补语「在」之前。正确：「错置在了」，「了」应紧跟在补语「在」之后，表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把车钥匙错置了三个次，之后就换了个地方存放。", "corrected_sentence": "他把车钥匙错置了三次，之后就换了个地方存放。", "error_description": "错误：「三个次」，动作次数的量词应用「次」，不能用「个」。正确：「错置了三次」，直接用「次」计数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
