INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13149, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物所包含的意义或深层含义。", "primary_collocate": null, "pronunciation": "yì hán", "ipa": "i˥˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "因此，自制堆肥不仅是一项园艺辅助技术，更是一种具哲学意涵的生活实践。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这首诗有很深的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能解释这句话的意涵吗？", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色在中国文化里有特别的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的意涵让人想了很久。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了这个故事的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还不懂这个节日的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个传统习俗都有自己的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字有美好的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话里藏着另一层意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层意涵", "label": "量词"}], "register": "书面", "sense_fingerprint": "事物所含的深层意义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意涵", "is_correct": true, "explanation": "「意涵」指事物所包含的意义，「具哲学意涵」修饰「生活实践」。"}, {"text": "身高", "is_correct": false, "explanation": "语义：「身高」是人或物的高度，不能说「具哲学身高」。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」是交易中的钱数，与哲学内涵无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」指重量，不能用来修饰「哲学」。"}], "explanations": {"意涵": "「意涵」指事物所包含的意义，「具哲学意涵」修饰「生活实践」。", "身高": "语义：「身高」是人或物的高度，不能说「具哲学身高」。", "价格": "语义：「价格」是交易中的钱数，与哲学内涵无关。", "体重": "搭配：「体重」指重量，不能用来修饰「哲学」。"}, "sentence_index": 0, "correct_answer": "意涵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我的一点意涵。", "explanation": "这里应该用〈心意〉。意涵指事物所包含的意义，表示送礼或示好的诚意要用〈心意〉。"}, {"text": "这道汤的意涵很鲜。", "explanation": "这里应该用〈味道〉。意涵指事物包含的意义，不能用「鲜」来形容。"}, {"text": "这条路的意涵很长。", "explanation": "这里应该用〈长度〉。意涵是抽象的内容，不能用「长」来衡量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意涵", "is_correct": true, "explanation": "「意涵」指节日所包含的意义，与「我还不懂这个节日的」的语境一致。"}, {"text": "尺码", "is_correct": false, "explanation": "搭配：「尺码」指衣物或鞋的大小，不能用于节日。"}, {"text": "体积", "is_correct": false, "explanation": "语义：「体积」指物体占据的空间，与节日的含义不符。"}, {"text": "腰围", "is_correct": false, "explanation": "语义：「腰围」指人的腰部尺寸，不能用于节日。"}], "explanations": {"意涵": "「意涵」指节日所包含的意义，与「我还不懂这个节日的」的语境一致。", "尺码": "搭配：「尺码」指衣物或鞋的大小，不能用于节日。", "体积": "语义：「体积」指物体占据的空间，与节日的含义不符。", "腰围": "语义：「腰围」指人的腰部尺寸，不能用于节日。"}, "sentence_index": 6, "correct_answer": "意涵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的意涵很鲜艳。", "explanation": "这里应该用〈颜色〉。意涵是抽象的意义，不能用「鲜艳」形容。"}, {"text": "这辆车的意涵很快。", "explanation": "这里应该用〈速度〉。意涵不能以速度来描述。"}, {"text": "这杯咖啡的意涵很烫。", "explanation": "这里应该用〈温度〉。意涵是抽象的内容，不能用「烫」来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个仪式有一只隐藏的意涵。", "corrected_sentence": "这个仪式有一层隐藏的意涵。", "error_description": "错误：量词用错。「意涵」应使用量词「层」，「只」用于动物或小件物品。正确是「一层意涵」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些图案有一颗深的意涵。", "corrected_sentence": "这些图案有一层深的意涵。", "error_description": "错误：量词用错。「意涵」应使用量词「层」，「颗」用于颗粒状的东西。正确是「一层深的意涵」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
