INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13151, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过操作、展示等方式，将事物或过程呈现出来，供人观看或学习。", "primary_collocate": null, "pronunciation": "yǎn shì", "ipa": "jɛn˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "它在微观层面演示了可持续生活的可行性，将抽象的环保理念转化为每日可操作的仪式。", "target_word": "演示", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师给我们演示这个实验。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理在会上演示了新产品。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手机演示怎么做蛋糕。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师向客户演示新软件。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给大家演示如何急救。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你再演示一遍，好吗？", "target_word": "演示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个视频演示了机器的工作过程。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把整个过程演示给我们看。", "target_word": "演示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师正在黑板前演示解题步骤。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "演示了", "label": "完成体"}, {"form": "演示过", "label": "经历体"}, {"form": "演示演示", "label": "重叠"}, {"form": "演示文稿", "label": "复合词"}], "register": "中性", "sense_fingerprint": "演示：通过操作展示，把事物或过程呈现给人看、供人学习", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14c65f7f-0b0a-4240-89c9-7a856accbf3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13151, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演示", "is_correct": true, "explanation": "演示：通过操作、展示等方式，把事物或过程呈现出来，供人观看或学习。"}, {"text": "厌世", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是厌恶世事。"}, {"text": "仰视", "is_correct": false, "explanation": "yǎng 与 yǎn 韵母不同（ang 与 an），意思是抬头向上看。"}, {"text": "岩石", "is_correct": false, "explanation": "yán 与 yǎn 声调不同，shí 与 shì 声调也不同，意思是岩石。"}], "explanations": {"演示": "演示：通过操作、展示等方式，把事物或过程呈现出来，供人观看或学习。", "厌世": "yàn（第四声）与 yǎn（第三声）声调不同，意思是厌恶世事。", "仰视": "yǎng 与 yǎn 韵母不同（ang 与 an），意思是抬头向上看。", "岩石": "yán 与 yǎn 声调不同，shí 与 shì 声调也不同，意思是岩石。"}, "sentence_index": null, "correct_answer": "演示"}, "level_3": {"options": [{"text": "演示", "is_correct": true, "explanation": "正确：「演示」指通过操作把过程呈现出来，与「展示可行性」的语境相符。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：「饲养」的对象是动物，不能用于「可行性」。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」含有讥讽的意思，与「呈现可行性」的语境不符。"}, {"text": "批发", "is_correct": false, "explanation": "搭配：「批发」针对的是商品，不能用于「可行性」。"}], "explanations": {"演示": "正确：「演示」指通过操作把过程呈现出来，与「展示可行性」的语境相符。", "饲养": "搭配：「饲养」的对象是动物，不能用于「可行性」。", "嘲笑": "语义：「嘲笑」含有讥讽的意思，与「呈现可行性」的语境不符。", "批发": "搭配：「批发」针对的是商品，不能用于「可行性」。"}, "sentence_index": 0, "correct_answer": "演示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在舞台上演示了一个老人。", "explanation": "这里应该用〈扮演〉。演示指展示操作或过程，不能用来指在舞台上扮演角色。"}, {"text": "他向大家演示了昨天的天气情况。", "explanation": "这里应该用〈汇报〉。演示指通过操作把过程展示出来，叙说天气等已发生的情况要用汇报。"}, {"text": "他向我演示了让我先走的意思。", "explanation": "这里应该用〈示意〉。演示指把过程展示给人看，用手势传递意思要说示意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13151, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "演示", "is_correct": true, "explanation": "演示：通过操作、展示等方式，把事物或过程呈现出来，供人观看或学习。"}, {"text": "延时", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，shí 与 shì 声调也不同，意思是延长时间。"}, {"text": "厌食", "is_correct": false, "explanation": "yàn 与 yǎn、shí 与 shì 声调都不同，意思是厌恶进食。"}, {"text": "演戏", "is_correct": false, "explanation": "xì 与 shì 声母不同（x 与 sh），意思是表演戏剧。"}], "explanations": {"演示": "演示：通过操作、展示等方式，把事物或过程呈现出来，供人观看或学习。", "延时": "yán（第二声）与 yǎn（第三声）声调不同，shí 与 shì 声调也不同，意思是延长时间。", "厌食": "yàn 与 yǎn、shí 与 shì 声调都不同，意思是厌恶进食。", "演戏": "xì 与 shì 声母不同（x 与 sh），意思是表演戏剧。"}, "sentence_index": null, "correct_answer": "演示"}, "level_3": {"options": [{"text": "演示", "is_correct": true, "explanation": "正确：「演示」的动作可以重复进行，「再演示一遍」即请对方再做一次展示。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：「哭泣」是情绪表现，与「请对方再做一遍」的请求无关。"}, {"text": "消失", "is_correct": false, "explanation": "语义：「消失」指不再存在，不是可以请对方再做一遍的动作。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：「诞生」指新事物出现，不是可以请对方再做一遍的动作。"}], "explanations": {"演示": "正确：「演示」的动作可以重复进行，「再演示一遍」即请对方再做一次展示。", "哭泣": "语义：「哭泣」是情绪表现，与「请对方再做一遍」的请求无关。", "消失": "语义：「消失」指不再存在，不是可以请对方再做一遍的动作。", "诞生": "语义：「诞生」指新事物出现，不是可以请对方再做一遍的动作。"}, "sentence_index": 6, "correct_answer": "演示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在走廊上演示了那个调皮的学生。", "explanation": "这里应该用〈批评〉。演示的对象是事物或过程，不能用于人。"}, {"text": "店员耐心地演示了这笔账单。", "explanation": "这里应该用〈结算〉。演示指展示操作，核对并付清账款要说结算。"}, {"text": "前台仔细地演示了客人的名字。", "explanation": "这里应该用〈登记〉。演示不用于记录信息，把客人的名字记下来要说登记。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你能再演示一下这只动作吗？", "corrected_sentence": "你能再演示一下这个动作吗？", "error_description": "错误：「这只动作」，「动作」的量词用错。「只」多用于动物或成对物品中的一个，「动作」应用量词「个」，正确说法是「这个动作」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师上周演示着这个实验，所以大家都懂了。", "corrected_sentence": "老师上周演示过这个实验，所以大家都懂了。", "error_description": "错误：「演示着」，进行体「着」表示动作正在进行，与表示过去时间的「上周」不相符。正确：「演示过」，「过」表示曾经做过这件事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13152, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喧闹", "is_correct": true, "explanation": "正确答案。“喧闹”指声音大、嘈杂，与“静默”（安静无声）相对。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”描述光线，与声音无关，和“静默”没有反义关系。"}, {"text": "冰冷", "is_correct": false, "explanation": "“冰冷”描述温度或态度，与“静默”不是反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”描述速度，与“静默”没有反义关系。"}], "correct_answer": "喧闹", "explanations": {"喧闹": "正确答案。“喧闹”指声音大、嘈杂，与“静默”（安静无声）相对。", "明亮": "“明亮”描述光线，与声音无关，和“静默”没有反义关系。", "冰冷": "“冰冷”描述温度或态度，与“静默”不是反义关系。", "迅速": "“迅速”描述速度，与“静默”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13152, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "嘈杂", "is_correct": true, "explanation": "正确答案。“嘈杂”指声音杂乱、吵闹，与“静默”相对。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”描述温度或感觉，与“静默”没有反义关系。"}, {"text": "光滑", "is_correct": false, "explanation": "“光滑”描述表面的质地，与“静默”没有反义关系。"}, {"text": "缓慢", "is_correct": false, "explanation": "“缓慢”描述速度，与“静默”没有反义关系。"}], "correct_answer": "嘈杂", "explanations": {"嘈杂": "正确答案。“嘈杂”指声音杂乱、吵闹，与“静默”相对。", "温暖": "“温暖”描述温度或感觉，与“静默”没有反义关系。", "光滑": "“光滑”描述表面的质地，与“静默”没有反义关系。", "缓慢": "“缓慢”描述速度，与“静默”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13152, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指保持安静，不发出声音；也指不出声地做某事。", "primary_collocate": null, "pronunciation": "jìng mò", "ipa": "tɕiŋ˥˩ mwo˥˩", "syllable_count": 2, "sentences": [{"text": "倘若此趋势持续，2026年或将见证一场静默的认知民主化浪潮——个体不再被算法凝视，而是通过可信赖的代理，主动参与数字身份的建构与协商。", "target_word": "静默", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当千万个家庭共同参与这一静默的物质转化，其累积效应或将重塑我们与自然物质交换的文明逻辑。", "target_word": "静默", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "夜晚的小村庄一片静默。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他静默的样子让大家有点担心。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里静默了很久，没人回答。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她静默地坐在窗边看雨。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪后的山谷格外静默。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人静默的眼神里有很多故事。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会场上突然变得静默。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖面静默，只有风轻轻吹过。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "静默地", "label": "状语形式"}, {"form": "靜默", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容安静无声，或悄悄地不出声地进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '793f12b2-1a45-4e9f-b63f-7c7c045ff77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13152, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "静默", "is_correct": true, "explanation": "正确答案。静默 jìng mò：保持安静，不发出声音。"}, {"text": "寂寞", "is_correct": false, "explanation": "jì（第四声）与 jìng 的区别在于韵尾 -ng 有无。寂寞指孤独、冷清，不指安静无声。"}, {"text": "京墨", "is_correct": false, "explanation": "声调混淆：京墨（jīng mò）与静默（jìng mò）首音的声母韵母相同，只在声调上不同（一声与四声）。京墨指北京产的墨锭。"}, {"text": "清末", "is_correct": false, "explanation": "首音 qīng 与 jìng 的声母不同（q 送气，j 不送气），声调也不同。清末指清朝后期。"}], "explanations": {"静默": "正确答案。静默 jìng mò：保持安静，不发出声音。", "寂寞": "jì（第四声）与 jìng 的区别在于韵尾 -ng 有无。寂寞指孤独、冷清，不指安静无声。", "京墨": "声调混淆：京墨（jīng mò）与静默（jìng mò）首音的声母韵母相同，只在声调上不同（一声与四声）。京墨指北京产的墨锭。", "清末": "首音 qīng 与 jìng 的声母不同（q 送气，j 不送气），声调也不同。清末指清朝后期。"}, "sentence_index": null, "correct_answer": "静默"}, "level_3": {"options": [{"text": "静默", "is_correct": true, "explanation": "正确答案。“一场静默的认知民主化浪潮”指这场变化在无声中悄然发生，静默在此修饰“浪潮”。"}, {"text": "被动", "is_correct": false, "explanation": "语义：“被动”与后文“主动参与”相反，不能修饰这里描述的积极参与过程。"}, {"text": "方形", "is_correct": false, "explanation": "语义：“方形”是几何形状，不能修饰社会运动。"}, {"text": "私密", "is_correct": false, "explanation": "语义：“私密”指不公开的个人事务，与“民主化”所指的社会性公开参与相矛盾。"}], "explanations": {"静默": "正确答案。“一场静默的认知民主化浪潮”指这场变化在无声中悄然发生，静默在此修饰“浪潮”。", "被动": "语义：“被动”与后文“主动参与”相反，不能修饰这里描述的积极参与过程。", "方形": "语义：“方形”是几何形状，不能修饰社会运动。", "私密": "语义：“私密”指不公开的个人事务，与“民主化”所指的社会性公开参与相矛盾。"}, "sentence_index": 0, "correct_answer": "静默"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，她的心情很静默。", "explanation": "这里应该用〈平静〉。“静默”指不出声，形容心情要用“平静”，“静默”不能用来说心情。"}, {"text": "大家静默地热烈讨论，场面一下子很热闹。", "explanation": "这里表示热闹、有声响，应该用〈喧闹〉。“静默”指不出声，与这样的场面相反。"}, {"text": "他静默地唱完了这首歌，大家都很感动。", "explanation": "这里应该用〈轻声〉。“静默”指完全不出声，与“唱歌”需要发声相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "静默", "is_correct": true, "explanation": "正确答案。“格外静默”描述雪后山谷的无声状态。"}, {"text": "喧闹", "is_correct": false, "explanation": "语义：“喧闹”指声音大、嘈杂，与“雪后”的寂静情境相反。"}, {"text": "繁华", "is_correct": false, "explanation": "搭配：“繁华”多用于街市、城镇，不用于形容山谷。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”形容温度极高，与“雪后”的寒冷情境相矛盾。"}], "explanations": {"静默": "正确答案。“格外静默”描述雪后山谷的无声状态。", "喧闹": "语义：“喧闹”指声音大、嘈杂，与“雪后”的寂静情境相反。", "繁华": "搭配：“繁华”多用于街市、城镇，不用于形容山谷。", "滚烫": "语义：“滚烫”形容温度极高，与“雪后”的寒冷情境相矛盾。"}, "sentence_index": 6, "correct_answer": "静默"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台新收音机静默地播放着音乐。", "explanation": "这里表示发出声响，应该用〈响亮〉。“静默”指不出声，不能用来形容播放音乐。"}, {"text": "鞭炮声中，整条街道静默得很。", "explanation": "这里表示热闹非凡，应该用〈喧闹〉。“静默”指无声，与鞭炮声中的街道相反。"}, {"text": "她静默地大声哭了起来。", "explanation": "这里表示哭得很大声，应该用〈嚎啕〉。“静默”的无声义与此相反，不能用来形容哭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会场里一个静默，没有人说话。", "corrected_sentence": "会场里一片静默，没有人说话。", "error_description": "“静默”前的量词应用“片”，写作“一片静默”；这里用“个”不自然，不符合“静默”作为一片寂静场面的说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他静默的站在门口，没有说话。", "corrected_sentence": "他静默地站在门口，没有说话。", "error_description": "修饰动词“站”的状语应用“地”，写作“静默地站”。用“的”会把“静默”当作形容词修饰名词，这里不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
