INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用布料制成的袋子，常用于装物品或购物。", "primary_collocate": null, "pronunciation": "bù dài zi", "ipa": "pu˥˩ taɪ˥˩ tsɨ", "syllable_count": 3, "sentences": [{"text": "人们可以用布袋子，布袋子可以洗，可以再用。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我去超市买东西，带了一个布袋子。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个布袋子很结实，可以装很多书。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把苹果装进了那个蓝色的布袋子。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市不给塑料袋，所以大家都用布袋子。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布袋子脏了，我把它洗干净了。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的布袋子上有一只可爱的小猫。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去买菜的时候，总是拿着布袋子。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个布袋子是奶奶用旧衣服做的。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的布袋子里有两本书和一瓶水。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "布袋", "label": "复合"}], "register": "中性", "sense_fingerprint": "用布料制成、可装物品或购物的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '774c926e-fb1f-4488-8915-497812d93261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "布袋子", "is_correct": true, "explanation": "与句中“布袋子”相同。“可以洗、可以再用”说的是布做的袋子。"}, {"text": "纸袋子", "is_correct": false, "explanation": "体貌：纸袋子是纸做的，不能水洗，与“可以洗”的语境冲突。"}, {"text": "皮包", "is_correct": false, "explanation": "语义：皮包多为皮革做的，不能像布袋子那样水洗，与“可以洗”不合。"}, {"text": "纸箱", "is_correct": false, "explanation": "语义：纸箱是硬纸板做的，不能水洗，与“可以洗”的语境冲突。"}], "explanations": {"布袋子": "与句中“布袋子”相同。“可以洗、可以再用”说的是布做的袋子。", "纸袋子": "体貌：纸袋子是纸做的，不能水洗，与“可以洗”的语境冲突。", "皮包": "语义：皮包多为皮革做的，不能像布袋子那样水洗，与“可以洗”不合。", "纸箱": "语义：纸箱是硬纸板做的，不能水洗，与“可以洗”的语境冲突。"}, "sentence_index": 0, "correct_answer": "布袋子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把手机放在上衣的布袋子里。", "explanation": "这里应该用〈口袋〉。口袋是衣服上缝的部分，布袋子是独立的袋子，不能说“上衣的布袋子”。"}, {"text": "我买了一条布袋子。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，布袋子不能用“条”。"}, {"text": "我买了一张布袋子。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等扁平的东西，布袋子不能用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "布袋子", "is_correct": true, "explanation": "与句中“布袋子”相同。“她的……上有一只可爱的小猫”说的是袋子上的图案。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是能让小猫待在上面的东西，“她的海洋上”搭配不上。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以摆放图案的表面，与“上有一只可爱的小猫”冲突。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字”上不能有一只实体小猫，“名字上有一只小猫”不成立。"}], "explanations": {"布袋子": "与句中“布袋子”相同。“她的……上有一只可爱的小猫”说的是袋子上的图案。", "海洋": "语义：海洋不是能让小猫待在上面的东西，“她的海洋上”搭配不上。", "空气": "语义：空气不是可以摆放图案的表面，与“上有一只可爱的小猫”冲突。", "名字": "搭配：“名字”上不能有一只实体小猫，“名字上有一只小猫”不成立。"}, "sentence_index": 6, "correct_answer": "布袋子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他手里拿着一根布袋子。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，布袋子不能用“根”。"}, {"text": "他买了一双布袋子。", "explanation": "这里应该用〈个〉。“双”用于成对的东西，一个布袋子不能说“一双”。"}, {"text": "他有一本布袋子，里面装着两本书。", "explanation": "这里应该用〈个〉。“本”用于书籍、本子等，布袋子不能用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一副布袋子。", "corrected_sentence": "我买了一个布袋子。", "error_description": "布袋子的量词应该用“个”，不能用“副”。“副”用于成对或成套的东西，这里说“一副布袋子”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一把布袋子。", "corrected_sentence": "我买了一个布袋子。", "error_description": "布袋子的量词应该用“个”，不能用“把”。“把”用于有柄或可握持的东西，如伞、刀，布袋子不能用“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
