INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用水或溶剂等去除物体上的污垢。", "primary_collocate": null, "pronunciation": "xǐ", "ipa": "ɕi˨˩˦", "syllable_count": 1, "sentences": [{"text": "人们可以用布袋子，布袋子可以洗，可以再用。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "吃饭以前，你要先洗手。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太脏了，我想洗一洗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天晚上都要洗碗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子已经洗过两次了。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天洗了车，今天又下雨了。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子不能用热水洗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把青菜洗干净再切。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在河边洗衣服。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服太旧了，洗了很多次，颜色都变了。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗了", "label": "体标"}, {"form": "洗过", "label": "体标"}, {"form": "洗洗", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用水或溶剂去除物体上的污垢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '774c926e-fb1f-4488-8915-497812d93261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "洗", "is_correct": true, "explanation": "洗（xǐ，第三声），意思是用水去除污垢。"}, {"text": "细", "is_correct": false, "explanation": "声调不同：细是 xì（第四声），与 xǐ（第三声）不同，意思是细小。"}, {"text": "吸", "is_correct": false, "explanation": "声调不同：吸是 xī（第一声），与 xǐ（第三声）不同，意思是吸入。"}, {"text": "西", "is_correct": false, "explanation": "声调不同：西是 xī（第一声），与 xǐ（第三声）不同，意思是西方。"}, {"text": "死", "is_correct": false, "explanation": "声母不同：死是 sǐ，s 与 x 不同，声调相同，意思是死亡。"}, {"text": "戏", "is_correct": false, "explanation": "声调不同：戏是 xì（第四声），与 xǐ（第三声）不同，意思是戏剧。"}], "explanations": {"洗": "洗（xǐ，第三声），意思是用水去除污垢。", "细": "声调不同：细是 xì（第四声），与 xǐ（第三声）不同，意思是细小。", "吸": "声调不同：吸是 xī（第一声），与 xǐ（第三声）不同，意思是吸入。", "西": "声调不同：西是 xī（第一声），与 xǐ（第三声）不同，意思是西方。", "死": "声母不同：死是 sǐ，s 与 x 不同，声调相同，意思是死亡。", "戏": "声调不同：戏是 xì（第四声），与 xǐ（第三声）不同，意思是戏剧。"}, "sentence_index": null, "correct_answer": "洗"}, "level_3": {"options": [{"text": "洗", "is_correct": true, "explanation": "与句中“洗”相同，“可以洗，可以再用”说的是用水去除污垢。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔掉的东西不能再用，与“可以再用”矛盾。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉之后不能再用，与“可以再用”矛盾。"}, {"text": "切", "is_correct": false, "explanation": "语义：布袋子若被切开就不能再用，与“可以再用”矛盾。"}], "explanations": {"洗": "与句中“洗”相同，“可以洗，可以再用”说的是用水去除污垢。", "扔": "语义：扔掉的东西不能再用，与“可以再用”矛盾。", "烧": "语义：烧掉之后不能再用，与“可以再用”矛盾。", "切": "语义：布袋子若被切开就不能再用，与“可以再用”矛盾。"}, "sentence_index": 0, "correct_answer": "洗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完步，用毛巾洗汗。", "explanation": "这里应该用〈擦〉。“擦”用于汗、灰尘等，汗不能说“洗”。"}, {"text": "妈妈用熨斗洗了一下裙子。", "explanation": "这里应该用〈熨〉。“熨”是用熨斗把衣服弄平整，不用水；“洗”指用水去除污垢，不能这样用。"}, {"text": "我每天给花洗水。", "explanation": "这里应该用〈浇〉。“浇”用于给花草等浇水，“洗”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "洗", "is_correct": true, "explanation": "洗（xǐ，第三声），意思是用水去除污垢。"}, {"text": "席", "is_correct": false, "explanation": "声调不同：席是 xí（第二声），与 xǐ（第三声）不同，意思是席子。"}, {"text": "系", "is_correct": false, "explanation": "声调不同：系是 xì（第四声），与 xǐ（第三声）不同，意思是系上、联系。"}, {"text": "醒", "is_correct": false, "explanation": "韵母不同：醒是 xǐng，比 xǐ 多了后鼻音 ng，声调相同，意思是醒来。"}], "explanations": {"洗": "洗（xǐ，第三声），意思是用水去除污垢。", "席": "声调不同：席是 xí（第二声），与 xǐ（第三声）不同，意思是席子。", "系": "声调不同：系是 xì（第四声），与 xǐ（第三声）不同，意思是系上、联系。", "醒": "韵母不同：醒是 xǐng，比 xǐ 多了后鼻音 ng，声调相同，意思是醒来。"}, "sentence_index": null, "correct_answer": "洗"}, "level_3": {"options": [{"text": "洗", "is_correct": true, "explanation": "与句中“洗”相同，“不能用热水洗”说的是用热水去除杯子上的污垢。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的对象不是杯子这类器皿，“这种杯子不能用热水切”搭配不上。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是把东西扔到地上，与用热水清洁的动作不相符。"}, {"text": "剪", "is_correct": false, "explanation": "配价：“剪”需要剪刀之类的工具，“用热水剪”不成立。"}], "explanations": {"洗": "与句中“洗”相同，“不能用热水洗”说的是用热水去除杯子上的污垢。", "切": "搭配：“切”的对象不是杯子这类器皿，“这种杯子不能用热水切”搭配不上。", "摔": "语义：“摔”是把东西扔到地上，与用热水清洁的动作不相符。", "剪": "配价：“剪”需要剪刀之类的工具，“用热水剪”不成立。"}, "sentence_index": 6, "correct_answer": "洗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天晚上都在手上洗护手霜。", "explanation": "这里应该用〈涂〉。“涂”用于把护手霜抹在皮肤上；“洗”指用水去除污垢，不能用于护手霜。"}, {"text": "妈妈在锅里洗汤，等会儿就能喝了。", "explanation": "这里应该用〈煮〉。“煮”用于加热烹饪食物，汤不能说“洗”。"}, {"text": "她用手洗眼泪，不让别人看见。", "explanation": "这里应该用〈抹〉。“抹”用于擦去眼泪、药膏等，眼泪不能说“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋脏了，我得把它洗。", "corrected_sentence": "这双鞋脏了，我得把它洗干净。", "error_description": "“把”字句中的“洗”后面要有补语，说“把它洗干净”才完整，只说“把它洗”不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把被子洗了干净了。", "corrected_sentence": "他把被子洗干净了。", "error_description": "「了」位置错误：结果补语「干净」与动词「洗」之间不能插入「了」，「洗了干净」不成立，应说「他把被子洗干净了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收钱", "is_correct": true, "explanation": "正确：收钱指接受费用，与“付钱”的意思正相反。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指随意走动，与“付钱”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "无关：“读书”指阅读，与“付钱”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清理，与“付钱”没有反义关系。"}], "correct_answer": "收钱", "explanations": {"收钱": "正确：收钱指接受费用，与“付钱”的意思正相反。", "散步": "无关：“散步”指随意走动，与“付钱”没有反义关系。", "读书": "无关：“读书”指阅读，与“付钱”没有反义关系。", "打扫": "无关：“打扫”指清理，与“付钱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收钱", "is_correct": true, "explanation": "正确：收钱指接受费用，与“付钱”的意思正相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”指发出乐音，与“付钱”没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "无关：“洗澡”指清洁身体，与“付钱”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "无关：“跑步”指快速移动，与“付钱”没有反义关系。"}], "correct_answer": "收钱", "explanations": {"收钱": "正确：收钱指接受费用，与“付钱”的意思正相反。", "唱歌": "无关：“唱歌”指发出乐音，与“付钱”没有反义关系。", "洗澡": "无关：“洗澡”指清洁身体，与“付钱”没有反义关系。", "跑步": "无关：“跑步”指快速移动，与“付钱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿出钱来支付费用。", "primary_collocate": null, "pronunciation": "fù qián", "ipa": "fu˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "顾客要付钱才能拿到袋子。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "吃完饭，爸爸去前面付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住酒店要先付钱吗？", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐出租车下车时要付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以用手机付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了带钱包，没办法付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完病，我们先去窗口付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我请客，你不用付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮我付钱，我回头还他。", "target_word": "付钱", "complexity_tier": "T3", "furigana": "péng yǒu bāng wǒ fù qián, wǒ huí tóu huán tā.", "sentence_source": "generated"}, {"text": "租房子要提前一个月付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了钱", "label": "体标"}, {"form": "付过钱", "label": "体标"}], "register": "中性", "sense_fingerprint": "拿出钱支付某种费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea494939-a4c9-431c-bc0d-cd219d6a4140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付钱", "is_correct": true, "explanation": "正确：顾客拿袋子之前要支付费用，符合“付钱”的意思。"}, {"text": "收钱", "is_correct": false, "explanation": "语义：顾客是付钱的一方，不能说“收钱”。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与拿到袋子没有逻辑关系，句子说不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“拿到袋子”前不说“洗澡”，两者不搭配。"}], "explanations": {"付钱": "正确：顾客拿袋子之前要支付费用，符合“付钱”的意思。", "收钱": "语义：顾客是付钱的一方，不能说“收钱”。", "唱歌": "语义：唱歌与拿到袋子没有逻辑关系，句子说不通。", "洗澡": "搭配：“拿到袋子”前不说“洗澡”，两者不搭配。"}, "sentence_index": 0, "correct_answer": "付钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他中了彩票，付钱了一百万。", "explanation": "这里应该用〈得到〉。「付钱」指支付费用，中彩票得到的钱要用「得到」。"}, {"text": "他靠写书付钱，生活很好。", "explanation": "这里应该用〈赚〉。付钱是支出，靠写书获得收入要用“赚”。"}, {"text": "我们向灾区付钱。", "explanation": "这里应该用〈捐〉。付钱指为买卖或服务支付费用，无偿给灾区钱款要用“捐”，不能说付钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付钱", "is_correct": true, "explanation": "正确：看完病后先去窗口付钱，符合语境。"}, {"text": "听歌", "is_correct": false, "explanation": "语义：去窗口听歌与“看完病”的语境无关，句子不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：在窗口睡觉不合情理，与“先去”办事的语境不符。"}, {"text": "种花", "is_correct": false, "explanation": "搭配：窗口不跟“种花”搭配，种花需要土地。"}], "explanations": {"付钱": "正确：看完病后先去窗口付钱，符合语境。", "听歌": "语义：去窗口听歌与“看完病”的语境无关，句子不通。", "睡觉": "语义：在窗口睡觉不合情理，与“先去”办事的语境不符。", "种花": "搭配：窗口不跟“种花”搭配，种花需要土地。"}, "sentence_index": 6, "correct_answer": "付钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师付钱给我，夸我考了满分。", "explanation": "这里应该用〈奖赏〉。付钱是为买卖或服务支付费用，夸奖学生不是交易，不能说付钱。"}, {"text": "强盗抢钱时付了钱。", "explanation": "这里应该用〈掠夺〉。付钱是按规定支付费用，强行夺取钱财要用“掠夺”，不能说“付钱”。"}, {"text": "小偷偷东西时，也付了钱。", "explanation": "这里应该用〈盗窃〉。付钱是合法支付，盗窃是非法拿走别人财物，不能说付钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "离开超市前，我们要先付了钱。", "corrected_sentence": "离开超市前，我们要先付钱。", "error_description": "“付”和“钱”之间多了“了”。“要先”表示尚未发生的必要动作，不能用表示完成的“了”。应为“要先付钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在咖啡厅坐了一会儿，我们就去付钱着。", "corrected_sentence": "在咖啡厅坐了一会儿，我们就去付钱。", "error_description": "“付钱”后多了“着”。“去”后面接的是即将进行的动作，动词后不能加表示持续的“着”。应为“我们就去付钱。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违反", "is_correct": true, "explanation": "反义：「违反」与「遵守」相对，指不依规定行事。"}, {"text": "挑选", "is_correct": false, "explanation": "无关：「挑选」与「遵守」没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：「修理」与「遵守」没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：「散步」与「遵守」没有反义关系。"}], "correct_answer": "违反", "explanations": {"违反": "反义：「违反」与「遵守」相对，指不依规定行事。", "挑选": "无关：「挑选」与「遵守」没有反义关系。", "修理": "无关：「修理」与「遵守」没有反义关系。", "散步": "无关：「散步」与「遵守」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
