INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依照规定或命令行动，不违反。", "primary_collocate": null, "pronunciation": "zūn shǒu", "ipa": "tswən˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "政府会检查商店有没有遵守规定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "开车的人都要遵守交通规则。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生应该遵守学校的规定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民要遵守法律。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客必须遵守景区的规定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的人都遵守这条规定。", "target_word": "遵守", "complexity_tier": "T3", "furigana": "zūn shǒu", "sentence_source": "generated"}, {"text": "比赛时，大家都要遵守规则。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人必须遵守上级的命令。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家遵守图书馆的规定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机遵守交通规则，路上就安全多了。", "target_word": "遵守", "complexity_tier": "T3", "furigana": "zūn shǒu", "sentence_source": "generated"}], "morphological_forms": [{"form": "遵守了", "label": "体标"}, {"form": "遵守着", "label": "体标"}, {"form": "遵守过", "label": "体标"}], "register": "中性", "sense_fingerprint": "依照规定、法律或命令行动而不违反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea494939-a4c9-431c-bc0d-cd219d6a4140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遵守", "is_correct": true, "explanation": "正确。「遵守规定」表示依照规定行事，句中“检查有没有……规定”正是考察这一点。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：「提高」用于水平、质量，不能说提高规定。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：句子问的是商店是否依规定办事，「喜欢」表示好感，与“检查”的语境不合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」指修补器物，不能用于规定。"}], "explanations": {"遵守": "正确。「遵守规定」表示依照规定行事，句中“检查有没有……规定”正是考察这一点。", "提高": "搭配：「提高」用于水平、质量，不能说提高规定。", "喜欢": "语义：句子问的是商店是否依规定办事，「喜欢」表示好感，与“检查”的语境不合。", "修理": "语义：「修理」指修补器物，不能用于规定。"}, "sentence_index": 0, "correct_answer": "遵守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要遵守房间的干净。", "explanation": "这里应该用〈保持〉。「遵守」的对象是规定、规则或要求，干净的环境要用「保持」。"}, {"text": "孩子应该遵守父母。", "explanation": "这里应该用〈服从〉。「遵守」的对象是规定、法律或命令，指向人时要用「服从」。"}, {"text": "过马路要遵守安全。", "explanation": "这里应该用〈注意〉。「遵守」搭配规则、规定，说到安全时要用「注意安全」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遵守", "is_correct": true, "explanation": "正确。「遵守规则」表示依规则行事，符合比赛时的语境。"}, {"text": "搬", "is_correct": false, "explanation": "配价：「搬」要求有具体的物体作宾语，不能搬规则。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」指燃烧，与规则无关。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」指烹调食物，与规则无关。"}], "explanations": {"遵守": "正确。「遵守规则」表示依规则行事，符合比赛时的语境。", "搬": "配价：「搬」要求有具体的物体作宾语，不能搬规则。", "烧": "语义：「烧」指燃烧，与规则无关。", "煮": "语义：「煮」指烹调食物，与规则无关。"}, "sentence_index": 6, "correct_answer": "遵守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要遵守公共财物。", "explanation": "这里应该用〈爱护〉。「遵守」的对象是规定，爱护物品要用「爱护」。"}, {"text": "他已经遵守了这门技术。", "explanation": "这里应该用〈掌握〉。「遵守」用于规定、规则，学会技术、知识要用「掌握」。"}, {"text": "我们要遵守老师的帮助。", "explanation": "这里应该用〈感谢〉。「遵守」指依照规定行事，对别人的帮助要说「感谢」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天没遵守了学校的约定。", "corrected_sentence": "他昨天没遵守学校的约定。", "error_description": "「没」否定动作时，动词后不能再加「了」。错误在“遵守”后面的“了”；应说「没遵守」，去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他遵守很认真。", "corrected_sentence": "他遵守得很认真。", "error_description": "动词带程度补语时，中间要加「得」。应说「遵守得很认真」，不能说「遵守很认真」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
