INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体出现不健康的状态，比如得了感冒、发烧等疾病。", "primary_collocate": null, "pronunciation": "shēng bìng", "ipa": "ʂɤŋ˥ piŋ˥˩", "syllable_count": 2, "sentences": [{"text": "动物会吃这些垃圾，然后生病。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他昨天生病了，没来上课。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生病的时候，妈妈照顾我。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，小心别生病。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病了，妈妈很着急。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生病了，今天在家休息。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常不吃早饭，容易生病。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很少生病。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶生病住院了。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你生病了就要去看医生。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生病了", "label": "体标"}, {"form": "生了病", "label": "离合"}, {"form": "生过病", "label": "离合"}], "register": "中性", "sense_fingerprint": "人或动物得病，身体不健康", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea494939-a4c9-431c-bc0d-cd219d6a4140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生病", "is_correct": true, "explanation": "“生病”与前句“吃垃圾”的因果相合，表示身体不健康。"}, {"text": "康复", "is_correct": false, "explanation": "语义：“康复”指病后恢复健康，前句并没有生病，“然后康复”说不通。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”的主体应是人，“动物上学”说不通。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”的主语一般是学生，不能说“动物毕业”。"}], "explanations": {"生病": "“生病”与前句“吃垃圾”的因果相合，表示身体不健康。", "康复": "语义：“康复”指病后恢复健康，前句并没有生病，“然后康复”说不通。", "上学": "语义：“上学”的主体应是人，“动物上学”说不通。", "毕业": "搭配：“毕业”的主语一般是学生，不能说“动物毕业”。"}, "sentence_index": 0, "correct_answer": "生病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他切菜时生病了，手流了很多血。", "explanation": "这里应该用〈割伤〉。“生病”指身体因疾病不健康，切菜划伤是外伤，要说“割伤”。"}, {"text": "他打篮球时生病了，腿摔得不能动。", "explanation": "这里应该用〈摔伤〉。“生病”不用于摔倒造成的伤，要说“摔伤”。"}, {"text": "他被车撞后生病了，腿上擦破了一大片皮。", "explanation": "这里应该用〈撞伤〉。“生病”不用于车祸造成的伤，要说“撞伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生病", "is_correct": true, "explanation": "“生病”与“不吃早饭”的结果相合，表示身体不健康。"}, {"text": "出院", "is_correct": false, "explanation": "语义：“出院”指离开医院，句中没有住院的前提，“容易出院”说不通。"}, {"text": "升职", "is_correct": false, "explanation": "搭配：“升职”是职场上的晋升，主语应是工作的人，与“不吃早饭”没有关系。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，与“不吃早饭”的结果不合。"}], "explanations": {"生病": "“生病”与“不吃早饭”的结果相合，表示身体不健康。", "出院": "语义：“出院”指离开医院，句中没有住院的前提，“容易出院”说不通。", "升职": "搭配：“升职”是职场上的晋升，主语应是工作的人，与“不吃早饭”没有关系。", "退休": "语义：“退休”指离开工作岗位，与“不吃早饭”的结果不合。"}, "sentence_index": 6, "correct_answer": "生病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她跑步时生病了，脚踝肿得很厉害。", "explanation": "这里应该用〈扭伤〉。“生病”指身体因疾病不舒服，跑步时扭到脚是外伤，要说“扭伤”。"}, {"text": "他从楼梯上摔下来，生病了，膝盖擦破了一大片皮。", "explanation": "这里应该用〈摔伤〉。“生病”不用于摔倒造成的伤，要说“摔伤”。"}, {"text": "他被热汤烫到，生病了，手上起了水泡。", "explanation": "这里应该用〈烫伤〉。“生病”不用于热汤造成的伤，要说“烫伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上周很生病。", "corrected_sentence": "我上周生病。", "error_description": "“很”是程度副词，不能修饰“生病”这类动作，“很生病”不通。去掉“很”，应为“我上周生病。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他前天就生病了一场。", "corrected_sentence": "他前天就病了一场。", "error_description": "“生病”是离合词，不能整体带“了一场”。去掉“生”，应为“他前天就病了一场。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纸袋是一种用纸张制成的袋子，常用于购物或包装物品。", "primary_collocate": null, "pronunciation": "zhǐ dài", "ipa": "ʈʂɻ̩˨˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "人们希望以后用纸袋或布袋。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我把买来的面包放进纸袋里了。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸袋很结实，可以装三本书。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市给了我一个纸袋，不用塑料袋。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用纸袋装着刚烤好的饼干。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨时纸袋容易湿，不能装书。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈提着一个纸袋去上班。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店的纸袋上印着一朵小花。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸袋可以用很多次。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把礼物放在红色的纸袋里。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个纸袋", "label": "量词"}, {"form": "紙袋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用纸张制成、用于购物或包装的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8dcf6e-820e-41d6-966b-7b4656bddf4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纸袋", "is_correct": true, "explanation": "正确：句中“纸袋”与“布袋”并列，都是可以替代塑料袋的环保袋。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是用来装垃圾的，不能与“布袋”并列作为可以替代的袋子。"}, {"text": "一次性餐具", "is_correct": false, "explanation": "语义：“或布袋”要求前后都是袋子，一次性餐具不是用来装东西的袋子。"}, {"text": "囊", "is_correct": false, "explanation": "语域：“囊”是书面语，不用于这种口语化的日常环保提议。"}], "explanations": {"纸袋": "正确：句中“纸袋”与“布袋”并列，都是可以替代塑料袋的环保袋。", "垃圾桶": "语义：垃圾桶是用来装垃圾的，不能与“布袋”并列作为可以替代的袋子。", "一次性餐具": "语义：“或布袋”要求前后都是袋子，一次性餐具不是用来装东西的袋子。", "囊": "语域：“囊”是书面语，不用于这种口语化的日常环保提议。"}, "sentence_index": 0, "correct_answer": "纸袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一张纸袋，装了三本书。", "explanation": "这里应该用〈个〉。纸袋是立体的袋子，量词用“个”；“张”用于纸、桌子等平面物体，不用于纸袋。"}, {"text": "他咬了一口纸袋，觉得很好吃。", "explanation": "这里应该用〈饼干〉。纸袋是用来装东西的，不能吃，“好吃”应用于食物，要说饼干。"}, {"text": "他穿着一个纸袋去上班。", "explanation": "这里应该用〈背〉或〈提〉。“穿”只用于衣服、鞋袜，不能用于袋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸袋", "is_correct": true, "explanation": "正确：“提着”的是一个袋子，纸袋可以拎在手里带去上班。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”是人，不能像袋子一样被“提着”去上班，句意不通。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：“小孩”是人，不能被拎在手里带去上班。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“提”用于能拎在手里的东西，冰箱太大太重，只能说“搬”。"}], "explanations": {"纸袋": "正确：“提着”的是一个袋子，纸袋可以拎在手里带去上班。", "老板": "语义：“老板”是人，不能像袋子一样被“提着”去上班，句意不通。", "小孩": "语义：“小孩”是人，不能被拎在手里带去上班。", "冰箱": "搭配：“提”用于能拎在手里的东西，冰箱太大太重，只能说“搬”。"}, "sentence_index": 6, "correct_answer": "纸袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用纸袋洗澡，洗得很干净。", "explanation": "这里应该用〈肥皂〉。洗澡要用肥皂或沐浴露，纸袋不能用来洗澡。"}, {"text": "他用纸袋扫地，把屋子打扫得很干净。", "explanation": "这里应该用〈扫把〉。扫地要用扫把，纸袋不能用来扫地。"}, {"text": "他用纸袋喝水，一口一口慢慢喝。", "explanation": "这里应该用〈杯子〉。喝水要用杯子，纸袋不能用来盛水喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一张纸袋装了两个苹果。", "corrected_sentence": "他用一个纸袋装了两个苹果。", "error_description": "量词错误：“纸袋”是立体的袋子，量词应用“个”，不能用平面物体的量词“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把饼干装进纸袋上了。", "corrected_sentence": "她把饼干装进纸袋里了。", "error_description": "方位词错误：把东西装进袋子应说“纸袋里”，“上”表示在表面之上，不能说“纸袋上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
