INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13174, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由塑料材料制成的各种产品。", "primary_collocate": null, "pronunciation": "sù liào zhì pǐn", "ipa": "su˥˩ liɑʊ˥˩ ʈʂɻ̩˥˩ pʰin˨˩˦", "syllable_count": 4, "sentences": [{"text": "面对海洋和陆地的生态压力，一次性塑料制品因为不可降解性强、又被广泛使用，已经成为环境治理的重点问题。", "target_word": "塑料制品", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "近年来，许多国家开始通过立法限制使用一次性塑料制品，这是全球趋势的一部分。", "target_word": "塑料制品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家工厂专门生产各种塑料制品。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料制品很轻，也不容易坏。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的塑料制品比纸制品便宜。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把用完的塑料制品放进回收箱。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的塑料制品不能放进火里烧。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定少买塑料制品，多用布袋。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些塑料制品可以回收再利用。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的垃圾里有很多塑料制品。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "塑料製品", "label": "繁体"}, {"form": "一次性塑料制品", "label": "复合"}], "register": "中性", "sense_fingerprint": "塑料制成的各类产品，泛指工业与日常用品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0fbe80-3322-4a2e-a4d7-d218a61d1e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塑料制品", "is_correct": true, "explanation": "正确。“一次性塑料制品”指塑料做的一次性用品，与句中“不可降解性”及“广泛使用”的语境相符。"}, {"text": "纸张", "is_correct": false, "explanation": "语义：纸张可以降解，与句中的“不可降解性”相矛盾。"}, {"text": "木材", "is_correct": false, "explanation": "搭配：“一次性”不修饰木材这类原料，不能说“一次性木材”。"}, {"text": "农作物", "is_correct": false, "explanation": "语义：农作物是种植出来的，不是制成的产品，也不能用“一次性”来修饰。"}], "explanations": {"塑料制品": "正确。“一次性塑料制品”指塑料做的一次性用品，与句中“不可降解性”及“广泛使用”的语境相符。", "纸张": "语义：纸张可以降解，与句中的“不可降解性”相矛盾。", "木材": "搭配：“一次性”不修饰木材这类原料，不能说“一次性木材”。", "农作物": "语义：农作物是种植出来的，不是制成的产品，也不能用“一次性”来修饰。"}, "sentence_index": 0, "correct_answer": "塑料制品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他饿了，就吃了一大口塑料制品。", "explanation": "这里应该用〈面包〉。塑料制品不能吃，吃东西要说具体的食物。"}, {"text": "我买了一张塑料制品。", "explanation": "这里量词应该用〈件〉。〈张〉多用于纸、桌子等扁平的东西，塑料制品应说“一件”。"}, {"text": "他每天开车去塑料制品。", "explanation": "这里应该用〈工厂〉。塑料制品是物品，不是地方，去某处要说地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塑料制品", "is_correct": true, "explanation": "正确。塑料制品遇火会熔化并释放有害烟气，所以不能放进火里烧，符合句中语境。"}, {"text": "木柴", "is_correct": false, "explanation": "语义：木柴本来就是用来烧的，与句中“不能放进火里烧”的意思相反。"}, {"text": "冰块", "is_correct": false, "explanation": "搭配：“烧”不搭配冰块，冰块遇火只会融化成水。"}, {"text": "冰山", "is_correct": false, "explanation": "语义：冰山不会出现在厨房里，与句中“厨房里的”的语境相冲突。"}], "explanations": {"塑料制品": "正确。塑料制品遇火会熔化并释放有害烟气，所以不能放进火里烧，符合句中语境。", "木柴": "语义：木柴本来就是用来烧的，与句中“不能放进火里烧”的意思相反。", "冰块": "搭配：“烧”不搭配冰块，冰块遇火只会融化成水。", "冰山": "语义：冰山不会出现在厨房里，与句中“厨房里的”的语境相冲突。"}, "sentence_index": 6, "correct_answer": "塑料制品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他渴了，就喝了塑料制品。", "explanation": "搭配：〈喝〉的对象应是饮料、水等液体，塑料制品不能喝。"}, {"text": "他每天晚上读塑料制品。", "explanation": "搭配：〈读〉的对象应是书报等文字材料，塑料制品不能读。"}, {"text": "老师让我们听塑料制品。", "explanation": "搭配：〈听〉的对象应是声音、音乐等，塑料制品不能听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们工厂昨天生产了三只塑料制品。", "corrected_sentence": "他们工厂昨天生产了三件塑料制品。", "error_description": "量词错误：塑料制品应用量词“件”，应说“三件塑料制品”。“只”多用于动物或成对的东西，不能用来修饰塑料制品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人塑料制品装进了箱子。", "corrected_sentence": "工人把塑料制品装进了箱子。", "error_description": "缺少“把”：“装进”前的宾语“塑料制品”要用“把”引出，应说“工人把塑料制品装进了箱子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
