INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13175, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然资源是指自然界中人类可以利用的物质和能量，如空气、水、土地、矿产等。", "primary_collocate": null, "pronunciation": "zì rán zī yuán", "ipa": "tsz̩⁵¹ ʐan³⁵ tsz̩⁵⁵ ɥɛn³⁵", "syllable_count": 4, "sentences": [{"text": "这些环境政策的目标是减少塑料污染，保护自然资源。", "target_word": "自然资源", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "中国有丰富的自然资源，比如煤和石油。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要合理使用自然资源，不能浪费。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家人口很多，自然资源却不够用。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球上的自然资源是有限的。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府正在研究怎样保护自然资源。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开发自然资源以前，要先想想环境问题。", "target_word": "自然资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水、土地和森林都是重要的自然资源。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那座岛上的自然资源很少，生活不容易。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作是调查这个地区的自然资源。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然資源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自然界中人类可利用的物质和能量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd050e39d-2ea0-4db5-ae84-c11939194167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13175, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然资源", "is_correct": true, "explanation": "填入“自然资源”：减少污染、保护的对象正是自然界中可供人类利用的物质和能量，与句意相配。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“保护”的对象应是有价值的东西，“保护噪音”与“减少塑料污染”的政策目标相反，句意不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是要清理的废弃物，“保护垃圾”与环境政策的目标相反。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“保护”不能带“账单”作宾语，句子不通。"}], "explanations": {"自然资源": "填入“自然资源”：减少污染、保护的对象正是自然界中可供人类利用的物质和能量，与句意相配。", "噪音": "语义：“保护”的对象应是有价值的东西，“保护噪音”与“减少塑料污染”的政策目标相反，句意不通。", "垃圾": "语义：“垃圾”是要清理的废弃物，“保护垃圾”与环境政策的目标相反。", "账单": "搭配：“保护”不能带“账单”作宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "自然资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自然资源的美景让人心情好。", "explanation": "这里应该用〈大自然〉。自然资源指可供人类利用的物质和能量，不用来形容美景。"}, {"text": "这家公司的自然资源包括很多房子。", "explanation": "这里应该用〈资产〉。自然资源指自然界的物质和能量，房子是人造的资产，不属于自然资源。"}, {"text": "这家工厂每天生产很多自然资源。", "explanation": "这里应该用〈产品〉。自然资源是自然界本来就有的，工厂不能生产它们。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13175, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然资源", "is_correct": true, "explanation": "填入“自然资源”：开发的对象正是自然界中的物质和能量，与“开发……以前要先想想环境问题”相符。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：“笑容”是面部表情，不能被开发，句子不通。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是过去发生的事，不能被“开发”，句子意思不通。"}, {"text": "情感", "is_correct": false, "explanation": "语义：情感不是可以开发的物质或能量，与句意不符。"}], "explanations": {"自然资源": "填入“自然资源”：开发的对象正是自然界中的物质和能量，与“开发……以前要先想想环境问题”相符。", "笑容": "语义：“笑容”是面部表情，不能被开发，句子不通。", "历史": "语义：历史是过去发生的事，不能被“开发”，句子意思不通。", "情感": "语义：情感不是可以开发的物质或能量，与句意不符。"}, "sentence_index": 6, "correct_answer": "自然资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区的自然资源很美。", "explanation": "这里应该用〈风景〉。自然资源指物质和能量，不用来形容景色。"}, {"text": "学校教给我们很多自然资源。", "explanation": "这里应该用〈知识〉。自然资源是物质和能量，不是可以教授的知识。"}, {"text": "学生完成了自然资源。", "explanation": "这里应该用〈作业〉。自然资源是客观存在的物质，不能说“完成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要保护自然资源们。", "corrected_sentence": "我们要保护自然资源。", "error_description": "复数错误：“自然资源”是泛指的物质和能量，不指人，不能加“们”表示复数，应说“自然资源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂要合理利用一个自然资源。", "corrected_sentence": "工厂要合理利用自然资源。", "error_description": "量词错误：“自然资源”是泛指的概念，不能用“一个”计量，应去掉“一个”，说“工厂要合理利用自然资源”，或改说“一种自然资源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13176, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
