INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13181, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吸管是一种中空的管状器具，通常用于吸取液体饮料。", "primary_collocate": null, "pronunciation": "xī guǎn", "ipa": "ɕi˥ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "近年来，欧盟通过《一次性塑料指令》规定禁用餐具、吸管和发泡餐盒等十类常见塑料消费品，各成员国也要把指令转为本国法律。", "target_word": "吸管", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "联邦层面长期缺乏统一立法，但多个城市与州级行政区自主推行禁令，涵盖塑料吸管、外卖容器及零售包装等领域。", "target_word": "吸管", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "另一些国家完全禁止某些塑料产品，比如塑料吸管和餐具。", "target_word": "吸管", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "请给我一根吸管，我想喝果汁。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩用吸管喝牛奶，不会洒出来。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根吸管太细，喝不了奶茶。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把吸管插进杯子里喝了一口。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸吸管泡在水里太久会变软。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员问我要不要吸管。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用完的吸管要扔进垃圾桶。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "塑料吸管", "label": "复合"}, {"form": "纸吸管", "label": "复合"}], "register": "中性", "sense_fingerprint": "中空管状器具，用来吸饮料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0fbe80-3322-4a2e-a4d7-d218a61d1e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13181, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吸管", "is_correct": true, "explanation": "正确：吸管（xī guǎn）是中空的细管，用来吸取饮料。"}, {"text": "习惯", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，guàn（第四声）与 guǎn（第三声）声调也不同，意思是习惯。"}, {"text": "气管", "is_correct": false, "explanation": "qì（第四声）与 xī（第一声）声母不同（q/x），声调也不同，意思是气管。"}, {"text": "机关", "is_correct": false, "explanation": "jī 与 xī 声母不同（j/x），guān（第一声）与 guǎn（第三声）声调不同，意思是机关。"}], "explanations": {"吸管": "正确：吸管（xī guǎn）是中空的细管，用来吸取饮料。", "习惯": "xí（第二声）与 xī（第一声）声调不同，guàn（第四声）与 guǎn（第三声）声调也不同，意思是习惯。", "气管": "qì（第四声）与 xī（第一声）声母不同（q/x），声调也不同，意思是气管。", "机关": "jī 与 xī 声母不同（j/x），guān（第一声）与 guǎn（第三声）声调不同，意思是机关。"}, "sentence_index": null, "correct_answer": "吸管"}, "level_3": {"options": [{"text": "吸管", "is_correct": true, "explanation": "正确：吸管多为塑料制成，属于列表中的塑料消费品，与餐具、发泡餐盒并列。"}, {"text": "纸杯", "is_correct": false, "explanation": "语义：列表写的是塑料消费品，纸杯是纸制品，与“禁用塑料消费品”的限定不符。"}, {"text": "玻璃瓶", "is_correct": false, "explanation": "语义：玻璃是无机材料，不属于塑料消费品，放进这份禁用列表不成立。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“禁用”针对的是器具和消费品，不说禁用饮料，饮料也不是塑料制品。"}], "explanations": {"吸管": "正确：吸管多为塑料制成，属于列表中的塑料消费品，与餐具、发泡餐盒并列。", "纸杯": "语义：列表写的是塑料消费品，纸杯是纸制品，与“禁用塑料消费品”的限定不符。", "玻璃瓶": "语义：玻璃是无机材料，不属于塑料消费品，放进这份禁用列表不成立。", "饮料": "搭配：“禁用”针对的是器具和消费品，不说禁用饮料，饮料也不是塑料制品。"}, "sentence_index": 0, "correct_answer": "吸管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根吸管是用来打电话的。", "explanation": "这里应该用〈手机〉。吸管只用来吸饮料，不能用来打电话，打电话要用手机。"}, {"text": "他把果汁倒进吸管里。", "explanation": "这里应该用〈杯子〉。吸管是细管，用来吸饮料，不能用来盛装或倒入液体。"}, {"text": "他用吸管舀了一口汤。", "explanation": "这里应该用〈勺子〉。舀汤要用勺子，吸管是用来吸的，不能用来舀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸管", "is_correct": true, "explanation": "正确：吸管是中空的细管，插进杯子里可以把饮料吸上来喝。"}, {"text": "勺子", "is_correct": false, "explanation": "语义：勺子是浅凹的，不能插进杯子里吸饮料，这里需要中空的细管。"}, {"text": "毛巾", "is_correct": false, "explanation": "搭配：“插”要用细长的东西，不说插毛巾，毛巾也不能用来喝水。"}, {"text": "筷子", "is_correct": false, "explanation": "形状：筷子是实心的，吸管是中空的，实心的筷子无法把饮料吸上来。"}], "explanations": {"吸管": "正确：吸管是中空的细管，插进杯子里可以把饮料吸上来喝。", "勺子": "语义：勺子是浅凹的，不能插进杯子里吸饮料，这里需要中空的细管。", "毛巾": "搭配：“插”要用细长的东西，不说插毛巾，毛巾也不能用来喝水。", "筷子": "形状：筷子是实心的，吸管是中空的，实心的筷子无法把饮料吸上来。"}, "sentence_index": 6, "correct_answer": "吸管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一只吸管。", "explanation": "这里应该用〈根〉。吸管细长，量词用“根”；“只”多用于动物和成对物件中的一个。"}, {"text": "我买了一张吸管。", "explanation": "这里应该用〈根〉。“张”用于纸张、桌子等平面或扁平的物件，吸管是细长条，应说“一根”。"}, {"text": "我买了一块吸管。", "explanation": "这里应该用〈根〉。“块”用于块状的东西，吸管是细长的，应说“一根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了三只吸管。", "corrected_sentence": "我买了三根吸管。", "error_description": "量词错误：吸管应用量词“根”，应说“三根吸管”。“只”多用于动物或成对物件中的一个，不用来数吸管。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吸管扔掉了。", "corrected_sentence": "他把吸管扔掉了。", "error_description": "缺少“把”：“扔掉”前的宾语“吸管”要用“把”引出，应说“他把吸管扔掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
