INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指用餐时使用的各种器具，如碗、盘、筷子、勺子等。", "primary_collocate": null, "pronunciation": "cān jù", "ipa": "tsʰan˥˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "近年来，欧盟通过《一次性塑料指令》规定禁用餐具、吸管和发泡餐盒等十类常见塑料消费品，各成员国也要把指令转为本国法律。", "target_word": "餐具", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "另一些国家完全禁止某些塑料产品，比如塑料吸管和餐具。", "target_word": "餐具", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "吃饭以前，请把餐具摆好。", "target_word": "餐具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的餐具都消毒过。", "target_word": "餐具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外卖里有一套一次性餐具。", "target_word": "餐具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在厨房洗餐具。", "target_word": "餐具", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他送了我一套漂亮的餐具。", "target_word": "餐具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把新买的餐具擦干净，放进了厨房。", "target_word": "餐具", "complexity_tier": "T3", "furigana": "wǒ bǎ xīn mǎi de cānjù cā gānjìng，fàngjìn le chúfáng。", "sentence_source": "generated"}, {"text": "我们出去野餐时带了餐具。", "target_word": "餐具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套餐具是用瓷做的。", "target_word": "餐具", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套餐具", "label": "量词"}, {"form": "一次性餐具", "label": "复合"}], "register": "中性", "sense_fingerprint": "用餐时使用的碗、盘、筷子、勺子等器具的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0fbe80-3322-4a2e-a4d7-d218a61d1e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13182, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "餐具", "is_correct": true, "explanation": "正确：餐具是吃饭时用的碗、勺、筷子等器具。"}, {"text": "惨剧", "is_correct": false, "explanation": "cǎn（第三声）与 cān（第一声）声调不同，意思是悲惨的事件。"}, {"text": "餐局", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是一次聚餐。"}, {"text": "残局", "is_correct": false, "explanation": "cán（第二声）与 cān（第一声）、jú（第二声）与 jù（第四声）声调都不同，意思是残余的局面或棋局。"}, {"text": "餐叙", "is_correct": false, "explanation": "xù 与 jù 声母不同（x/j），声调相同，意思是一起吃饭交谈。"}], "explanations": {"餐具": "正确：餐具是吃饭时用的碗、勺、筷子等器具。", "惨剧": "cǎn（第三声）与 cān（第一声）声调不同，意思是悲惨的事件。", "餐局": "jú（第二声）与 jù（第四声）声调不同，意思是一次聚餐。", "残局": "cán（第二声）与 cān（第一声）、jú（第二声）与 jù（第四声）声调都不同，意思是残余的局面或棋局。", "餐叙": "xù 与 jù 声母不同（x/j），声调相同，意思是一起吃饭交谈。"}, "sentence_index": null, "correct_answer": "餐具"}, "level_3": {"options": [{"text": "餐具", "is_correct": true, "explanation": "正确：列表中的餐具指一次性塑料餐具，与吸管、发泡餐盒并列。"}, {"text": "纸箱", "is_correct": false, "explanation": "语义：纸箱是纸制品，不是被禁的塑料消费品，放进这份列表不成立。"}, {"text": "玻璃瓶", "is_correct": false, "explanation": "语义：玻璃是无机材料，不属于塑料消费品，与题干的限定不符。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“禁用”针对器具和消费品，不说禁用饮料，饮料也不是塑料制品。"}], "explanations": {"餐具": "正确：列表中的餐具指一次性塑料餐具，与吸管、发泡餐盒并列。", "纸箱": "语义：纸箱是纸制品，不是被禁的塑料消费品，放进这份列表不成立。", "玻璃瓶": "语义：玻璃是无机材料，不属于塑料消费品，与题干的限定不符。", "饮料": "搭配：“禁用”针对器具和消费品，不说禁用饮料，饮料也不是塑料制品。"}, "sentence_index": 0, "correct_answer": "餐具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用餐具炒了一盘菜。", "explanation": "这里应该用〈炊具〉。炒菜要用锅、铲等炊具，餐具是吃饭时用的器具，不能用来炒菜。"}, {"text": "我们围坐在餐具旁吃饭。", "explanation": "这里应该用〈餐桌〉。围坐吃饭的地方是餐桌，餐具是器具，不能作为围坐的场所。"}, {"text": "我们去餐具吃饭。", "explanation": "这里应该用〈餐厅〉。去吃饭的场所是餐厅，餐具是器具，不能说去餐具吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐具", "is_correct": true, "explanation": "正确：一套餐具是成套计量的器具，“漂亮的”和“送了我”都说得通。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“套”用于成套的器具或服装，不说一套面包，应说一袋或一个面包。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：送礼物不会送病毒，病毒也谈不上漂亮。"}, {"text": "花", "is_correct": false, "explanation": "搭配：花按“束”或“枝”计量，不说一套花。"}], "explanations": {"餐具": "正确：一套餐具是成套计量的器具，“漂亮的”和“送了我”都说得通。", "面包": "搭配：“套”用于成套的器具或服装，不说一套面包，应说一袋或一个面包。", "病毒": "语义：送礼物不会送病毒，病毒也谈不上漂亮。", "花": "搭配：花按“束”或“枝”计量，不说一套花。"}, "sentence_index": 6, "correct_answer": "餐具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一只餐具。", "explanation": "这里应该用〈套〉。餐具按套计量，要说“一套餐具”，“只”不能用于餐具。"}, {"text": "我买了一张餐具。", "explanation": "这里应该用〈套〉。“张”用于平面的东西，餐具成套计量，应说“一套”。"}, {"text": "我买了一块餐具。", "explanation": "这里应该用〈套〉。“块”用于块状的东西，餐具成套计量，应说“一套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上摆着这套餐具过。", "corrected_sentence": "桌上摆着这套餐具。", "error_description": "多余的“过”：句子描述的是摆放的状态，应用“着”，不说“过”；“过”也不能放在宾语“这套餐具”之后。正确说法：桌上摆着这套餐具。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一只瓷餐具。", "corrected_sentence": "我买了一套瓷餐具。", "error_description": "量词错误：餐具成套计量，应说“一套”，不说“一只”。正确说法：我买了一套瓷餐具。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13183, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免税", "is_correct": true, "explanation": "免税指免除税收，与“征税”意思相反，二者构成反义。"}, {"text": "研究", "is_correct": false, "explanation": "与“征税”无反义关系，“研究”指探求事物的道理，与收税无关。"}, {"text": "打扫", "is_correct": false, "explanation": "与“征税”无反义关系，“打扫”指清除脏物，与税收无关。"}, {"text": "旅行", "is_correct": false, "explanation": "与“征税”无反义关系，“旅行”指到外地游览，与税收无关。"}], "correct_answer": "免税", "explanations": {"免税": "免税指免除税收，与“征税”意思相反，二者构成反义。", "研究": "与“征税”无反义关系，“研究”指探求事物的道理，与收税无关。", "打扫": "与“征税”无反义关系，“打扫”指清除脏物，与税收无关。", "旅行": "与“征税”无反义关系，“旅行”指到外地游览，与税收无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13183, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免税", "is_correct": true, "explanation": "免税指免除税收，与“征税”意思相反，二者构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“征税”无反义关系，“唱歌”指用声音表达乐曲，与税收无关。"}, {"text": "散步", "is_correct": false, "explanation": "与“征税”无反义关系，“散步”指随意走动，与税收无关。"}, {"text": "游泳", "is_correct": false, "explanation": "与“征税”无反义关系，“游泳”指在水中活动，与税收无关。"}], "correct_answer": "免税", "explanations": {"免税": "免税指免除税收，与“征税”意思相反，二者构成反义。", "唱歌": "与“征税”无反义关系，“唱歌”指用声音表达乐曲，与税收无关。", "散步": "与“征税”无反义关系，“散步”指随意走动，与税收无关。", "游泳": "与“征税”无反义关系，“游泳”指在水中活动，与税收无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13183, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "国家依法向单位和个人征收货币或实物，以筹集财政收入。", "primary_collocate": null, "pronunciation": "zhēng shuì", "ipa": "tʂəŋ˥ ʂweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "政府还会对制造塑料的企业征税，鼓励它们改用环保材料。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "政府对大公司征税，用来修路。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从明年一月起，政府对香烟征税。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府对很贵的车征税，买车的人要多付钱。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家对外国货征税，所以价钱更高。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府为了有钱修学校，决定对富人多征税。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前政府没有对网上买的东西征税。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府对糖征税后，汽水变贵了。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长说，政府不会对小店征税。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市对旅客征税，钱用来建公园。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "征了税", "label": "体标"}, {"form": "征过税", "label": "体标"}], "register": "正式", "sense_fingerprint": "国家依法向单位和个人征收钱物，筹集财政收入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd050e39d-2ea0-4db5-ae84-c11939194167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13183, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "征税", "is_correct": true, "explanation": "填入“征税”：政府对企业征收税款，与“对制造塑料的企业”搭配，也符合后半句“鼓励它们改用环保材料”的政策意图。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能以企业为对象，句子不通。"}, {"text": "承认", "is_correct": false, "explanation": "配价：“承认”后接事实或观点，不能说“对企业承认”，句子不成立。"}, {"text": "回避", "is_correct": false, "explanation": "搭配：“回避”是躲开的意思，不能说“对企业回避”，与句意不合。"}], "explanations": {"征税": "填入“征税”：政府对企业征收税款，与“对制造塑料的企业”搭配，也符合后半句“鼓励它们改用环保材料”的政策意图。", "吃": "语义：“吃”指进食，不能以企业为对象，句子不通。", "承认": "配价：“承认”后接事实或观点，不能说“对企业承认”，句子不成立。", "回避": "搭配：“回避”是躲开的意思，不能说“对企业回避”，与句意不合。"}, "sentence_index": 0, "correct_answer": "征税"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每年都向政府征税。", "explanation": "这里应该用〈纳税〉。征税的主体是国家，个人是纳税的一方，不能说“向政府征税”。"}, {"text": "这家医院对病人征税，价格很高。", "explanation": "这里应该用〈收费〉。征税只能由国家依法进行，医院收的是服务费用，不是税。"}, {"text": "交警对超速的司机征税。", "explanation": "这里应该用〈罚款〉。征税是按税法向纳税人收取税款，因违章被处的钱叫罚款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "征税", "is_correct": true, "explanation": "填入“征税”：“没有对……征税”指不向网购商品征收税款，与句意相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”要带请求、要求之类的对象，不能说“对东西拒绝”，句子不通。"}, {"text": "担心", "is_correct": false, "explanation": "配价：“担心”的对象是某种情况或事情，不能说“对东西担心”，句子不成立。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得好而赞美，与政府管理网购商品的语境冲突，句意不合。"}], "explanations": {"征税": "填入“征税”：“没有对……征税”指不向网购商品征收税款，与句意相符。", "拒绝": "搭配：“拒绝”要带请求、要求之类的对象，不能说“对东西拒绝”，句子不通。", "担心": "配价：“担心”的对象是某种情况或事情，不能说“对东西担心”，句子不成立。", "欣赏": "语义：“欣赏”指觉得好而赞美，与政府管理网购商品的语境冲突，句意不合。"}, "sentence_index": 6, "correct_answer": "征税"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都去银行征税。", "explanation": "这里应该用〈交税〉。征税的是国家，个人只能交税，不能说“去银行征税”。"}, {"text": "这家公司每年都向税务局征税。", "explanation": "这里应该用〈报税〉。征税是税务机关的行为，公司是报税的一方，不能说“公司向税务局征税”。"}, {"text": "学生每学期都要向学校征税。", "explanation": "这里应该用〈缴费〉。征税只能由国家依法进行，学校收的是学费等费用，不是税。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府汽车公司征税，用来修路。", "corrected_sentence": "政府对汽车公司征税，用来修路。", "error_description": "“征税”的受税对象要用介词“对”引出，应说“对汽车公司征税”。省略“对”直接说“政府汽车公司征税”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府以前对进口的衣服征税过。", "corrected_sentence": "政府以前对进口的衣服征过税。", "error_description": "“征税”是离合词，体标“过”要放在“征”和“税”之间，应说“征过税”。“征税过”把“过”放在末尾，不符合汉语语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13184, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "沿用", "is_correct": true, "explanation": "“沿用”指继续使用原来的方法或东西，与“改用”正相反，是这一义项的反义词。"}, {"text": "讨论", "is_correct": false, "explanation": "与“改用”无反义关系，“讨论”指就问题交换意见。"}, {"text": "冷藏", "is_correct": false, "explanation": "与“改用”无反义关系，“冷藏”指把东西放在低温中保存。"}, {"text": "散步", "is_correct": false, "explanation": "与“改用”无反义关系，“散步”指随意地走动。"}], "correct_answer": "沿用", "explanations": {"沿用": "“沿用”指继续使用原来的方法或东西，与“改用”正相反，是这一义项的反义词。", "讨论": "与“改用”无反义关系，“讨论”指就问题交换意见。", "冷藏": "与“改用”无反义关系，“冷藏”指把东西放在低温中保存。", "散步": "与“改用”无反义关系，“散步”指随意地走动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13184, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "沿用", "is_correct": true, "explanation": "“沿用”指继续使用原来的方法或东西，与“改用”正相反，是这一义项的反义词。"}, {"text": "观察", "is_correct": false, "explanation": "与“改用”无反义关系，“观察”指仔细地看。"}, {"text": "修理", "is_correct": false, "explanation": "与“改用”无反义关系，“修理”指修复坏了的东西。"}, {"text": "旅行", "is_correct": false, "explanation": "与“改用”无反义关系，“旅行”指到外地游览。"}], "correct_answer": "沿用", "explanations": {"沿用": "“沿用”指继续使用原来的方法或东西，与“改用”正相反，是这一义项的反义词。", "观察": "与“改用”无反义关系，“观察”指仔细地看。", "修理": "与“改用”无反义关系，“修理”指修复坏了的东西。", "旅行": "与“改用”无反义关系，“旅行”指到外地游览。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13184, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变原来的方式或物品，换成另一种来使用。", "primary_collocate": null, "pronunciation": "gǎi yòng", "ipa": "kaɪ̯˨˩˦ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "政府还会对制造塑料的企业征税，鼓励它们改用环保材料。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们家改用布袋买菜了。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机坏了，只好改用旧手机。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多商店改用纸袋，不再给塑料袋。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，我改用热水洗脸。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司改用新系统以后，工作快多了。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前他用铅笔，现在改用钢笔写字。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅改用纸吸管了。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他改用另一种药。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校改用电子课本，书包轻多了。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改用了", "label": "体标"}, {"form": "改用过", "label": "体标"}], "register": "中性", "sense_fingerprint": "改用:改变原来的方式或物品，换成另一种来使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23dfa03-b845-44a8-b153-08ac3a942371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改用", "is_correct": true, "explanation": "“改用”指换成另一种东西来用，与“鼓励它们改用环保材料”的语境相符。"}, {"text": "停用", "is_correct": false, "explanation": "语义：“停用”与“鼓励”的积极意向相反，与前面征税的目的矛盾。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉环保材料与“鼓励”“环保”的语境冲突。"}, {"text": "乱用", "is_correct": false, "explanation": "搭配：“鼓励”后接的应是正面行为，“乱用”是贬义词，不能这样搭配。"}], "explanations": {"改用": "“改用”指换成另一种东西来用，与“鼓励它们改用环保材料”的语境相符。", "停用": "语义：“停用”与“鼓励”的积极意向相反，与前面征税的目的矛盾。", "扔掉": "语义：扔掉环保材料与“鼓励”“环保”的语境冲突。", "乱用": "搭配：“鼓励”后接的应是正面行为，“乱用”是贬义词，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "改用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把头发改用了黑色。", "explanation": "这里应该用〈改成〉。改用指换一种东西或方法来使用，改颜色要说〈改成〉。"}, {"text": "学校改用了新的校长。", "explanation": "这里应该用〈换〉。改用指换用物品或方法，人事变动要说〈换〉。"}, {"text": "医生改用了他的病。", "explanation": "这里应该用〈治疗〉。改用指换用物品或方法，治病要说〈治疗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改用", "is_correct": true, "explanation": "“改用”指换成另一种东西来用，与“以前用铅笔，现在用钢笔”的对比相符。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉钢笔就无法用钢笔写字，与句中的用法矛盾。"}, {"text": "戒掉", "is_correct": false, "explanation": "搭配：“戒掉”搭配习惯、烟酒等，不能搭配“钢笔写字”。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：收藏钢笔不等于用钢笔写字，与“用钢笔写字”的语义冲突。"}], "explanations": {"改用": "“改用”指换成另一种东西来用，与“以前用铅笔，现在用钢笔”的对比相符。", "扔掉": "语义：扔掉钢笔就无法用钢笔写字，与句中的用法矛盾。", "戒掉": "搭配：“戒掉”搭配习惯、烟酒等，不能搭配“钢笔写字”。", "收藏": "语义：收藏钢笔不等于用钢笔写字，与“用钢笔写字”的语义冲突。"}, "sentence_index": 6, "correct_answer": "改用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在银行改用了手续。", "explanation": "这里应该用〈办理〉。改用指换用物品或方法，办手续要说〈办理〉。"}, {"text": "他改用了作业中的错误。", "explanation": "这里应该用〈改正〉。改用指换用另一种东西，修正错误要说〈改正〉。"}, {"text": "老师改用了我的家长，把情况告诉了他们。", "explanation": "这里应该用〈通知〉。改用指换用物品或方法，告诉家长要说〈通知〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们改用了了新的洗衣机。", "corrected_sentence": "他们改用了新的洗衣机。", "error_description": "重复“了”：“改用”是一个整体动词，“了”只用一个，应说“改用了新的洗衣机”，不能说“改用了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校改用了一本新系统。", "corrected_sentence": "学校改用了一个新系统。", "error_description": "量词错误：“系统”应用“个”或“套”计量，“本”用于书册。应说“一个新系统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
