INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13186, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指支付了超过应付金额的款项。", "primary_collocate": null, "pronunciation": "duō fù", "ipa": "tu̯ɔ⁵⁵ fu⁵¹", "syllable_count": 2, "sentences": [{"text": "顾客买饮料时多付一点钱，归还空瓶后可以拿回押金。", "target_word": "多付", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我多付了十块钱，老板马上退给我。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不小心多付了房租，房东会退回来。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买票时我多付了五元，工作人员发现了。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电费多付的钱，下个月可以少交。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈发现自己多付了菜钱，就回去找老板。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你多付的钱，银行三天内会还给你。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机说我多付了车费，把零钱还给了我。", "target_word": "多付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他多付了水费，所以这个月不用再交。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友多付了饭钱，我晚上转给他。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "多付了", "label": "体标"}, {"form": "多付过", "label": "体标"}], "register": "中性", "sense_fingerprint": "支付超过应付金额的钱款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23dfa03-b845-44a8-b153-08ac3a942371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多付", "is_correct": true, "explanation": "正确：“多付”指顾客付了超过应付的钱，与后文归还空瓶后拿回押金相符。"}, {"text": "收", "is_correct": false, "explanation": "语义：“收”是接受钱款的动作，顾客买饮料时不会收钱。"}, {"text": "赔", "is_correct": false, "explanation": "搭配：“赔”表示赔偿损失，不能和买饮料时的付款搭配。"}, {"text": "抢", "is_correct": false, "explanation": "语义：“抢一点钱”指夺取，与买饮料时的正常付款完全不符。"}], "explanations": {"多付": "正确：“多付”指顾客付了超过应付的钱，与后文归还空瓶后拿回押金相符。", "收": "语义：“收”是接受钱款的动作，顾客买饮料时不会收钱。", "赔": "搭配：“赔”表示赔偿损失，不能和买饮料时的付款搭配。", "抢": "语义：“抢一点钱”指夺取，与买饮料时的正常付款完全不符。"}, "sentence_index": 0, "correct_answer": "多付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师多付了我一个机会。", "explanation": "这里应该用〈多给〉。多付只用于钱款，给人机会要用“多给”。"}, {"text": "我多付了一封信。", "explanation": "这里应该用〈多写〉。多付只用于钱款，写信的数量要用“多写”。"}, {"text": "我多付了三页书。", "explanation": "这里应该用〈多看〉。多付只用于钱款，看书的量要用“多看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多付", "is_correct": true, "explanation": "正确：“多付”指付了超过应付的钱，与“归还”的语境相符。"}, {"text": "撒", "is_correct": false, "explanation": "搭配：“撒”指散落，与交给银行、再还给你的钱款不搭配。"}, {"text": "扔", "is_correct": false, "explanation": "语义：被扔掉的钱不会由银行归还，句意不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉的钱无法归还，与“银行三天内会还给你”矛盾。"}], "explanations": {"多付": "正确：“多付”指付了超过应付的钱，与“归还”的语境相符。", "撒": "搭配：“撒”指散落，与交给银行、再还给你的钱款不搭配。", "扔": "语义：被扔掉的钱不会由银行归还，句意不通。", "烧": "语义：烧掉的钱无法归还，与“银行三天内会还给你”矛盾。"}, "sentence_index": 6, "correct_answer": "多付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我排队时多付了一个小时。", "explanation": "这里应该用〈多花〉。多付只用于钱款，花费时间要用“多花”。"}, {"text": "他多付了我一份礼物。", "explanation": "这里应该用〈多送〉。多付用于钱款，送人东西要用“多送”。"}, {"text": "服务员多付了一勺汤。", "explanation": "这里应该用〈多加〉。多付用于钱款，给食物添量要用“多加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我多付着一块钱，老板还给了我。", "corrected_sentence": "我多付了一块钱，老板还给了我。", "error_description": "体标错误：“多付”是已完成的一次性付款，应用“了”；“着”表示持续的状态，不能用于这里。应改为“多付了一块钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次我没多付了钱，只付了应该付的。", "corrected_sentence": "这次我没多付钱，只付了应该付的。", "error_description": "体标错误：“没”表示动作没有发生，否定句中不能再用“了”。应改为“没多付钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
