INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13187, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将借来的物品或钱财等返还给原主。", "primary_collocate": null, "pronunciation": "guī huán", "ipa": "ku̯eɪ̯⁵⁵ xu̯an³⁵", "syllable_count": 2, "sentences": [{"text": "顾客买饮料时多付一点钱，归还空瓶后可以拿回押金。", "target_word": "归还", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我昨天把借来的书归还了图书馆。", "target_word": "归还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王向朋友借了钱，下个月就归还。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在月底前归还图书馆的书。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他借了我的伞，还没有归还。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "租来的相机，你要按时归还。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让同学们把借的笔归还原主。", "target_word": "归还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向同学借的字典，已经按时归还了。", "target_word": "归还", "complexity_tier": "T3", "furigana": "guī huán", "sentence_source": "generated"}, {"text": "借过的东西，一定要记得归还。", "target_word": "归还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我读完了，明天去归还。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "归还了", "label": "体标"}, {"form": "归还过", "label": "体标"}, {"form": "歸還", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把借来的物品或钱财还给原主", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23dfa03-b845-44a8-b153-08ac3a942371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13187, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "归还", "is_correct": true, "explanation": "归还 guī huán，意思是把借来的东西还回去。"}, {"text": "规划", "is_correct": false, "explanation": "规划 guī huà：第一个音节相同，第二个音节 huà 去掉了韵尾 n 且声调不同（第四声），意思是计划。"}, {"text": "桂花", "is_correct": false, "explanation": "桂花 guì huā：第一个音节声调不同（guì 为第四声），第二个音节 huā 去掉了韵尾 n，意思是桂花。"}, {"text": "鬼话", "is_correct": false, "explanation": "鬼话 guǐ huà：第一个音节声调不同（guǐ 为第三声），第二个音节去掉韵尾 n，意思是胡说的话。"}, {"text": "鬼混", "is_correct": false, "explanation": "鬼混 guǐ hùn：第一个音节声调不同（guǐ 为第三声），第二个音节韵母 uan 变为 un，意思是厮混。"}], "explanations": {"归还": "归还 guī huán，意思是把借来的东西还回去。", "规划": "规划 guī huà：第一个音节相同，第二个音节 huà 去掉了韵尾 n 且声调不同（第四声），意思是计划。", "桂花": "桂花 guì huā：第一个音节声调不同（guì 为第四声），第二个音节 huā 去掉了韵尾 n，意思是桂花。", "鬼话": "鬼话 guǐ huà：第一个音节声调不同（guǐ 为第三声），第二个音节去掉韵尾 n，意思是胡说的话。", "鬼混": "鬼混 guǐ hùn：第一个音节声调不同（guǐ 为第三声），第二个音节韵母 uan 变为 un，意思是厮混。"}, "sentence_index": null, "correct_answer": "归还"}, "level_3": {"options": [{"text": "归还", "is_correct": true, "explanation": "归还空瓶后才能拿回押金，符合句意。"}, {"text": "购买", "is_correct": false, "explanation": "语义：购买是买入，与“拿回押金”的回收前提相反，句意不通。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：丢弃是扔掉，扔掉之后无法再拿回押金。"}, {"text": "保留", "is_correct": false, "explanation": "搭配：“保留空瓶”在此语境不成立，留下空瓶就无法换回押金。"}], "explanations": {"归还": "归还空瓶后才能拿回押金，符合句意。", "购买": "语义：购买是买入，与“拿回押金”的回收前提相反，句意不通。", "丢弃": "语义：丢弃是扔掉，扔掉之后无法再拿回押金。", "保留": "搭配：“保留空瓶”在此语境不成立，留下空瓶就无法换回押金。"}, "sentence_index": 0, "correct_answer": "归还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买的鞋太小，昨天去商店归还了。", "explanation": "这里应该用〈退还〉。归还指把借来的东西还给原主；买来的商品退回商店要用退还。"}, {"text": "他不小心打坏了邻居的玻璃，已经归还了三百元。", "explanation": "这里应该用〈赔偿〉。归还指把借来的东西还给原主；因损坏而付钱要说赔偿。"}, {"text": "他一直想归还父母的养育之恩。", "explanation": "这里应该用〈报答〉。归还只用于把借来的东西还给原主，恩情要说报答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归还", "is_correct": true, "explanation": "归还原主符合句意，老师要求同学把借的笔还给原来的主人。"}, {"text": "偷窃", "is_correct": false, "explanation": "语义：偷窃是非法拿走，与“归还原主”的交还语境相反。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：收藏是留为己有，与交还给原主的意思相反。"}, {"text": "抢夺", "is_correct": false, "explanation": "配价：“抢夺”要带被夺物并以“从…手中”引出对象，不能直接接“原主”。"}], "explanations": {"归还": "归还原主符合句意，老师要求同学把借的笔还给原来的主人。", "偷窃": "语义：偷窃是非法拿走，与“归还原主”的交还语境相反。", "收藏": "语义：收藏是留为己有，与交还给原主的意思相反。", "抢夺": "配价：“抢夺”要带被夺物并以“从…手中”引出对象，不能直接接“原主”。"}, "sentence_index": 6, "correct_answer": "归还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "生日那天，我把自己写的一本小说归还给了朋友。", "explanation": "这里应该用〈赠送〉。归还指把借来的东西还给原主，这本小说是我自己写的，只能说赠送。"}, {"text": "他把积蓄归还给了灾区。", "explanation": "这里应该用〈捐献〉。归还指还给原主；把自己的钱无偿交给灾区要说捐献。"}, {"text": "他向老板归还了这个月的工资。", "explanation": "这里应该用〈领取〉。归还指把借来的东西还给原主，工资是应得的收入，应说领取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把借来的伞归还了朋友。", "corrected_sentence": "我把借来的伞归还给了朋友。", "error_description": "漏字：归还后引出收件人要加介词“给”，应说“归还给了朋友”，不能直接接“朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我借过老师的书，已经归还了过。", "corrected_sentence": "我借过老师的书，已经归还过了。", "error_description": "错误：“归还了过”；正确：“归还过了”。“过”表示经历，“了”表示完成，应先说“归还过”再加“了”，不能把“了”放在“过”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
