INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从别处到原来的地方；还。", "primary_collocate": null, "pronunciation": "huí", "ipa": "xweɪ˧˥", "syllable_count": 1, "sentences": [{"text": "顾客买饮料时多付一点钱，归还空瓶后可以拿回押金。", "target_word": "回", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们六点就回家了。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节他要回老家看爷爷。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课后，我先回宿舍放书。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手机放回了口袋里。", "target_word": "回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走回座位，坐了下来。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，燕子又飞回了北方。", "target_word": "回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后回了上海工作。", "target_word": "回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们快回教室吧。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末他常回奶奶家吃饭。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "回了", "label": "完成体"}, {"form": "回过", "label": "经历体"}, {"form": "回来", "label": "复合词"}, {"form": "回去", "label": "复合词"}], "register": "中性", "sense_fingerprint": "从别处回到原来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b637169d-fc3a-4445-b0ef-7e8b7705b7e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13190, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回", "is_correct": true, "explanation": "回（huí）：返回原来的地方，是本词。"}, {"text": "会", "is_correct": false, "explanation": "会（huì）与 huí 声调不同（第四声），意思是“会议、会合”。"}, {"text": "灰", "is_correct": false, "explanation": "灰（huī）与 huí 声调不同（第一声），意思是“灰色”。"}, {"text": "悔", "is_correct": false, "explanation": "悔（huǐ）与 huí 声调不同（第三声），意思是“后悔”。"}, {"text": "怀", "is_correct": false, "explanation": "怀（huái）与 huí 韵母不同（-uai 与 -ui），意思是“怀抱”。"}, {"text": "挥", "is_correct": false, "explanation": "挥（huī）与 huí 声调不同（第一声），意思是“挥动”。"}], "explanations": {"回": "回（huí）：返回原来的地方，是本词。", "会": "会（huì）与 huí 声调不同（第四声），意思是“会议、会合”。", "灰": "灰（huī）与 huí 声调不同（第一声），意思是“灰色”。", "悔": "悔（huǐ）与 huí 声调不同（第三声），意思是“后悔”。", "怀": "怀（huái）与 huí 韵母不同（-uai 与 -ui），意思是“怀抱”。", "挥": "挥（huī）与 huí 声调不同（第一声），意思是“挥动”。"}, "sentence_index": null, "correct_answer": "回"}, "level_3": {"options": [{"text": "回", "is_correct": true, "explanation": "回：返还，指还空瓶后收回押金，与“拿回”搭配。"}, {"text": "交", "is_correct": false, "explanation": "语义：“交”是交付、上交，与顾客收回押金的意思相反。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”是丢失，与收回押金的意思相反。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“拿买押金”不成搭配，“买”不能与“拿”和“押金”组合。"}], "explanations": {"回": "回：返还，指还空瓶后收回押金，与“拿回”搭配。", "交": "语义：“交”是交付、上交，与顾客收回押金的意思相反。", "丢": "语义：“丢”是丢失，与收回押金的意思相反。", "买": "搭配：“拿买押金”不成搭配，“买”不能与“拿”和“押金”组合。"}, "sentence_index": 0, "correct_answer": "回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把借你的笔回给你了。", "explanation": "这里应该用〈还〉。借来的笔要归还，说“还给你”，“回给你”不是这个搭配。"}, {"text": "妈妈把衣服回在衣架上。", "explanation": "这里应该用〈挂〉。回指返回原处，把衣服悬挂起来要说挂，不能说回在衣架上。"}, {"text": "他去年刚毕业，就回了一家新公司工作。", "explanation": "这里应该用〈去〉。回指回到原来去过的地方，第一次去的新公司不能说回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13190, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "回", "is_correct": true, "explanation": "回（huí）：返回原来的地方，是本词。"}, {"text": "辉", "is_correct": false, "explanation": "辉（huī）与 huí 声调不同（第一声），意思是“光辉”。"}, {"text": "汇", "is_correct": false, "explanation": "汇（huì）与 huí 声调不同（第四声），意思是“汇集”。"}, {"text": "毁", "is_correct": false, "explanation": "毁（huǐ）与 huí 声调不同（第三声），意思是“毁坏”。"}, {"text": "慧", "is_correct": false, "explanation": "慧（huì）与 huí 声调不同（第四声），意思是“智慧”。"}], "explanations": {"回": "回（huí）：返回原来的地方，是本词。", "辉": "辉（huī）与 huí 声调不同（第一声），意思是“光辉”。", "汇": "汇（huì）与 huí 声调不同（第四声），意思是“汇集”。", "毁": "毁（huǐ）与 huí 声调不同（第三声），意思是“毁坏”。", "慧": "慧（huì）与 huí 声调不同（第四声），意思是“智慧”。"}, "sentence_index": null, "correct_answer": "回"}, "level_3": {"options": [{"text": "回", "is_correct": true, "explanation": "回：返回，指燕子重新飞回北方。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中游动，燕子是飞行，不能说“游了北方”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“北方”组合，“飞吃”不成搭配。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“北方”作宾语。"}], "explanations": {"回": "回：返回，指燕子重新飞回北方。", "游": "语义：“游”指在水中游动，燕子是飞行，不能说“游了北方”。", "吃": "搭配：“吃”不能与“北方”组合，“飞吃”不成搭配。", "睡": "配价：“睡”是不及物动词，不能带“北方”作宾语。"}, "sentence_index": 6, "correct_answer": "回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天把作业回给了老师。", "explanation": "这里应该用〈交〉。把作业上交给老师要说交，回字在这里不能表示交付。"}, {"text": "我昨天去超市回了一瓶酱油。", "explanation": "这里应该用〈买〉。回表示返回原处，买东西要说买，或说买回来，不能只说回。"}, {"text": "他每个月回五千块钱。", "explanation": "这里应该用〈挣〉。回表示返回或答复，不能表示收入，应说挣五千块钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想回了家吃饭。", "corrected_sentence": "他想回家吃饭。", "error_description": "“想”表示打算，尚未实现，不能与完成体“了”搭配；“想回了家”不成立，应说“想回家吃饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
