INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13195, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13195, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按照一定的标准把事物归类并进行管理。", "primary_collocate": null, "pronunciation": "fēn lèi guǎn lǐ", "ipa": "fən˥ lei˥˩ kwan˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "亚洲一些城市则加强垃圾分类管理，规定居民必须把塑料垃圾分开投放，否则会被罚款。", "target_word": "分类管理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "学校对图书实行分类管理。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的分类管理能让仓库更整齐。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市的商品分类管理做得很好。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾分类管理需要大家一起做。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对文件进行分类管理，找起来很快。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品的分类管理很重要，不能放错。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仓库的零件都做了分类管理，找起来很方便。", "target_word": "分类管理", "complexity_tier": "T3", "furigana": "zhè ge cāngkù de língjiàn dōu zuò le fēnlèi guǎnlǐ, zhǎo qǐlái hěn fāngbiàn.", "sentence_source": "generated"}, {"text": "社区开始了垃圾分类管理。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的药品实行分类管理，每种药都有位置。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分類管理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按标准归类后进行的管理制度或办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b637169d-fc3a-4445-b0ef-7e8b7705b7e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13195, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“垃圾价格”说不通，垃圾不谈价格。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：垃圾颜色与“规定分开投放、罚款”的管理语境无关。"}, {"text": "分类管理", "is_correct": true, "explanation": "分类管理：按标准归类并进行管理，与“规定居民分开投放”相符。"}, {"text": "习惯", "is_correct": false, "explanation": "搭配：“垃圾习惯”搭配不当，不能说加强垃圾习惯。"}], "explanations": {"价格": "搭配：“垃圾价格”说不通，垃圾不谈价格。", "颜色": "语义：垃圾颜色与“规定分开投放、罚款”的管理语境无关。", "分类管理": "分类管理：按标准归类并进行管理，与“规定居民分开投放”相符。", "习惯": "搭配：“垃圾习惯”搭配不当，不能说加强垃圾习惯。"}, "sentence_index": 0, "correct_answer": "分类管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们分类管理合作，效率很高。", "explanation": "这里应该用〈分工〉。分工合作指各人担任不同任务；分类管理指按标准归类并管理，不说分类管理合作。"}, {"text": "他每天早上都分类管理早饭。", "explanation": "这里应该用〈准备〉。早饭要用准备或吃，分类管理指按标准归类并管理，不能用于饮食。"}, {"text": "老师把学生分类管理成三组。", "explanation": "这里应该用〈分组〉。把人分成若干组要用分组，分类管理指归类并管理，不说分类管理成三组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能被放错，与“药品”的存放语境不合。"}, {"text": "分类管理", "is_correct": true, "explanation": "分类管理：按标准归类并进行管理，说明药品为什么要有规范的管理，不能放错。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：药品不谈心情，“心情”与“放错”搭配不当。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气与药品的存放无关，句意不通。"}], "explanations": {"天气": "语义：天气不能被放错，与“药品”的存放语境不合。", "分类管理": "分类管理：按标准归类并进行管理，说明药品为什么要有规范的管理，不能放错。", "心情": "搭配：药品不谈心情，“心情”与“放错”搭配不当。", "脾气": "语义：脾气与药品的存放无关，句意不通。"}, "sentence_index": 6, "correct_answer": "分类管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师把任务分类管理给每个学生。", "explanation": "这里应该用〈分配〉。任务的分派要用分配，分类管理指按标准归类并管理，不说把任务分类管理给学生。"}, {"text": "请把垃圾分类管理投放。", "explanation": "这里应该用〈分开〉。把垃圾分开投放是具体动作，分类管理指一套归类管理办法，不能用来修饰投放。"}, {"text": "他把资料分类管理成三点。", "explanation": "这里应该用〈归纳〉。把资料概括成几点要用归纳，分类管理指归类并管理，不说分类管理成三点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只分类管理很有效。", "corrected_sentence": "这项分类管理很有效。", "error_description": "“分类管理”作为制度义的名词，量词应用“项”（或“套”）；“只”多用于动物和小件物品，不能用于管理。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校实行了过分类管理。", "corrected_sentence": "学校实行过分类管理。", "error_description": "“过”表示经历，与“了”不能同时用于同一动词；表示曾经实行，只用“过”，应说“实行过分类管理”，“了”多余。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
