INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13197, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把资金、物品等投入某个领域或地方。", "primary_collocate": null, "pronunciation": "tóu fàng", "ipa": "tʰoʊ˧˥ fɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "亚洲一些城市则加强垃圾分类管理，规定居民必须把塑料垃圾分开投放，否则会被罚款。", "target_word": "投放", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司为了卖新车，投放了很多广告。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府向市场投放了大量资金。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市里投放了很多共享单车。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂把新产品投放到市场。", "target_word": "投放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人往河里投放了很多鱼苗。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校附近新投放了许多垃圾桶。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府计划向灾区投放更多物资。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把旧衣服投放到这个箱子里。", "target_word": "投放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场往池塘里投放了饲料。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "投放了", "label": "体标：完成"}, {"form": "投放过", "label": "体标：经历"}, {"form": "投放量", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把资金、产品、广告等投入市场或某个领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d5ca48-c41f-404e-b8aa-feb7d9f3a2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13197, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投放", "is_correct": true, "explanation": "正确：“分开投放”表示把垃圾放到指定地点回收，与“垃圾分类管理”的语境相符。"}, {"text": "生产", "is_correct": false, "explanation": "语义：塑料垃圾是废弃物，不能被“生产”，与句中“垃圾分类管理”的语境不符。"}, {"text": "销售", "is_correct": false, "explanation": "搭配：“销售”的宾语多为商品，不能说“销售塑料垃圾”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：垃圾不能被“种植”，与句意完全不符。"}], "explanations": {"投放": "正确：“分开投放”表示把垃圾放到指定地点回收，与“垃圾分类管理”的语境相符。", "生产": "语义：塑料垃圾是废弃物，不能被“生产”，与句中“垃圾分类管理”的语境不符。", "销售": "搭配：“销售”的宾语多为商品，不能说“销售塑料垃圾”。", "种植": "语义：垃圾不能被“种植”，与句意完全不符。"}, "sentence_index": 0, "correct_answer": "投放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校投放了一场比赛。", "explanation": "这里应该用〈举办〉。投放指把资金、物资投入某个领域或地方，不用于组织活动。"}, {"text": "老师投放了每个学生的座位。", "explanation": "这里应该用〈安排〉。投放用于资金、物品投入某处，不用于安排座位。"}, {"text": "政府投放了一批荣誉证书。", "explanation": "这里应该用〈颁发〉。投放指把物资、资金投入市场或地区，不用于授予荣誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13197, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投放", "is_correct": true, "explanation": "正确：“新投放了许多垃圾桶”表示学校附近新设置了垃圾桶，与语境相符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“新拆除”与“新”所表达的增设之义相矛盾。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”多用于矿藏、潜力等，不能与“垃圾桶”搭配。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁”是彻底毁掉，与学校附近新增垃圾桶的语境不符。"}], "explanations": {"投放": "正确：“新投放了许多垃圾桶”表示学校附近新设置了垃圾桶，与语境相符。", "拆除": "语义：“新拆除”与“新”所表达的增设之义相矛盾。", "挖掘": "搭配：“挖掘”多用于矿藏、潜力等，不能与“垃圾桶”搭配。", "销毁": "语义：“销毁”是彻底毁掉，与学校附近新增垃圾桶的语境不符。"}, "sentence_index": 6, "correct_answer": "投放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他朝窗户投放了一块石头。", "explanation": "这里应该用〈投掷〉。投放表示把资金、物资投入某个领域或地方，不用于用力扔出去。"}, {"text": "球员在比赛中投放了三个三分球。", "explanation": "这里应该用〈投篮〉。投放指把资金、物资投入某个领域或地方，不能表示把球投进篮筐。"}, {"text": "他往墙上投放了一根钉子。", "explanation": "这里应该用〈钉〉。投放指把资金、物资投入某个领域或地方，不能表示把钉子钉进墙里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂向市场投放了了一批新的洗衣机。", "corrected_sentence": "工厂向市场投放了一批新的洗衣机。", "error_description": "错误形式：“投放了了”。正确形式：“投放了”。“了”只能出现一次，多出的一个应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
