INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13200, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有好处；有帮助。", "primary_collocate": null, "pronunciation": "yǒu yì", "ipa": "joʊ˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "这些措施虽然有时给生活带来不便，但长期来看对环境有益。", "target_word": "有益", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "多喝水对身体有益。", "target_word": "有益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "运动对健康很有益。", "target_word": "有益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "睡前读书对睡眠有益。", "target_word": "有益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书对孩子学习非常有益。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个活动对大家都有益。", "target_word": "有益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃水果对小朋友的身体有益。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提的建议对公司的发展很有益。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听音乐对放松心情有益。", "target_word": "有益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次旅行让我学到了很多有益的东西。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有益于", "label": "带介词的形式"}, {"form": "有益的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "对人、事物或环境有好处、有帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d5ca48-c41f-404e-b8aa-feb7d9f3a2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有益", "is_correct": true, "explanation": "有益（yǒu yì）：有好处、有帮助，与本义一致。"}, {"text": "右翼", "is_correct": false, "explanation": "右翼（yòu yì）：第一个音节声调不同，yǒu 为第三声，yòu 为第四声，意思是右边的翅膀或右翼。"}, {"text": "游艺", "is_correct": false, "explanation": "游艺（yóu yì）：第一个音节声调不同，yóu 为第二声，意思是游戏、娱乐活动。"}, {"text": "有戏", "is_correct": false, "explanation": "有戏（yǒu xì）：第二个音节声母不同，xì 与 yì 的声母不同，意思是有希望、有成功的可能。"}, {"text": "有疑", "is_correct": false, "explanation": "有疑（yǒu yí）：第二个音节声调不同，yí 为第二声，意思是有疑问、有怀疑。"}], "explanations": {"有益": "有益（yǒu yì）：有好处、有帮助，与本义一致。", "右翼": "右翼（yòu yì）：第一个音节声调不同，yǒu 为第三声，yòu 为第四声，意思是右边的翅膀或右翼。", "游艺": "游艺（yóu yì）：第一个音节声调不同，yóu 为第二声，意思是游戏、娱乐活动。", "有戏": "有戏（yǒu xì）：第二个音节声母不同，xì 与 yì 的声母不同，意思是有希望、有成功的可能。", "有疑": "有疑（yǒu yí）：第二个音节声调不同，yí 为第二声，意思是有疑问、有怀疑。"}, "sentence_index": null, "correct_answer": "有益"}, "level_3": {"options": [{"text": "有益", "is_correct": true, "explanation": "有益：对环境有好处，与前文「长期来看」的正面结论一致。"}, {"text": "有趣", "is_correct": false, "explanation": "搭配：「有趣」形容事物令人感兴趣，不能说「对环境有趣」。"}, {"text": "有名", "is_correct": false, "explanation": "语义：「有名」指名气大，与环境的好处无关，句意不通。"}, {"text": "有礼", "is_correct": false, "explanation": "搭配：「有礼」形容人懂礼貌，环境不能「有礼」。"}], "explanations": {"有益": "有益：对环境有好处，与前文「长期来看」的正面结论一致。", "有趣": "搭配：「有趣」形容事物令人感兴趣，不能说「对环境有趣」。", "有名": "语义：「有名」指名气大，与环境的好处无关，句意不通。", "有礼": "搭配：「有礼」形容人懂礼貌，环境不能「有礼」。"}, "sentence_index": 0, "correct_answer": "有益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次进攻很有益。", "explanation": "这里应该用〈有效〉。有益说事物对人有好处，进攻的成效要用有效，不说有益。"}, {"text": "今天下午我很有益，我们去看电影吧。", "explanation": "这里应该用〈有空〉。有益说事物对人有好处，表示时间充裕、可以做事要用有空，不说人很有益。"}, {"text": "他的脾气很有益。", "explanation": "这里应该用〈好〉。有益说对人或环境有好处，形容性情要用好，不说有益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有益", "is_correct": true, "explanation": "有益（yǒu yì）：有好处、有帮助，与本义一致。"}, {"text": "优异", "is_correct": false, "explanation": "优异（yōu yì）：第一个音节声调不同，yōu 为第一声，意思是优秀、出色。"}, {"text": "游移", "is_correct": false, "explanation": "游移（yóu yí）：两个音节声调都不同，意思是犹豫不定。"}, {"text": "有依", "is_correct": false, "explanation": "有依（yǒu yī）：第二个音节声调不同，yī 为第一声，意思是有依靠。"}, {"text": "语义", "is_correct": false, "explanation": "语义（yǔ yì）：第一个音节韵母不同，yǔ 与 yǒu 韵母不同，意思是词语或句子表达的意义。"}], "explanations": {"有益": "有益（yǒu yì）：有好处、有帮助，与本义一致。", "优异": "优异（yōu yì）：第一个音节声调不同，yōu 为第一声，意思是优秀、出色。", "游移": "游移（yóu yí）：两个音节声调都不同，意思是犹豫不定。", "有依": "有依（yǒu yī）：第二个音节声调不同，yī 为第一声，意思是有依靠。", "语义": "语义（yǔ yì）：第一个音节韵母不同，yǔ 与 yǒu 韵母不同，意思是词语或句子表达的意义。"}, "sentence_index": null, "correct_answer": "有益"}, "level_3": {"options": [{"text": "有益", "is_correct": true, "explanation": "有益：对小朋友的身体有好处，与「吃水果」的语境一致。"}, {"text": "有序", "is_correct": false, "explanation": "搭配：「有序」形容事情有条理，不用来说身体。"}, {"text": "有声", "is_correct": false, "explanation": "语义：「有声」指有声音，与身体的好处无关，句意不通。"}, {"text": "有色", "is_correct": false, "explanation": "语义：「有色」指带颜色，身体不能说有色，句意不通。"}], "explanations": {"有益": "有益：对小朋友的身体有好处，与「吃水果」的语境一致。", "有序": "搭配：「有序」形容事情有条理，不用来说身体。", "有声": "语义：「有声」指有声音，与身体的好处无关，句意不通。", "有色": "语义：「有色」指带颜色，身体不能说有色，句意不通。"}, "sentence_index": 6, "correct_answer": "有益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手很有益。", "explanation": "这里应该用〈有名〉。有益说事物对人有好处，形容歌手的名气要用有名，不说有益。"}, {"text": "他跑得很有益。", "explanation": "这里应该用〈快〉。有益说对人或事物有好处，形容速度要用快，不说有益。"}, {"text": "他的牙齿很有益。", "explanation": "这里应该用〈整齐〉。有益说对人或事物有好处，形容牙齿要用整齐，不说有益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早起散步身体有益。", "corrected_sentence": "早起散步对身体有益。", "error_description": "错误形式：“身体有益”。“有益”的受益对象需用介词“对”引出，应为“对身体有益”，“对”不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "规律运动心脏很有益。", "corrected_sentence": "规律运动对心脏很有益。", "error_description": "「有益」前面要用介词「对」引出受益对象，「对」不能省略。应改为「规律运动对心脏很有益」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
