INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生活在海洋中的各种生物的总称，包括鱼、虾、贝、海藻等。", "primary_collocate": null, "pronunciation": "hǎi yáng shēng wù", "ipa": "xai̯˨˩˦ jɑŋ˧˥ ʂɤŋ˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "科学家指出，塑料在自然环境中很难分解，会对海洋生物造成伤害。", "target_word": "海洋生物", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "海龟、鲸鱼和海带都是海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师常常带学生研究海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水太脏，海洋生物就会生病。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深海里有很多我们没见过的海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海洋生物需要干净的海水才能活下去。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去海边看了很多有趣的海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民说，今年捕到的海洋生物比去年少。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在博物馆里看到一种发光的海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海洋生物的种类比陆地上的少吗？", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "海洋中各种生物的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d5ca48-c41f-404e-b8aa-feb7d9f3a2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋生物", "is_correct": true, "explanation": "海洋生物：指海里生活的动物和植物，是会受到伤害的生物。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：「造成伤害」不能用于名字。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不会受到伤害，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以受伤害的对象，句意不通。"}], "explanations": {"海洋生物": "海洋生物：指海里生活的动物和植物，是会受到伤害的生物。", "名字": "搭配：「造成伤害」不能用于名字。", "时间": "语义：时间是抽象概念，不会受到伤害，句意不通。", "天气": "语义：天气不是可以受伤害的对象，句意不通。"}, "sentence_index": 0, "correct_answer": "海洋生物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今晚点了一盘海洋生物。", "explanation": "这里应该用〈海鲜〉。海洋生物是生物学概念，指海里生活的动物和植物，点菜时的食材要说海鲜。"}, {"text": "这艘船在海洋生物上航行。", "explanation": "这里应该用〈海上〉。海洋生物指海里生活的动植物，船航行的是海面这个地方，不能说在海洋生物上。"}, {"text": "我们在海洋生物里游泳，水很清。", "explanation": "这里应该用〈海里〉。海洋生物指海里生活的生物，不能当作游泳的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋生物", "is_correct": true, "explanation": "海洋生物：海边看到的有趣事物，符合「看了很多」的语境。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：「看」不能用于数学，「有趣的数学」在此处搭配不当。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「看」不能用于味道，句意不通。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法是抽象规则，不能用眼睛去看，句意不通。"}], "explanations": {"海洋生物": "海洋生物：海边看到的有趣事物，符合「看了很多」的语境。", "数学": "搭配：「看」不能用于数学，「有趣的数学」在此处搭配不当。", "味道": "搭配：「看」不能用于味道，句意不通。", "语法": "语义：语法是抽象规则，不能用眼睛去看，句意不通。"}, "sentence_index": 6, "correct_answer": "海洋生物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "草原上生长着很多海洋生物。", "explanation": "这里应该用〈植物〉。海洋生物指海里生活的生物，草原上的植物不能说成海洋生物。"}, {"text": "森林里住着很多海洋生物。", "explanation": "这里应该用〈野生动物〉。海洋生物指生活在海里的生物，森林里的动物不能说成海洋生物。"}, {"text": "沙漠里走着很多海洋生物。", "explanation": "这里应该用〈骆驼〉。骆驼生活在沙漠，海洋生物指海里生活的生物，不能用于沙漠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个博物馆里有很多有趣海洋生物。", "corrected_sentence": "这个博物馆里有很多有趣的海洋生物。", "error_description": "「有趣」修饰名词时要加「的」。「有趣海洋生物」应改为「有趣的海洋生物」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "深海里很多海洋生物。", "corrected_sentence": "深海里有很多海洋生物。", "error_description": "错误形式：“深海里很多海洋生物”。存在句需要动词“有”，应为“深海里有很多海洋生物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
