INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13205, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起努力，为了共同的目标而奋斗。", "primary_collocate": null, "pronunciation": "gòng tóng nǔ lì", "ipa": "kʊŋ˥˩ tʰʊŋ˧˥ nu˨˩˦ li˥˩", "syllable_count": 4, "sentences": [{"text": "专家认为，有效的监管需要政府、企业和公众共同努力。", "target_word": "共同努力", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "要保护河水，大家需要共同努力。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同学共同努力，终于完成了作业。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要全家共同努力，生活就会变好。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过大家共同努力，比赛我们赢了。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让城市更干净，我们要共同努力。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望学生和家长共同努力。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国人民共同努力，让边境更安全。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队共同努力，打进了决赛。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的成功是大家共同努力的结果。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "众人为共同目标一起奋斗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d5ca48-c41f-404e-b8aa-feb7d9f3a2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13205, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共同努力", "is_correct": true, "explanation": "正确：“共同努力”表示大家为共同目标一起付出努力，与句中“政府、企业和公众”多方协作的语境相符。"}, {"text": "单独努力", "is_correct": false, "explanation": "语义：“单独”指一个人做，与句中“政府、企业和公众”这些多方主体冲突，句意不通。"}, {"text": "相互竞争", "is_correct": false, "explanation": "语义：“竞争”与“有效的监管需要……”所要求的协作方向相反，句意矛盾。"}, {"text": "努力过", "is_correct": false, "explanation": "体貌：“过”表示曾经发生过的经历，与句中“需要”所表达的现在或将来的要求不一致。"}], "explanations": {"共同努力": "正确：“共同努力”表示大家为共同目标一起付出努力，与句中“政府、企业和公众”多方协作的语境相符。", "单独努力": "语义：“单独”指一个人做，与句中“政府、企业和公众”这些多方主体冲突，句意不通。", "相互竞争": "语义：“竞争”与“有效的监管需要……”所要求的协作方向相反，句意矛盾。", "努力过": "体貌：“过”表示曾经发生过的经历，与句中“需要”所表达的现在或将来的要求不一致。"}, "sentence_index": 0, "correct_answer": "共同努力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们共同努力去公园散步。", "explanation": "这里应该用〈一起〉。“共同努力”表示为共同目标付出辛苦，去公园散步不需要努力，不能这样用。"}, {"text": "我一个人共同努力，完成了这份报告。", "explanation": "这里应该用〈独自〉。“共同”指多人一起做事，只有一个人时不能用“共同”。"}, {"text": "我们共同努力，把一个人推下了水。", "explanation": "这里误用了〈共同努力〉的意思。“共同努力”指为共同目标出力，用于伤害他人的行为不合适，这种情况应说合伙作恶，而不是共同努力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共同努力", "is_correct": true, "explanation": "正确：“共同努力”表示学生和家长一起为共同目标付出努力，符合“老师希望”的期望语境。"}, {"text": "相互埋怨", "is_correct": false, "explanation": "语义：“埋怨”与“老师希望”所表达的合作期望相反，句意矛盾。"}, {"text": "停止努力", "is_correct": false, "explanation": "语义：“停止努力”与“老师希望”所表达的积极愿望相矛盾。"}, {"text": "独自努力", "is_correct": false, "explanation": "搭配：“独自”只指一个人，与“学生和家长”这样的复数主体不搭配。"}], "explanations": {"共同努力": "正确：“共同努力”表示学生和家长一起为共同目标付出努力，符合“老师希望”的期望语境。", "相互埋怨": "语义：“埋怨”与“老师希望”所表达的合作期望相反，句意矛盾。", "停止努力": "语义：“停止努力”与“老师希望”所表达的积极愿望相矛盾。", "独自努力": "搭配：“独自”只指一个人，与“学生和家长”这样的复数主体不搭配。"}, "sentence_index": 6, "correct_answer": "共同努力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两支球队共同努力，最后把对方打败了。", "explanation": "这里应该用〈竞争〉。“共同努力”要求参与者目标一致，对方是对手时不能用。"}, {"text": "大家共同努力，偷懒睡起了大觉。", "explanation": "这里误用成了偷懒的意思。“共同努力”表示大家为同一目标付出辛苦，偷懒与之意思相反，句子不通。"}, {"text": "我们共同努力，突然下起了雨。", "explanation": "这里误用了〈共同努力〉的意思。“共同努力”指人为同一目标出力，下雨是自然现象，不能靠努力促成，这里用法错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们和朋友共同共同努力，完成了这个项目。", "corrected_sentence": "我们和朋友共同努力，完成了这个项目。", "error_description": "重复错误：“共同”只需说一次，应说“共同努力”，不能说“共同共同努力”，多写了一个“共同”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们三个人共同共同努力，把这件事做好了。", "corrected_sentence": "我们三个人共同努力，把这件事做好了。", "error_description": "重复错误：“共同”只需说一次，应说“共同努力”，不能说“共同共同努力”，多写了一个“共同”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
