INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13207, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人或事物经历过的过程、经历。", "primary_collocate": null, "pronunciation": "lì chéng", "ipa": "li˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "在全球环境政策的演进历程中，立法手段日益成为各国应对塑料污染的核心工具。", "target_word": "历程", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这一历程并非线性前进，而是在资源危机、环境压力与科学突破的交织推动下，不断重构能源获取的范式。", "target_word": "历程", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这本书写了他的成长历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的发展历程很不容易。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给我们讲了学习汉语的历程。", "target_word": "历程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段历程让我学到了很多。", "target_word": "历程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览介绍了这座城市的历程。", "target_word": "历程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回忆这一路的历程，她很感动。", "target_word": "历程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了自己创业的历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一段难忘的人生历程。", "target_word": "历程", "complexity_tier": "T3", "furigana": "zhè shì yí duàn nán wàng de rén shēng lì chéng", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段历程", "label": "量词"}, {"form": "心路历程", "label": "复合"}, {"form": "歷程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物所经历的整个过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0fbe80-3322-4a2e-a4d7-d218a61d1e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13207, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程（第四声）指经历的过程，与听到的读音一致。"}, {"text": "里程", "is_correct": false, "explanation": "lǐ chéng（第三声）与 lì chéng（第四声）声调不同，里程指路程的长度。"}, {"text": "日程", "is_correct": false, "explanation": "rì chéng 与 lì chéng 声母不同（r 与 l），日程指每天的安排。"}, {"text": "立场", "is_correct": false, "explanation": "lì chǎng 与 lì chéng 第二音节的元音与声调不同（e 与 a，二声与三声），立场指对问题的态度。"}], "explanations": {"历程": "历程（第四声）指经历的过程，与听到的读音一致。", "里程": "lǐ chéng（第三声）与 lì chéng（第四声）声调不同，里程指路程的长度。", "日程": "rì chéng 与 lì chéng 声母不同（r 与 l），日程指每天的安排。", "立场": "lì chǎng 与 lì chéng 第二音节的元音与声调不同（e 与 a，二声与三声），立场指对问题的态度。"}, "sentence_index": null, "correct_answer": "历程"}, "level_3": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程指经历的发展过程，与“演进”搭配，指政策逐步发展的过程。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句的书面语体不合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“演进”的对象是政策、制度等发展过程，不能说“演进颜色”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，与政策的演进无关。"}], "explanations": {"历程": "历程指经历的发展过程，与“演进”搭配，指政策逐步发展的过程。", "玩意儿": "语域：“玩意儿”是口语说法，与这句的书面语体不合。", "颜色": "搭配：“演进”的对象是政策、制度等发展过程，不能说“演进颜色”。", "体重": "语义：“体重”指身体的重量，与政策的演进无关。"}, "sentence_index": 0, "correct_answer": "历程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在公园里发现了一处很漂亮的历程。", "explanation": "这里应该用〈景点〉。可以游览的地方是景点；历程指经历的过程，不指游览的地方。"}, {"text": "妈妈在厨房里切菜，用的是一把很大的历程。", "explanation": "这里应该用〈菜刀〉。切菜用的是菜刀；历程指经历的过程，不是工具。"}, {"text": "这段历程一直通向山顶的寺庙。", "explanation": "这里应该用〈路径〉。通向某处的小道是路径；历程指经历的过程，不指道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13207, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程（第四声）指经历的过程，与听到的读音一致。"}, {"text": "立正", "is_correct": false, "explanation": "lì zhèng 与 lì chéng 第二音节声母不同（zh 与 ch），立正指军人站立的姿势。"}, {"text": "力争", "is_correct": false, "explanation": "lì zhēng 与 lì chéng 第二音节声母与声调都不同（zh 与 ch，一声与二声），力争指努力争取。"}, {"text": "日程", "is_correct": false, "explanation": "rì chéng 与 lì chéng 声母不同（r 与 l），日程指每天的安排。"}], "explanations": {"历程": "历程（第四声）指经历的过程，与听到的读音一致。", "立正": "lì zhèng 与 lì chéng 第二音节声母不同（zh 与 ch），立正指军人站立的姿势。", "力争": "lì zhēng 与 lì chéng 第二音节声母与声调都不同（zh 与 ch，一声与二声），力争指努力争取。", "日程": "rì chéng 与 lì chéng 声母不同（r 与 l），日程指每天的安排。"}, "sentence_index": null, "correct_answer": "历程"}, "level_3": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程指城市走过的发展道路，展览可以介绍这一过程。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：展览介绍的是可以展示的内容，“眼泪”不能作为城市的介绍对象。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人的身体长度，城市没有身高，不搭配。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“噪音”是刺耳的声音，不是展览可以介绍的城市内容。"}], "explanations": {"历程": "历程指城市走过的发展道路，展览可以介绍这一过程。", "眼泪": "语义：展览介绍的是可以展示的内容，“眼泪”不能作为城市的介绍对象。", "身高": "搭配：“身高”指人的身体长度，城市没有身高，不搭配。", "噪音": "语义：“噪音”是刺耳的声音，不是展览可以介绍的城市内容。"}, "sentence_index": 6, "correct_answer": "历程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电脑同时运行了许多历程，所以变慢了。", "explanation": "这里应该用〈进程〉。正在运行的程序是进程，电脑同时运行多个程序要说进程；历程指经历的过程，不指计算机的运行。"}, {"text": "他很喜欢读中国的历程书。", "explanation": "这里应该用〈历史〉。读的是历史书，历程指经历的过程，不说“历程书”。"}, {"text": "妈妈在历程里做饭。", "explanation": "这里应该用〈厨房〉。做饭的地方是厨房；历程指经历的过程，不能表示做饭的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他记录下了一段漫长地历程。", "corrected_sentence": "他记录下了一段漫长的历程。", "error_description": "修饰语错误：“历程”前的修饰语“漫长”应用“的”连接，不用“地”；“地”用于动词前。应说“漫长的历程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他回忆起了那片难忘的人生历程。", "corrected_sentence": "他回忆起了那段难忘的人生历程。", "error_description": "量词错误：“历程”用“段”计量，应说“那段历程”；“片”不能用来计量历程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
