INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13210, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不可以，表示禁止或不允许做某事。", "primary_collocate": null, "pronunciation": "bù kě", "ipa": "pu⁵¹ kʰɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这里是医院，请大家不可大声说话。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进了考场，学生不可带手机。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路的时候，不可看手机。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水很深，小孩子不可一个人下水。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药要按时吃，不可随便多吃。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在图书馆里，不可吃东西。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，考试时不可看别人的答案。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河很危险，大家不可靠近。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人不可说谎，要诚实。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有雪，开车时不可超速。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "情态动词，书面，表示禁止或不允许做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可", "is_correct": true, "explanation": "正确：「不可」表示禁止，与「请大家……」的礼貌提醒和医院需要安静的语境相符。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示必要、强制要求，填入后变成“请大家必须大声说话”，与医院应当安静的语境相反。"}, {"text": "应该", "is_correct": false, "explanation": "语义：「应该」表示应当或建议，填入后变成“请大家应该大声说话”，与医院的安静要求相反。"}, {"text": "要", "is_correct": false, "explanation": "语域：「要」口语化，且此处表示应当，与书面的禁止语气不一致；语义上也与医院的安静环境矛盾。"}], "explanations": {"不可": "正确：「不可」表示禁止，与「请大家……」的礼貌提醒和医院需要安静的语境相符。", "必须": "语义：「必须」表示必要、强制要求，填入后变成“请大家必须大声说话”，与医院应当安静的语境相反。", "应该": "语义：「应该」表示应当或建议，填入后变成“请大家应该大声说话”，与医院的安静要求相反。", "要": "语域：「要」口语化，且此处表示应当，与书面的禁止语气不一致；语义上也与医院的安静环境矛盾。"}, "sentence_index": 0, "correct_answer": "不可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空气是人类生存不可或缺的。", "explanation": "这里“不可或缺”是另一个义项，表示必不可少，与禁止或不能无关；此句的“不可”不能用来表示禁止。"}, {"text": "我不可游泳，水性太差了。", "explanation": "这里应该用〈不会〉，说自己没有这项能力；不可表示禁止或不可能，不用来说自己的能力不足。"}, {"text": "听到这个消息，我不可相信这是真的。", "explanation": "这里应该用〈不敢〉与“相信”搭配，表示难以置信；不可表示禁止，说成“不许相信”，与句意不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可", "is_correct": true, "explanation": "正确：「不可」表示禁止，与老师的规定和“考试时”的公平要求相符。"}, {"text": "可以", "is_correct": false, "explanation": "语义：「可以」表示允许，填入后变成“考试时可以看别人的答案”，与老师禁止作弊的规定矛盾。"}, {"text": "能", "is_correct": false, "explanation": "语义：「能」表示许可或能力，填入后变成“考试时能看别人的答案”，与老师的规定和考试公平的要求相反。"}, {"text": "得", "is_correct": false, "explanation": "语义：「得」表示必须，填入后变成“考试时得看别人的答案”，把作弊说成了要求，与老师的规定矛盾。"}], "explanations": {"不可": "正确：「不可」表示禁止，与老师的规定和“考试时”的公平要求相符。", "可以": "语义：「可以」表示允许，填入后变成“考试时可以看别人的答案”，与老师禁止作弊的规定矛盾。", "能": "语义：「能」表示许可或能力，填入后变成“考试时能看别人的答案”，与老师的规定和考试公平的要求相反。", "得": "语义：「得」表示必须，填入后变成“考试时得看别人的答案”，把作弊说成了要求，与老师的规定矛盾。"}, "sentence_index": 6, "correct_answer": "不可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子身体很好，不可运动。", "explanation": "这里应该用〈不宜〉，表示身体状况不适合运动；不可表示禁止，与“身体很好”的语境矛盾，说成了“不许运动”。"}, {"text": "他一直很骄傲，总是不可理睬别人。", "explanation": "这里应该用〈不屑〉，表示看不起而不予理会；不可表示禁止，把态度说成了规定，与“骄傲”的语境不合。"}, {"text": "这个方法很简单，你不可试试。", "explanation": "这里应该用〈不妨〉，表示可以试一试、没有坏处；不可表示禁止，与“很简单”的鼓励语气相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里是电影院，请大家不可了大声喧哗。", "corrected_sentence": "这里是电影院，请大家不可大声喧哗。", "error_description": "「不可」是情态动词，后面不能直接加动态助词「了」，应删去「了」，说「请大家不可大声喧哗」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们，上课时很不可玩手机。", "corrected_sentence": "学生们，上课时不可玩手机。", "error_description": "“不可”是情态动词，不能受程度副词“很”修饰，应删去“很”，说“上课时不可玩手机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
