INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "实体指客观存在的事物，比如一个物体或一个人。", "primary_collocate": null, "pronunciation": "shí tǐ", "ipa": "ʂɻ̩³⁵ tʰi²¹⁴", "syllable_count": 2, "sentences": [{"text": "桌子、人和房子都是实体。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词指的是一种看得见的实体。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想法不是实体，我们看不到它。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山川和河流都是实体，而情绪不是。", "target_word": "实体", "complexity_tier": "T3", "furigana": "shí tǐ", "sentence_source": "generated"}, {"text": "影子不是实体，只是光的变化。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实体和名字不一样，名字只是叫法。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头、桌子这些能用手摸到的东西，都是实体。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头是实体，梦不是。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮是一个实体，它离我们很远。", "target_word": "实体", "complexity_tier": "T3", "furigana": "shí tǐ", "sentence_source": "generated"}, {"text": "实体可以是物体，也可以是一个人。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "實體", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "哲学或学术用语，客观存在的事物，可指物体或人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实体", "is_correct": true, "explanation": "正确：实体指客观存在的事物，桌子、人和房子都符合这一点。"}, {"text": "想法", "is_correct": false, "explanation": "语义：“想法”指头脑中的念头，桌子、人和房子是看得见、摸得着的东西，不能说是想法。"}, {"text": "梦", "is_correct": false, "explanation": "语义：“梦”指睡眠中出现的景象，桌子、人和房子不是梦，这样说与常识相反。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”只用来说人或动物的样子，不能用来概括桌子和房子。"}], "explanations": {"实体": "正确：实体指客观存在的事物，桌子、人和房子都符合这一点。", "想法": "语义：“想法”指头脑中的念头，桌子、人和房子是看得见、摸得着的东西，不能说是想法。", "梦": "语义：“梦”指睡眠中出现的景象，桌子、人和房子不是梦，这样说与常识相反。", "外貌": "体貌：“外貌”只用来说人或动物的样子，不能用来概括桌子和房子。"}, "sentence_index": 0, "correct_answer": "实体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的实体，是一个关于友谊的故事。", "explanation": "这里应该用〈本质〉。“实体”指客观存在的事物，不表示事情的根本属性，不能说“这部电影的实体”。"}, {"text": "这个方案在纸面上很完美，但实体上行不通。", "explanation": "这里应该用〈实际〉。“实体”指客观存在的事物，不表示“实际、实在”的意思，不能说“实体上”。"}, {"text": "警方还没有查清这起事件的实体。", "explanation": "这里应该用〈真相〉。“实体”指客观存在的事物，不指事情的真实情况，不能用于查清事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实体", "is_correct": true, "explanation": "正确：「实体」指客观存在、能用手摸到的事物，石头和桌子都符合这一点。"}, {"text": "幻影", "is_correct": false, "explanation": "语义：「幻影」指虚幻的影像，不是客观存在的实物，填入后“都是幻影”与石头、桌子的实在性相反。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：「情绪」是心理状态，不能用手摸到，填入后“都是情绪”不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是事物的属性，不是能摸到的东西本身，填入后“都是颜色”与语境不符。"}], "explanations": {"实体": "正确：「实体」指客观存在、能用手摸到的事物，石头和桌子都符合这一点。", "幻影": "语义：「幻影」指虚幻的影像，不是客观存在的实物，填入后“都是幻影”与石头、桌子的实在性相反。", "情绪": "语义：「情绪」是心理状态，不能用手摸到，填入后“都是情绪”不通。", "颜色": "语义：「颜色」是事物的属性，不是能摸到的东西本身，填入后“都是颜色”与语境不符。"}, "sentence_index": 6, "correct_answer": "实体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次谈判的实体是价格，双方都很在意。", "explanation": "这里应该用〈核心〉，表示事情最关键的部分；实体指客观存在的事物，不能指谈判的关键。"}, {"text": "我们要抓住问题的实体，不要只看表面。", "explanation": "这里应该用〈本质〉，表示事物的根本属性；实体指客观存在的事物，不能指问题的本质。"}, {"text": "这份报告的实体部分很少，大多是空话。", "explanation": "这里应该用〈实质〉，表示内容的实际价值；实体指客观存在的事物，不能指报告的内容价值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只实体，可以用手摸到。", "corrected_sentence": "这是一个实体，可以用手摸到。", "error_description": "量词错误：“实体”前应用量词“个”。“只”多用于动物或成对物品中的一件，用在“实体”前是错误的，应改为“一个实体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块石头是一座实体，你可以拿在手里看。", "corrected_sentence": "这块石头是一个实体，你可以拿在手里看。", "error_description": "量词错误：“实体”前应用量词“个”。“座”多用于山、桥、房屋等大型物体，用在“实体”前是错误的，应改为“一个实体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
