INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体内部或表面产生大量气泡的现象。", "primary_collocate": null, "pronunciation": "fā pào", "ipa": "fa˥ pʰau˥˩", "syllable_count": 2, "sentences": [{"text": "这种新型塑料在高温加工时会迅速发泡，内部形成大量细小的气孔，因此密度大幅降低，重量也随之减轻。", "target_word": "发泡", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "洗手液遇到水就会发泡。", "target_word": "发泡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "咖啡店用蒸汽把牛奶发泡。", "target_word": "发泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种洗发水发泡很快，用一点就够。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小苏打放进醋里会发泡。", "target_word": "发泡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块香皂搓几下就发泡，很好用。", "target_word": "发泡", "complexity_tier": "T3", "furigana": "zhè kuài xiāng zào cuō jǐ xià jiù fā pào, hěn hǎo yòng.", "sentence_source": "generated"}, {"text": "工人把塑料加热，让它发泡变轻。", "target_word": "发泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牙膏发泡太多，我不喜欢。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用洗面奶在手心发泡，再洗脸。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣液倒进水里，搅一搅就发泡。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发泡了", "label": "体标"}, {"form": "发泡剂", "label": "复合"}, {"form": "發泡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体内部或表面产生大量气泡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发泡", "is_correct": true, "explanation": "发泡（fā pào）：物体内部或表面产生大量气泡。"}, {"text": "发报", "is_correct": false, "explanation": "发报（fā bào）与 fā pào 声母不同（b/p），声调相同，意思是拍发电报。"}, {"text": "发派", "is_correct": false, "explanation": "发派（fā pài）与 fā pào 韵母不同（ai/ao），声调相同，意思是分派、派遣。"}, {"text": "发票", "is_correct": false, "explanation": "发票（fā piào）比 fā pào 多一个介音 i，意思是开具的收款凭证。"}], "explanations": {"发泡": "发泡（fā pào）：物体内部或表面产生大量气泡。", "发报": "发报（fā bào）与 fā pào 声母不同（b/p），声调相同，意思是拍发电报。", "发派": "发派（fā pài）与 fā pào 韵母不同（ai/ao），声调相同，意思是分派、派遣。", "发票": "发票（fā piào）比 fā pào 多一个介音 i，意思是开具的收款凭证。"}, "sentence_index": null, "correct_answer": "发泡"}, "level_3": {"options": [{"text": "发泡", "is_correct": true, "explanation": "“高温加工时会迅速发泡”指塑料受热后内部产生大量气泡，与后文的气孔和密度降低相符。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割只是把材料分开，不会在材料内部形成气孔，与句意不符。"}, {"text": "压缩", "is_correct": false, "explanation": "语义：压缩会使体积变小、密度增大，与“密度大幅降低”矛盾。"}, {"text": "打磨", "is_correct": false, "explanation": "搭配：“打磨”作用于表面，不会使材料内部形成气孔，与“内部形成细小的气孔”矛盾。"}], "explanations": {"发泡": "“高温加工时会迅速发泡”指塑料受热后内部产生大量气泡，与后文的气孔和密度降低相符。", "切割": "语义：切割只是把材料分开，不会在材料内部形成气孔，与句意不符。", "压缩": "语义：压缩会使体积变小、密度增大，与“密度大幅降低”矛盾。", "打磨": "搭配：“打磨”作用于表面，不会使材料内部形成气孔，与“内部形成细小的气孔”矛盾。"}, "sentence_index": 0, "correct_answer": "发泡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服洗完以后，颜色很快就发泡了。", "explanation": "这里应该用〈褪色〉。衣服洗后颜色变淡应说“褪色”；“发泡”指产生气泡，与颜色变化无关，这里词义用错了。"}, {"text": "水放进冰箱里，过一夜就发泡了。", "explanation": "这里应该用〈结冰〉。水遇冷凝固成冰，应说“结冰”；“发泡”指产生大量气泡，与水变成固体无关，这里词义用错了。"}, {"text": "他一生气，脸就发泡了。", "explanation": "这里应该用〈涨红〉。生气时脸色变红应说“涨红”；“发泡”指物体产生气泡，不用来形容脸色，这里词义用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发泡", "is_correct": true, "explanation": "“让它发泡变轻”指加热后塑料内部产生气泡，体积膨胀、变轻，语境通顺。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”与句中的“加热”方向相反，降温也不会让塑料变轻。"}, {"text": "压缩", "is_correct": false, "explanation": "语义：“压缩”会使体积变小、密度变大，与“变轻”相矛盾。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”的结果是碎块，不能直接接“变轻”，搭配不当。"}], "explanations": {"发泡": "“让它发泡变轻”指加热后塑料内部产生气泡，体积膨胀、变轻，语境通顺。", "冷却": "语义：“冷却”与句中的“加热”方向相反，降温也不会让塑料变轻。", "压缩": "语义：“压缩”会使体积变小、密度变大，与“变轻”相矛盾。", "打碎": "搭配：“打碎”的结果是碎块，不能直接接“变轻”，搭配不当。"}, "sentence_index": 6, "correct_answer": "发泡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花苞遇到春天就会发泡。", "explanation": "这里应该用〈开花〉。花苞绽放是植物开放，应说“开花”；“发泡”指物体产生气泡，不能用于植物开放。"}, {"text": "毛衣用热水一洗就发泡了。", "explanation": "这里应该用〈收缩〉。毛衣遇热水变小，应说“收缩”；“发泡”指产生大量气泡，不表示物体缩小。"}, {"text": "这杯咖啡里的糖放进去，很快就发泡了。", "explanation": "这里应该用〈溶解〉。糖溶入水中是分子分散，并不产生泡沫，“发泡”不能用于此情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种沐浴球一放进水里就快很发泡。", "corrected_sentence": "这种沐浴球一放进水里就很快发泡。", "error_description": "语序错误：两个副词的顺序颠倒了，应为“很快”，说“就很快发泡”，不能说“就快很发泡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这罐牛奶用蒸汽一加热就发泡着。", "corrected_sentence": "这罐牛奶用蒸汽一加热就发泡了。", "error_description": "“着”表示状态持续，“一……就……”强调先后相继的结果，应用“了”，说“就发泡了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
