INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来盛放饭菜的盒子或容器，通常用于外卖或携带食物。", "primary_collocate": null, "pronunciation": "cān hé", "ipa": "tsʰan˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "近年来，以欧盟为代表的政治实体推行了系统性监管框架，通过《一次性塑料指令》明确禁用十类常见塑料消费品，如餐具、吸管与发泡餐盒，并要求成员国将指令转化为国内法，实现法律效力的属地化延伸。", "target_word": "餐盒", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "外卖的餐盒放在门口。", "target_word": "餐盒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把吃完的餐盒扔进垃圾桶。", "target_word": "餐盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个餐盒太小，装不下两个菜。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给我准备了一个餐盒。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐盒里有米饭、青菜和鸡蛋。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的餐盒又干净又结实。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把剩菜装进餐盒，带回家了。", "target_word": "餐盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热汤不能装在纸餐盒里，会漏。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中午公司送来了二十个餐盒。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "塑料餐盒", "label": "复合"}, {"form": "外卖餐盒", "label": "复合"}], "register": "中性", "sense_fingerprint": "外卖或携带食物用的饭菜容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐盒", "is_correct": true, "explanation": "餐盒指盛放饭菜的盒子，与餐具、吸管同属被禁的塑料消费品，“发泡餐盒”成立。"}, {"text": "纸巾", "is_correct": false, "explanation": "搭配：“发泡纸巾”不成词，纸巾也不是句中所列的被禁餐饮用品。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是文字资料，不是实物消费品，与餐具、吸管并列不成立。"}, {"text": "牙刷", "is_correct": false, "explanation": "搭配：“发泡牙刷”不成词，且牙刷不属于句中被禁的一次性餐饮用品。"}], "explanations": {"餐盒": "餐盒指盛放饭菜的盒子，与餐具、吸管同属被禁的塑料消费品，“发泡餐盒”成立。", "纸巾": "搭配：“发泡纸巾”不成词，纸巾也不是句中所列的被禁餐饮用品。", "食谱": "语义：食谱是文字资料，不是实物消费品，与餐具、吸管并列不成立。", "牙刷": "搭配：“发泡牙刷”不成词，且牙刷不属于句中被禁的一次性餐饮用品。"}, "sentence_index": 0, "correct_answer": "餐盒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去那家餐盒吃饭。", "explanation": "这里应该用〈餐厅〉。餐盒是盛放饭菜的盒子，不是吃饭的场所，“去……吃饭”要用餐厅。"}, {"text": "他坐在餐盒前写作业。", "explanation": "这里应该用〈书桌〉。坐着写作业要用书桌，餐盒是盛放饭菜的盒子，不能当桌子用。"}, {"text": "他穿上了那个餐盒。", "explanation": "这里应该用〈衣服〉。穿是穿衣服的动作，要用于衣物；餐盒是盛放饭菜的盒子，不能当作衣服穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐盒", "is_correct": true, "explanation": "“这家店的餐盒”指店里使用或出售的盒子，可以用“干净又结实”来形容，句意通顺。"}, {"text": "药片", "is_correct": false, "explanation": "语义：药片不是店里的盛放用具，不能用“干净又结实”形容，句子不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是饭店的物件，与句中“这家店”的语境不符。"}, {"text": "香烟", "is_correct": false, "explanation": "搭配：“干净”一般不用来形容香烟，“又干净又结实”与香烟搭配不当。"}], "explanations": {"餐盒": "“这家店的餐盒”指店里使用或出售的盒子，可以用“干净又结实”来形容，句意通顺。", "药片": "语义：药片不是店里的盛放用具，不能用“干净又结实”形容，句子不通。", "课本": "语义：课本不是饭店的物件，与句中“这家店”的语境不符。", "香烟": "搭配：“干净”一般不用来形容香烟，“又干净又结实”与香烟搭配不当。"}, "sentence_index": 6, "correct_answer": "餐盒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨了，他撑开了餐盒。", "explanation": "这里应该用〈雨伞〉。撑开用来挡雨的是雨伞，餐盒是盛放饭菜的盒子，不能用来挡雨。"}, {"text": "他开着餐盒去上班。", "explanation": "这里应该用〈汽车〉。开着去上班的是汽车等车辆，餐盒是盛放饭菜的盒子，不能当交通工具开。"}, {"text": "她把餐盒插进插座充电。", "explanation": "这里应该用〈充电器〉。插进插座充电的是充电器或插头，餐盒不是电器，不能插入插座。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我准备了一块餐盒，让我带去学校。", "corrected_sentence": "妈妈给我准备了一个餐盒，让我带去学校。", "error_description": "量词错误：“块”用于块状物，不能用来数餐盒，应改为“一个餐盒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我餐盒，别拿错了。", "corrected_sentence": "这是我的餐盒，别拿错了。", "error_description": "领属“的”漏掉：表示所属应说“我的餐盒”，不能说“我餐盒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
