INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13219, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13219, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国内法是指特定国家制定并适用于该国主权范围内的法律。", "primary_collocate": null, "pronunciation": "guó nèi fǎ", "ipa": "kuɔ˧˥ neɪ˥˩ fa˨˩˦", "syllable_count": 3, "sentences": [{"text": "近年来，以欧盟为代表的政治实体推行了系统性监管框架，通过《一次性塑料指令》明确禁用十类常见塑料消费品，如餐具、吸管与发泡餐盒，并要求成员国将指令转化为国内法，实现法律效力的属地化延伸。", "target_word": "国内法", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "国内法只在本国有效。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际条约要先变成国内法。", "target_word": "国内法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内法和国际法不一样。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院按国内法处理这个案子。", "target_word": "国内法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国的国内法有很多不同。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府把条约写进了国内法。", "target_word": "国内法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国公司也要遵守中国的国内法。", "target_word": "国内法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内法由本国的议会制定。", "target_word": "国内法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部国内法是去年通过的。", "target_word": "国内法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "國內法", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "与国际法相对，由一国制定、在该国主权范围内适用的法律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73af155f-4a0d-432b-a365-77d4bc223b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13219, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国内法", "is_correct": true, "explanation": "正确：指令要由成员国通过立法变成本国法律，即国内法。"}, {"text": "国际法", "is_correct": false, "explanation": "语义：「国际法」指国家之间共同遵守的法，成员国不能把指令转化为国际法，句意不合。"}, {"text": "条约", "is_correct": false, "explanation": "语义：条约是国家间的协议，不是由指令转化而来的本国法律，与句意不符。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：「玩意儿」是口语，与书面的「转化为……」不协调，而且不能指法律。"}], "explanations": {"国内法": "正确：指令要由成员国通过立法变成本国法律，即国内法。", "国际法": "语义：「国际法」指国家之间共同遵守的法，成员国不能把指令转化为国际法，句意不合。", "条约": "语义：条约是国家间的协议，不是由指令转化而来的本国法律，与句意不符。", "玩意儿": "语域：「玩意儿」是口语，与书面的「转化为……」不协调，而且不能指法律。"}, "sentence_index": 0, "correct_answer": "国内法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国内法抓住了小偷。", "explanation": "这里应该用〈警察〉。抓捕小偷的是警察，国内法是法律规范，不能用来抓人。"}, {"text": "两国签订了国内法。", "explanation": "这里应该用〈国际条约〉。两国之间签订的协议要说国际条约；国内法由一国自己制定，不能由两国签订。"}, {"text": "国内法受理了这个案子。", "explanation": "这里应该用〈法院〉。受理案件的是法院，国内法是法律规范，不能受理案件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国内法", "is_correct": true, "explanation": "正确：句中指政府把条约写进了本国的法律，即国内法。"}, {"text": "日记", "is_correct": false, "explanation": "语义：条约不会写进个人日记，写进的应是具有法律效力的规范，句意不合。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱记录烹饪方法，与条约无关，句意不合。"}, {"text": "段子", "is_correct": false, "explanation": "语域：「段子」是口语化的笑话，与正式的「写进……」语境不合，也不能指具有约束力的规范。"}], "explanations": {"国内法": "正确：句中指政府把条约写进了本国的法律，即国内法。", "日记": "语义：条约不会写进个人日记，写进的应是具有法律效力的规范，句意不合。", "菜谱": "语义：菜谱记录烹饪方法，与条约无关，句意不合。", "段子": "语域：「段子」是口语化的笑话，与正式的「写进……」语境不合，也不能指具有约束力的规范。"}, "sentence_index": 6, "correct_answer": "国内法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作家写了一部国内法。", "explanation": "这里应该用〈小说〉。作家写的是小说等文学作品，国内法是法律，不能由作家写成。"}, {"text": "导演拍了一部国内法。", "explanation": "这里应该用〈电影〉。导演拍的是电影，国内法是法律规范，不能拍成影片。"}, {"text": "乐团演奏了一部国内法。", "explanation": "这里应该用〈交响乐〉。乐团演奏的是交响乐，国内法是法律规范，不能演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个国内法需要相互协调。", "corrected_sentence": "两部国内法需要相互协调。", "error_description": "错误：量词用错了。「国内法」是法律，量词应用「部」，「个」用于个体事物，应说「两部国内法」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府依法制造了国内法。", "corrected_sentence": "政府依法制定了国内法。", "error_description": "错误：动词搭配错了。制定法律要用「制定」，「制造」用于产品等具体的东西，应说「制定国内法」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13220, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
