INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13224, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "禁止使用一次性塑料制品的政策或行动。", "primary_collocate": null, "pronunciation": "jìn sù", "ipa": "tɕin˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "例如，东南亚某国通过国家环境战略引入全面禁塑时间表，分阶段禁止聚乙烯薄膜与塑料袋流通，并建立地方级执法机制监督商业场所合规情况。", "target_word": "禁塑", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个城市的禁塑已经开始了。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "禁塑让超市不再免费送塑料袋。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人支持禁塑，因为塑料污染很严重。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府公布了新的禁塑政策。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "禁塑以后，市场里的塑料袋少多了。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲过禁塑的好处。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "禁塑对保护海洋有很大帮助。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一篇关于禁塑的文章。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "禁塑让商店老板多花了不少钱买纸袋。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "禁塑令", "label": "复合"}], "register": "正式", "sense_fingerprint": "禁止一次性塑料制品的政策或行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4207cc0a-4bb8-4fbd-9cd2-7d60f346daa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13224, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "禁塑", "is_correct": true, "explanation": "正确。禁塑：禁止使用一次性塑料制品的政策或行动。"}, {"text": "近似", "is_correct": false, "explanation": "jìn sì（近似）与 jìn sù（禁塑）韵母不同（i 与 u），近似的意思是接近、相似。"}, {"text": "尽数", "is_correct": false, "explanation": "shù 与 sù 声母不同（sh 与 s），尽数的意思是全部、所有。"}, {"text": "竞速", "is_correct": false, "explanation": "jìng 与 jìn 韵尾不同（ng 与 n），竞速的意思是比赛速度。"}, {"text": "进驻", "is_correct": false, "explanation": "zhù 与 sù 声母不同（zh 与 s），进驻的意思是进入并驻扎。"}], "explanations": {"禁塑": "正确。禁塑：禁止使用一次性塑料制品的政策或行动。", "近似": "jìn sì（近似）与 jìn sù（禁塑）韵母不同（i 与 u），近似的意思是接近、相似。", "尽数": "shù 与 sù 声母不同（sh 与 s），尽数的意思是全部、所有。", "竞速": "jìng 与 jìn 韵尾不同（ng 与 n），竞速的意思是比赛速度。", "进驻": "zhù 与 sù 声母不同（zh 与 s），进驻的意思是进入并驻扎。"}, "sentence_index": null, "correct_answer": "禁塑"}, "level_3": {"options": [{"text": "禁塑", "is_correct": true, "explanation": "正确。“全面禁塑时间表”指分阶段禁止一次性塑料制品的政策安排。"}, {"text": "禁烟", "is_correct": false, "explanation": "语义：禁烟指禁止吸烟，与句中“禁止聚乙烯薄膜与塑料袋流通”的内容不符。"}, {"text": "禁渔", "is_correct": false, "explanation": "语义：禁渔指禁止捕鱼，与句中塑料制品的管控内容不符。"}, {"text": "禁枪", "is_correct": false, "explanation": "搭配：“禁枪”针对枪支管制，不能与“聚乙烯薄膜与塑料袋”所指的管控对象搭配。"}], "explanations": {"禁塑": "正确。“全面禁塑时间表”指分阶段禁止一次性塑料制品的政策安排。", "禁烟": "语义：禁烟指禁止吸烟，与句中“禁止聚乙烯薄膜与塑料袋流通”的内容不符。", "禁渔": "语义：禁渔指禁止捕鱼，与句中塑料制品的管控内容不符。", "禁枪": "搭配：“禁枪”针对枪支管制，不能与“聚乙烯薄膜与塑料袋”所指的管控对象搭配。"}, "sentence_index": 0, "correct_answer": "禁塑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府公布了一只禁塑，要求超市停止供应塑料袋。", "explanation": "这里应该用〈项〉。禁塑作政策名词时量词用“项”，“只”用于动物或单个物件，不用于政策。"}, {"text": "政府没有禁止使用塑料袋，而是推行禁塑，要求超市收费。", "explanation": "这里应该用〈限塑〉。限塑指限制用量、仍允许使用并收费；禁塑指禁止使用，与“没有禁止使用塑料袋”自相矛盾。"}, {"text": "那个城市通过了一把禁塑，居民都很支持。", "explanation": "这里应该用〈项〉。“把”用于有柄的物件，不用于政策；禁塑作名词时量词用“项”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁塑", "is_correct": true, "explanation": "正确。禁塑指禁止一次性塑料制品的政策，可以讲它的好处。"}, {"text": "禁忌", "is_correct": false, "explanation": "语义：禁忌指忌讳或不许做的事，不能说“禁忌的好处”。"}, {"text": "禁区", "is_correct": false, "explanation": "搭配：“禁区”指不许进入的地方，不与“好处”搭配。"}, {"text": "禁地", "is_correct": false, "explanation": "语义：禁地指不许进入的场所，“禁地的好处”说不通。"}], "explanations": {"禁塑": "正确。禁塑指禁止一次性塑料制品的政策，可以讲它的好处。", "禁忌": "语义：禁忌指忌讳或不许做的事，不能说“禁忌的好处”。", "禁区": "搭配：“禁区”指不许进入的地方，不与“好处”搭配。", "禁地": "语义：禁地指不许进入的场所，“禁地的好处”说不通。"}, "sentence_index": 6, "correct_answer": "禁塑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市为了禁塑，专门大量进购了塑料袋。", "explanation": "句意矛盾：为了禁塑却大量进购塑料袋，做法与目的相反。禁塑指禁止使用一次性塑料制品。"}, {"text": "这种药物在医院被禁塑。", "explanation": "这里应该用〈禁用〉。禁用指不许使用某种物品或药品；禁塑只指不让人用塑料袋，不能用于药品。"}, {"text": "这款饮料因含糖超标已经禁塑。", "explanation": "这里应该用〈禁售〉。禁售指不许销售；禁塑只指不让人用塑料袋或相关政策，不能用于饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省颁布了一只禁塑令。", "corrected_sentence": "这个省颁布了一项禁塑令。", "error_description": "量词错误：“禁塑令”是政令，应用量词“项”，错用“只”。“只”用于动物或成对物件中的单个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市地禁塑政策很有效。", "corrected_sentence": "这座城市的禁塑政策很有效。", "error_description": "结构助词错误：“禁塑政策”前的定语“这座城市”应用“的”连接，误用“地”（“地”标示副词性修饰语）。应写作“这座城市的禁塑政策很有效”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
