INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13226, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "指按一定顺序或阶段逐步进行，不是一次性完成。", "primary_collocate": null, "pronunciation": "fēn jiē duàn", "ipa": "fən˥ tɕjɛ˥ twan˥˩", "syllable_count": 3, "sentences": [{"text": "例如，东南亚某国通过国家环境战略引入全面禁塑时间表，分阶段禁止聚乙烯薄膜与塑料袋流通，并建立地方级执法机制监督商业场所合规情况。", "target_word": "分阶段", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这项工作要分阶段完成。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校分阶段开放了新的图书馆。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算分阶段提高工资。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路将分阶段修好，第一段先开通。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府分阶段取消了这些旧规定。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议病人分阶段增加运动量。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的政策会分阶段实行。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂分阶段搬到了新地方。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划分阶段进行，今年先做第一步。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "按阶段逐步推进，不一次完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4207cc0a-4bb8-4fbd-9cd2-7d60f346daa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分阶段", "is_correct": true, "explanation": "分阶段：副词，表示按步骤逐步进行，与句中“全面禁塑时间表”的安排相符。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上执行，与“时间表”中分步禁止的安排相悖。"}, {"text": "一次性", "is_correct": false, "explanation": "语义：“一次性”表示一下子全部完成，与“分阶段”的逐步安排相反，也与“时间表”的先后步骤相悖。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上执行，与“时间表”中分阶段禁止的安排相悖。"}], "explanations": {"分阶段": "分阶段：副词，表示按步骤逐步进行，与句中“全面禁塑时间表”的安排相符。", "立即": "语义：“立即”表示马上执行，与“时间表”中分步禁止的安排相悖。", "一次性": "语义：“一次性”表示一下子全部完成，与“分阶段”的逐步安排相反，也与“时间表”的先后步骤相悖。", "立刻": "语义：“立刻”表示马上执行，与“时间表”中分阶段禁止的安排相悖。"}, "sentence_index": 0, "correct_answer": "分阶段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他分阶段一口气跑完了马拉松。", "explanation": "这里应该用〈一口气〉。分阶段指分步进行，一口气跑完是连续完成，不能用“分阶段”。"}, {"text": "他分阶段打碎了那个杯子。", "explanation": "这里不能用“分阶段”。打碎杯子是一瞬间完成的动作，没有分步进行的过程，“分阶段”指按步骤逐步做事。"}, {"text": "他分阶段按了一下开关。", "explanation": "这里应该用〈一次〉。分阶段指按步骤逐步进行，按一下开关是一次完成的动作，两者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分阶段", "is_correct": true, "explanation": "分阶段：副词，表示逐步增加，与医生建议循序渐进的安排相符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示出乎意料地发生，与医生建议循序渐进增加运动量的意思相悖。"}, {"text": "一下子", "is_correct": false, "explanation": "语义：“一下子”表示一次性完成，与医生建议逐步增加运动量相悖。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”表示过去的经历，而句中是对今后的建议，不能用“曾经”。"}], "explanations": {"分阶段": "分阶段：副词，表示逐步增加，与医生建议循序渐进的安排相符。", "突然": "语义：“突然”表示出乎意料地发生，与医生建议循序渐进增加运动量的意思相悖。", "一下子": "语义：“一下子”表示一次性完成，与医生建议逐步增加运动量相悖。", "曾经": "体貌：“曾经”表示过去的经历，而句中是对今后的建议，不能用“曾经”。"}, "sentence_index": 6, "correct_answer": "分阶段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们分阶段同时出发了。", "explanation": "这里应该用〈一齐〉。分阶段指先后分步进行，一齐出发是同一时间行动，不能用“分阶段”。"}, {"text": "他分阶段突然跳了起来。", "explanation": "这里应该用〈一下子〉。分阶段指分步进行，跳起来是瞬间完成的动作，不能用“分阶段”。"}, {"text": "这些书分阶段全部一次读完了。", "explanation": "这里应该用〈一口气〉。分阶段指分步进行，一口气读完是一次完成，不能用“分阶段”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们很分阶段搬进了新房子。", "corrected_sentence": "我们分阶段搬进了新房子。", "error_description": "程度副词错误：“分阶段”是表示步骤方式的副词，不能被“很”修饰，应去掉“很”，写作“我们分阶段搬进了新房子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的分阶段修好了操场。", "corrected_sentence": "学校分阶段修好了操场。", "error_description": "错误：“分阶段”前误加了“的”。正确：“分阶段”直接作状语，放在动词“修好”之前，写作“学校分阶段修好了操场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
