INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由乙烯聚合而成的高分子化合物，常用于制造塑料薄膜、容器等。", "primary_collocate": null, "pronunciation": "jù yǐ xī", "ipa": "tɕy˥˩ i˨˩˦ ɕi˥", "syllable_count": 3, "sentences": [{"text": "例如，东南亚某国通过国家环境战略引入全面禁塑时间表，分阶段禁止聚乙烯薄膜与塑料袋流通，并建立地方级执法机制监督商业场所合规情况。", "target_word": "聚乙烯", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "聚乙烯很轻，常用来做塑料袋。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂用聚乙烯生产塑料瓶。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乙烯是一种常见的塑料，不容易坏。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把聚乙烯加热，再做成薄膜。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水桶是聚乙烯做的，又轻又结实。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学课上，老师讲了聚乙烯是怎么做出来的。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乙烯用完以后，可以回收再用。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的很多食品袋都是聚乙烯做的。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乙烯不怕水，所以常做雨衣和水管。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高密度聚乙烯", "label": "复合"}, {"form": "聚乙烯薄膜", "label": "复合"}], "register": "中性", "sense_fingerprint": "乙烯聚合成的高分子塑料原料，用于做薄膜、袋子、容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4207cc0a-4bb8-4fbd-9cd2-7d60f346daa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚乙烯", "is_correct": true, "explanation": "聚乙烯：名词，作定语修饰“薄膜”，指这种塑料材料，与句中禁止流通的塑料制品相符。"}, {"text": "棉布", "is_correct": false, "explanation": "语义：棉布不是塑料，“棉布薄膜”与句中“塑料袋”所指的材料不符。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁不能制成薄膜，与句中“塑料袋”的语境不符。"}, {"text": "木材", "is_correct": false, "explanation": "搭配：薄膜通常由塑料等高分子材料制成，不说“木材薄膜”。"}], "explanations": {"聚乙烯": "聚乙烯：名词，作定语修饰“薄膜”，指这种塑料材料，与句中禁止流通的塑料制品相符。", "棉布": "语义：棉布不是塑料，“棉布薄膜”与句中“塑料袋”所指的材料不符。", "钢铁": "语义：钢铁不能制成薄膜，与句中“塑料袋”的语境不符。", "木材": "搭配：薄膜通常由塑料等高分子材料制成，不说“木材薄膜”。"}, "sentence_index": 0, "correct_answer": "聚乙烯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只聚乙烯。", "explanation": "这里应该用〈块〉。聚乙烯是材料，不用“只”计量，“只”一般用于动物或个体物品。"}, {"text": "妈妈把聚乙烯当成面粉，做了一锅面条。", "explanation": "聚乙烯是塑料原料，不能食用，这里不能把它当作食材使用。"}, {"text": "他每天都给聚乙烯浇水，希望它快点长大。", "explanation": "聚乙烯是塑料，不是植物，不能像植物一样浇水生长，这个词不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚乙烯", "is_correct": true, "explanation": "聚乙烯：名词，作“讲了”的宾语，是化学课上讲的人工合成材料，与“做出来”相符。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子是天然矿物，不是人工做出来的，与化学课讲人工合成的语境不符。"}, {"text": "铁矿", "is_correct": false, "explanation": "语义：铁矿是从地下开采的，不是做出来的，与句中“做出来”不符。"}, {"text": "春天", "is_correct": false, "explanation": "搭配：“做出来”的对象一般是人造的东西，不说“春天是怎么做出来的”。"}], "explanations": {"聚乙烯": "聚乙烯：名词，作“讲了”的宾语，是化学课上讲的人工合成材料，与“做出来”相符。", "沙子": "语义：沙子是天然矿物，不是人工做出来的，与化学课讲人工合成的语境不符。", "铁矿": "语义：铁矿是从地下开采的，不是做出来的，与句中“做出来”不符。", "春天": "搭配：“做出来”的对象一般是人造的东西，不说“春天是怎么做出来的”。"}, "sentence_index": 6, "correct_answer": "聚乙烯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们下午在聚乙烯见面吧。", "explanation": "聚乙烯是材料，不是场所，不能用作见面的地点，这个词不这么用。"}, {"text": "这位聚乙烯很会唱歌。", "explanation": "聚乙烯是物质，不能用来指人，这里的用法不对。"}, {"text": "他把这张桌子送给了聚乙烯。", "explanation": "“送给”的对象应是人，聚乙烯是材料，不能作受赠对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂用三个聚乙烯做了三个水桶。", "corrected_sentence": "工厂用聚乙烯做了三个水桶。", "error_description": "错误：“聚乙烯”是材料，不能用“个”计量，前面不该加“三个”。正确：直接说“工厂用聚乙烯做了三个水桶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种袋子是被聚乙烯做的，很轻。", "corrected_sentence": "这种袋子是用聚乙烯做的，很轻。", "error_description": "错误：用“被”引出做材料的“聚乙烯”不自然。正确：材料应用“用”引出，写作“这种袋子是用聚乙烯做的，很轻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
