INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种很薄的膜状材料，比如塑料薄膜。", "primary_collocate": null, "pronunciation": "bó mó", "ipa": "po˧˥ mo˧˥", "syllable_count": 2, "sentences": [{"text": "例如，东南亚某国通过国家环境战略引入全面禁塑时间表，分阶段禁止聚乙烯薄膜与塑料袋流通，并建立地方级执法机制监督商业场所合规情况。", "target_word": "薄膜", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民在地里盖了一层薄膜。", "target_word": "薄膜", "complexity_tier": "T3", "furigana": "bó mó", "sentence_source": "generated"}, {"text": "这种薄膜很薄，可以包食物。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把薄膜铺在大棚上。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕上贴着一层薄膜。", "target_word": "薄膜", "complexity_tier": "T3", "furigana": "bó mó", "sentence_source": "generated"}, {"text": "这家工厂每天生产很多薄膜。", "target_word": "薄膜", "complexity_tier": "T3", "furigana": "bó mó", "sentence_source": "generated"}, {"text": "薄膜太薄了，一拉就破。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买来的新手机屏幕上还有一张薄膜。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天天气冷，农民用薄膜保护小苗。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用薄膜把照片包好，免得弄湿。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层薄膜", "label": "量词"}, {"form": "一张薄膜", "label": "量词"}, {"form": "塑料薄膜", "label": "复合"}], "register": "中性", "sense_fingerprint": "很薄的膜状材料，如塑料薄膜，用于包装、覆盖、保护", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4207cc0a-4bb8-4fbd-9cd2-7d60f346daa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "薄膜", "is_correct": true, "explanation": "正确：「聚乙烯薄膜」指塑料薄膜，符合句意。"}, {"text": "纸箱", "is_correct": false, "explanation": "搭配：「聚乙烯」说明材料是塑料，修饰「纸箱」搭配不当，纸箱是纸制的。"}, {"text": "玻璃杯", "is_correct": false, "explanation": "语义：句中禁止流通的是塑料类包装材料，玻璃杯不是聚乙烯制品。"}, {"text": "木板", "is_correct": false, "explanation": "语义：木板不是聚乙烯制成的，与前面的材料限定相矛盾。"}], "explanations": {"薄膜": "正确：「聚乙烯薄膜」指塑料薄膜，符合句意。", "纸箱": "搭配：「聚乙烯」说明材料是塑料，修饰「纸箱」搭配不当，纸箱是纸制的。", "玻璃杯": "语义：句中禁止流通的是塑料类包装材料，玻璃杯不是聚乙烯制品。", "木板": "语义：木板不是聚乙烯制成的，与前面的材料限定相矛盾。"}, "sentence_index": 0, "correct_answer": "薄膜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块薄膜很硬，可以当桌面用。", "explanation": "这里应该用〈薄板〉。〈薄膜〉又薄又软，不能当桌面；〈薄板〉是较硬的薄片材料，才能用来做桌面。"}, {"text": "工人用薄膜砌墙。", "explanation": "这里应该用〈砖〉。薄膜又薄又软，不能像砖那样一块块码起来砌墙；砌墙要用砖、石等硬材料。"}, {"text": "乌龟的背上有一层薄膜，用来保护身体。", "explanation": "这里应该用〈硬壳〉。〈薄膜〉又薄又软，形成不了保护乌龟背部的硬壳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薄膜", "is_correct": true, "explanation": "正确：指薄而易破的塑料片，「一拉就破」与之相符。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁质地坚硬，不会薄到一拉就破。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头坚硬，不会因为一拉就破，与句意相反。"}, {"text": "铁丝", "is_correct": false, "explanation": "搭配：「薄」多形容片状物，不说「铁丝太薄」，应说「细」。"}], "explanations": {"薄膜": "正确：指薄而易破的塑料片，「一拉就破」与之相符。", "钢铁": "语义：钢铁质地坚硬，不会薄到一拉就破。", "石头": "语义：石头坚硬，不会因为一拉就破，与句意相反。", "铁丝": "搭配：「薄」多形容片状物，不说「铁丝太薄」，应说「细」。"}, "sentence_index": 6, "correct_answer": "薄膜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在茶里放了一片薄膜，喝起来很清凉。", "explanation": "这里应该用〈薄荷〉。〈薄荷〉是有清凉香味的植物，〈薄膜〉是没有香味的薄片材料，不能放进茶里。"}, {"text": "农民用薄膜焊了一个架子。", "explanation": "这里应该用〈钢管〉。焊接架子要用金属等可以熔接的材料，薄膜不能焊成架子。"}, {"text": "这扇窗户的薄膜被打碎了，风直往屋里灌。", "explanation": "这里应该用〈玻璃〉。〈薄膜〉柔软，不会被打碎；窗户碎了要说〈玻璃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在阳台上铺了一只薄膜，防止花盆弄脏地面。", "corrected_sentence": "妈妈在阳台上铺了一张薄膜，防止花盆弄脏地面。", "error_description": "量词错误：薄膜是片状材料，应说「一张薄膜」或「一层薄膜」，不能用「只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明把薄膜贴在窗户了。", "corrected_sentence": "小明把薄膜贴在窗户上了。", "error_description": "错误：漏掉方位词“上”。正确：表示贴在窗户表面要说“贴在窗户上”，应写作“小明把薄膜贴在窗户上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
