INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指人们进行活动、工作、学习等所在的特定地方或空间。", "primary_collocate": null, "pronunciation": "chǎng suǒ", "ipa": "ʈʂʰaŋ˨˩˦ suo̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "图书馆是学习的好场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园是老人锻炼的场所。", "target_word": "场所", "complexity_tier": "T3", "furigana": "chǎng suǒ", "sentence_source": "generated"}, {"text": "医院是病人需要安静的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个场所抽烟是不对的。", "target_word": "场所", "complexity_tier": "T3", "furigana": "chǎng suǒ", "sentence_source": "generated"}, {"text": "这个公园是孩子们玩的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂是工人工作的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场和电影院都是人多的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个场所晚上十点以后不让小孩进去。", "target_word": "场所", "complexity_tier": "T3", "furigana": "chǎng suǒ", "sentence_source": "generated"}, {"text": "学校是学生学习的主要场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进入这类场所，要先戴好口罩。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个场所", "label": "量词"}, {"form": "公共场所", "label": "复合"}, {"form": "娱乐场所", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们活动、工作、学习所在的特定地方或空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4207cc0a-4bb8-4fbd-9cd2-7d60f346daa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场所", "is_correct": true, "explanation": "正确：图书馆是学习活动的场所，符合句意。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是吃的东西，图书馆不是学习的饭菜。"}, {"text": "床", "is_correct": false, "explanation": "搭配：「好床」指睡觉用的，与「学习」搭配不当。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果与学习无关，不能说「学习的好水果」。"}], "explanations": {"场所": "正确：图书馆是学习活动的场所，符合句意。", "饭菜": "语义：饭菜是吃的东西，图书馆不是学习的饭菜。", "床": "搭配：「好床」指睡觉用的，与「学习」搭配不当。", "水果": "语义：水果与学习无关，不能说「学习的好水果」。"}, "sentence_index": 0, "correct_answer": "场所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事花了三个小时的场所才做完。", "explanation": "这里应该用〈时间〉。场所指人们活动的地方，不指时间长短；花了多长时间要用〈时间〉。"}, {"text": "他是我的场所，每天教我们数学。", "explanation": "这里应该用〈老师〉。场所指地方或空间，不能用来指人；教数学的人要说〈老师〉。"}, {"text": "这家饭店的场所很好吃。", "explanation": "这里应该用〈菜〉。场所是地方，不能吃；饭店里好吃的是〈菜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场所", "is_correct": true, "explanation": "正确：商场、电影院都是人多的公共场所，符合句意。"}, {"text": "时候", "is_correct": false, "explanation": "语义：商场和电影院是空间，不是时间，不能说「人多的时候」。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，商场和电影院不是玩具。"}, {"text": "公式", "is_correct": false, "explanation": "搭配：「人多」形容场所或场合，不能修饰公式。"}], "explanations": {"场所": "正确：商场、电影院都是人多的公共场所，符合句意。", "时候": "语义：商场和电影院是空间，不是时间，不能说「人多的时候」。", "玩具": "语义：玩具是物品，商场和电影院不是玩具。", "公式": "搭配：「人多」形容场所或场合，不能修饰公式。"}, "sentence_index": 6, "correct_answer": "场所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的场所很长，大家都读不完。", "explanation": "这里应该用〈篇幅〉。场所指人们活动的地方，不能用来形容文章的长短。"}, {"text": "他的场所很好听，大家都喜欢。", "explanation": "这里应该用〈声音〉。场所指地方，不能用来形容声音好听。"}, {"text": "他下班后回到了场所，好好休息。", "explanation": "这里应该用〈住处〉。场所指活动的地方，不指家或住的地方，下班回家要说〈住处〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一条安全的场所，孩子可以在这里玩。", "corrected_sentence": "这是一个安全的场所，孩子可以在这里玩。", "error_description": "量词错误：场所是地方，应说「一个场所」，不能用「条」，「条」用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把学生带了进这个场所。", "corrected_sentence": "老师把学生带进了这个场所。", "error_description": "补语与「了」位置错误：「进」是趋向补语，「了」应放在「带进」之后，应说「带进了这个场所」，不能说「带了进」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13233, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13233, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13233, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "替代品指能够代替原有物品或功能的其他物品。", "primary_collocate": null, "pronunciation": "tì dài pǐn", "ipa": "tʰi˥˩ taɪ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "此类监管实践虽面临执法资源不足与替代品成本高昂的挑战，但其政策导向清晰传递出对可持续消费模式的制度支持。", "target_word": "替代品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "糖太贵时，人们会买蜂蜜当替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料袋的替代品是纸袋和布袋。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药缺货了，医生推荐了一种替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母乳不足时，婴儿可以用配方奶作替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找不到原来的零件，只好买了替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料很难找到合适的替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木材价格上涨，竹子成了热门替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款电池的替代品价格便宜，质量也不错。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有真皮，只能用人造革做替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "替代品：用来代替原有物品或功能的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5df597c-7f63-48fe-bae5-e2a999fa4fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "替代品", "is_correct": true, "explanation": "正确。“替代品”指能代替原有物品的东西，可以与“成本高昂”搭配，句意通顺。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不是可以计算成本的事物，“春天成本高昂”句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有成本，无法与“成本高昂”搭配。"}, {"text": "东西", "is_correct": false, "explanation": "语域：“东西”是口语说法，与这句的书面语体不一致。"}], "explanations": {"替代品": "正确。“替代品”指能代替原有物品的东西，可以与“成本高昂”搭配，句意通顺。", "春天": "语义：“春天”是季节，不是可以计算成本的事物，“春天成本高昂”句意不通。", "天气": "语义：天气没有成本，无法与“成本高昂”搭配。", "东西": "语域：“东西”是口语说法，与这句的书面语体不一致。"}, "sentence_index": 0, "correct_answer": "替代品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次聚会的替代品是我的哥哥。", "explanation": "这里应该用〈代表〉。替代品指可代替物品或功能的东西，不用来指人；表示出席聚会的人应用〈代表〉。"}, {"text": "这场戏由替代品拍摄，主角没有出镜。", "explanation": "这里应该用〈替身〉。替身指替演员拍摄危险或难拍镜头的人，替代品指代替物品或功能的东西，不用来指拍摄镜头的人。"}, {"text": "他是我们班的替代品，负责管理纪律。", "explanation": "这里应该用〈班长〉。班长指担任班级管理工作的学生，替代品指可代替物品或功能的东西，不用来指负责管理的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "替代品", "is_correct": true, "explanation": "正确。“合适的替代品”指适合代替这种材料的东西，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以“找到合适”或“替代”的物品，与句意不符。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作”指职业或任务，材料不能找工作，“这种材料很难找到合适的工作”句意不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是特定的自然景观，无法被当作“合适的”替代物来寻找。"}], "explanations": {"替代品": "正确。“合适的替代品”指适合代替这种材料的东西，句意通顺。", "空气": "语义：空气不是可以“找到合适”或“替代”的物品，与句意不符。", "工作": "语义：“工作”指职业或任务，材料不能找工作，“这种材料很难找到合适的工作”句意不通。", "大海": "语义：大海是特定的自然景观，无法被当作“合适的”替代物来寻找。"}, "sentence_index": 6, "correct_answer": "替代品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的心情是今天的替代品。", "explanation": "这里应该用〈转移〉。替代品指可代替物品或功能的具体东西，心情不能充当一天的替代品，表示情绪转换应用〈转移〉。"}, {"text": "这次旅行的替代品很详细。", "explanation": "这里应该用〈计划〉。替代品指可代替某物或某功能的东西，不用来形容旅行的安排是否详细。"}, {"text": "这个节日的替代品是我的妈妈。", "explanation": "这里应该用〈陪同〉。替代品指可代替物品或功能的东西，不能用来指一起过节的家人，表示陪伴应用〈陪同〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一座替代品。", "corrected_sentence": "我买了一个替代品。", "error_description": "量词错误：“座”多用于山、桥、楼等大型固定之物，替代品应用“个”或“种”，“一座替代品”应改为“一个替代品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一只便宜的替代品。", "corrected_sentence": "我想买一个便宜的替代品。", "error_description": "量词错误：「只」多用于动物或成对的东西，替代品应用「个」或「种」，「一只便宜的替代品」应改为「一个便宜的替代品」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13234, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低廉", "is_correct": true, "explanation": "正确。“低廉”与“高昂”相对，都指价格或费用的高低。"}, {"text": "简单", "is_correct": false, "explanation": "无关：“简单”形容不复杂，与“高昂”的价格义及其它义项都不构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容清晰明白，与“高昂”的价格意义没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“高昂”的价格意义没有反义关系。"}], "correct_answer": "低廉", "explanations": {"低廉": "正确。“低廉”与“高昂”相对，都指价格或费用的高低。", "简单": "无关：“简单”形容不复杂，与“高昂”的价格义及其它义项都不构成反义。", "清楚": "“清楚”形容清晰明白，与“高昂”的价格意义没有反义关系。", "迅速": "“迅速”形容速度快，与“高昂”的价格意义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13234, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低廉", "is_correct": true, "explanation": "正确。“低廉”与“高昂”相对，都指价格或费用的高低。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线充足或清晰，与“高昂”的价格义及其它义项都不构成反义。"}, {"text": "辽阔", "is_correct": false, "explanation": "无关：“辽阔”形容地域广大，与“高昂”的价格意义没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "无关：“温和”形容性情或气候平缓，与“高昂”的价格义及其它义项都不构成反义。"}], "correct_answer": "低廉", "explanations": {"低廉": "正确。“低廉”与“高昂”相对，都指价格或费用的高低。", "明亮": "无关：“明亮”形容光线充足或清晰，与“高昂”的价格义及其它义项都不构成反义。", "辽阔": "无关：“辽阔”形容地域广大，与“高昂”的价格意义没有反义关系。", "温和": "无关：“温和”形容性情或气候平缓，与“高昂”的价格义及其它义项都不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13234, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容价格、费用或成本很贵。", "primary_collocate": null, "pronunciation": "gāo áng", "ipa": "kɑʊ˥ ɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "此类监管实践虽面临执法资源不足与替代品成本高昂的挑战，但其政策导向清晰传递出对可持续消费模式的制度支持。", "target_word": "高昂", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "高昂", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在这个景区，酒店的价格非常高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病住院，医药费十分高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学费高昂，很多家庭负担不起。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房的费用高昂，年轻人只好合租。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了买这块地，公司付出了高昂的代价。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国外留学的费用高昂，他选择在国内读书。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高昂的房价让很多人买不起房子。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次手术的费用高昂，家人借了不少钱。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "价格高昂", "label": "复合"}, {"form": "高昂的代价", "label": "复合"}], "register": "中性", "sense_fingerprint": "价格、费用、成本很贵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ab76373-a806-4838-933e-5ef3747780ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高昂", "is_correct": true, "explanation": "正确。“成本高昂”表示花费很大，与“替代品成本”和“挑战”的语境相符。"}, {"text": "高明", "is_correct": false, "explanation": "语义：“高明”形容技艺或见识出众，不能修饰“成本”。"}, {"text": "高速", "is_correct": false, "explanation": "搭配：“高速”说速度，不能说成本高速。"}, {"text": "高尚", "is_correct": false, "explanation": "语义：“高尚”形容品格，与“成本”和“挑战”的语境不符。"}], "explanations": {"高昂": "正确。“成本高昂”表示花费很大，与“替代品成本”和“挑战”的语境相符。", "高明": "语义：“高明”形容技艺或见识出众，不能修饰“成本”。", "高速": "搭配：“高速”说速度，不能说成本高速。", "高尚": "语义：“高尚”形容品格，与“成本”和“挑战”的语境不符。"}, "sentence_index": 0, "correct_answer": "高昂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树长得很高昂。", "explanation": "这里应该用〈高大〉。高昂形容情绪、声音或价格，形容树木的身形要用“高大”。"}, {"text": "他的棋艺很高昂，很少有人能赢他。", "explanation": "这里应该用〈高明〉。高昂形容情绪、声音或价格，形容棋艺的水平要用“高明”。"}, {"text": "这台机器工作很高昂。", "explanation": "这里应该用〈高效〉。高昂形容情绪、声音或价格，形容工作的效率要用“高效”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高昂", "is_correct": true, "explanation": "正确。“付出高昂的代价”指付出的代价很大，与“为了买这块地”的语境相符。"}, {"text": "高亢", "is_correct": false, "explanation": "语义：“高亢”多形容声音或情绪，不能修饰“代价”。"}, {"text": "高深", "is_correct": false, "explanation": "语义：“高深”形容学问或道理很深，不能说“代价高深”。"}, {"text": "高超", "is_correct": false, "explanation": "搭配：“高超”修饰技艺，不能修饰“代价”。"}], "explanations": {"高昂": "正确。“付出高昂的代价”指付出的代价很大，与“为了买这块地”的语境相符。", "高亢": "语义：“高亢”多形容声音或情绪，不能修饰“代价”。", "高深": "语义：“高深”形容学问或道理很深，不能说“代价高深”。", "高超": "搭配：“高超”修饰技艺，不能修饰“代价”。"}, "sentence_index": 6, "correct_answer": "高昂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的气温十分高昂。", "explanation": "这里应该用〈高〉。高昂用于价格、费用，气温要用“高”来说。"}, {"text": "上班的高昂时段，地铁很挤。", "explanation": "这里应该用〈高峰〉。高昂不能用来形容人流最多的时段，这里要用“高峰”。"}, {"text": "这次比赛的参赛人数很高昂，场面很热闹。", "explanation": "这里应该用〈众多〉。高昂不能用来形容人数的多少，这里要用“众多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司为了研发新产品付出了高昂地代价。", "corrected_sentence": "这家公司为了研发新产品付出了高昂的代价。", "error_description": "结构助词误用：“代价”是名词，修饰它的形容词要用“的”，“地”只用于修饰动词，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅游的费用高昂的让人吃惊。", "corrected_sentence": "这次旅游的费用高昂得让人吃惊。", "error_description": "补语标记误用：形容词后表示程度的补语要用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
