INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13238, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指已经具有或存在的事物。", "primary_collocate": null, "pronunciation": "yǐ yǒu", "ipa": "i˨˩˦ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "已有的制度不太合理，公司决定修改。", "target_word": "已有", "complexity_tier": "T3", "furigana": "yǐ yǒu de zhì dù bù tài hé lǐ gōng sī jué dìng xiū gǎi", "sentence_source": "generated"}, {"text": "已有的电线老化了，需要全部更换。", "target_word": "已有", "complexity_tier": "T3", "furigana": "yǐ yǒu de diàn xiàn lǎo huà le xū yào quán bù gēng huàn", "sentence_source": "generated"}, {"text": "我们已有的资料不够，还要再查。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "已有的足球队不够用，学校想再组一支。", "target_word": "已有", "complexity_tier": "T3", "furigana": "yǐ yǒu de zú qiú duì bù gòu yòng xué xiào xiǎng zài zǔ yì zhī", "sentence_source": "generated"}, {"text": "他很满意已有的工作，不想换了。", "target_word": "已有", "complexity_tier": "T3", "furigana": "tā hěn mǎn yì yǐ yǒu de gōng zuò bù xiǎng huàn le", "sentence_source": "generated"}, {"text": "已有的办法都试过了，问题还在。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很照顾已有的两个孩子，现在又想养一只猫。", "target_word": "已有", "complexity_tier": "T3", "furigana": "tā hěn zhào gù yǐ yǒu de liǎng gè hái zi xiàn zài yòu xiǎng yǎng yì zhī māo", "sentence_source": "generated"}, {"text": "书架上已有的书够我看了，不用再买了。", "target_word": "已有", "complexity_tier": "T3", "furigana": "shū jià shang yǐ yǒu de shū gòu wǒ kàn le bú yòng zài mǎi le", "sentence_source": "generated"}, {"text": "根据已有的数据，明年的销量会更高。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里已有的超市够用了，不需要再开了。", "target_word": "已有", "complexity_tier": "T3", "furigana": "xiǎo qū li yǐ yǒu de chāo shì gòu yòng le bù xū yào zài kāi le", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "已有：已经具有或存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5df597c-7f63-48fe-bae5-e2a999fa4fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "已有", "is_correct": true, "explanation": "正确。“已有的制度”指已经存在的制度，与后文“决定修改”相呼应。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是动作，不能修饰“制度”，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是动作，不能用来修饰“制度”。"}, {"text": "弄", "is_correct": false, "explanation": "语域：“弄”是口语说法，与这句的书面语体不一致。"}], "explanations": {"已有": "正确。“已有的制度”指已经存在的制度，与后文“决定修改”相呼应。", "吃": "语义：“吃”是动作，不能修饰“制度”，句意不通。", "游泳": "语义：“游泳”是动作，不能用来修饰“制度”。", "弄": "语域：“弄”是口语说法，与这句的书面语体不一致。"}, "sentence_index": 0, "correct_answer": "已有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的比赛已有很多观众到场。", "explanation": "这里应该用〈将有〉。“已有”指已经存在，明天的比赛尚未发生，不能用“已有”。"}, {"text": "下周的音乐会已有很多观众来了。", "explanation": "这里应该用〈将有〉。“已有”指已经存在，下周的音乐会还没有开始，不能说观众已经来了。"}, {"text": "后天的考试已有很多同学交了卷。", "explanation": "这里应该用〈将会〉。“已有”指已经存在，后天的考试还未举行，不能说同学已经交卷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已有", "is_correct": true, "explanation": "正确。“照顾已有的两个孩子”指照顾已经有的两个孩子，句意通顺。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”是动作，不能用来修饰“两个孩子”。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”指击打，“照顾打的两个孩子”意思不通，与句子不符。"}, {"text": "搞", "is_correct": false, "explanation": "语域：“搞”是口语说法，与这句的书面语体不一致。"}], "explanations": {"已有": "正确。“照顾已有的两个孩子”指照顾已经有的两个孩子，句意通顺。", "写": "语义：“写”是动作，不能用来修饰“两个孩子”。", "打": "语义：“打”指击打，“照顾打的两个孩子”意思不通，与句子不符。", "搞": "语域：“搞”是口语说法，与这句的书面语体不一致。"}, "sentence_index": 6, "correct_answer": "已有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下个月的展览已有很多人参观过了。", "explanation": "这里应该用〈将有〉。“已有”指已经存在，下个月的展览还未开始，不能说已有很多人参观过。"}, {"text": "这次会议已有很多人发过言了。", "explanation": "这里应该用〈将有〉。“已有”指已经存在，会议尚未举行，不能说已有很多人发过言了。"}, {"text": "明年的春节已有大家一起吃过年夜饭了。", "explanation": "这里应该用〈将要〉。“已有”指已经存在，明年的春节还没有到来，不能说大家已经吃过年夜饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书架上已有得很多书。", "corrected_sentence": "书架上已有很多书。", "error_description": "助词误用：“得”不能插在“已有”和宾语之间，“已有得很多书”应改为“已有很多书”，去掉多余的“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些没已有的书都很旧。", "corrected_sentence": "这些已有的书都很旧。", "error_description": "否定误用：“没”不能放在“已有”之前，“没已有”不成立，应删去“没”，改为“这些已有的书都很旧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13240, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13240, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "官方发布的禁止某种行为或事物的命令。", "primary_collocate": null, "pronunciation": "jìn lìng", "ipa": "tɕin⁵¹ liŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "值得注意的是，非洲大陆已有十余国实施不同程度的塑料袋禁令，部分国家甚至对违规生产或进口行为施以刑事处罚，反映出环境政策在资源约束型社会中的刚性取向。", "target_word": "禁令", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "联邦层面长期缺乏统一立法，但多个城市与州级行政区自主推行禁令，涵盖塑料吸管、外卖容器及零售包装等领域。", "target_word": "禁令", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "从全球趋势看，一次性塑料禁令已超越环境议题本身，演变为国家治理能力与国际形象的象征性场域。", "target_word": "禁令", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "全球趋势正从单一禁令转向系统治理，塑料污染的应对也因此成为检验现代国家制度韧性的重要试金石。", "target_word": "禁令", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "市政府发布了禁令，禁止在公园里放烟花。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项禁令从下个月一号开始生效。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府取消了对外卖塑料盒的禁令。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人不满意新的禁令。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育部门出台禁令，禁止校园内销售含糖饮料。", "target_word": "禁令", "complexity_tier": "T3", "furigana": "jiào yù bù mén chū tái jìn lìng jìn zhǐ xiào yuán nèi xiāo shòu hán táng yǐn liào", "sentence_source": "generated"}, {"text": "官方宣布，禁令明天起正式实施。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "项", "label": "量词"}], "register": "书面", "sense_fingerprint": "官方正式发布的禁止某种行为或事物的命令", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5df597c-7f63-48fe-bae5-e2a999fa4fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13240, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "禁令", "is_correct": true, "explanation": "禁令：官方发布的禁止某种行为或事物的命令，正确答案。"}, {"text": "信令", "is_correct": false, "explanation": "xìn lìng 与 jìn lìng 仅声母不同（x 与 j），韵母与声调相同，意思是信令（通信中的控制信号）。"}, {"text": "近零", "is_correct": false, "explanation": "líng（第二声）与 lìng（第四声）声调不同，意思是接近零。"}, {"text": "金领", "is_correct": false, "explanation": "jīn lǐng 两个音节的声调都与 jìn lìng 不同，意思是金领（高级白领）。"}], "explanations": {"禁令": "禁令：官方发布的禁止某种行为或事物的命令，正确答案。", "信令": "xìn lìng 与 jìn lìng 仅声母不同（x 与 j），韵母与声调相同，意思是信令（通信中的控制信号）。", "近零": "líng（第二声）与 lìng（第四声）声调不同，意思是接近零。", "金领": "jīn lǐng 两个音节的声调都与 jìn lìng 不同，意思是金领（高级白领）。"}, "sentence_index": null, "correct_answer": "禁令"}, "level_3": {"options": [{"text": "禁令", "is_correct": true, "explanation": "禁令：与“实施……禁令”和后文“刑事处罚”的强制语境相合，是正确答案。"}, {"text": "宣传", "is_correct": false, "explanation": "语义：“宣传”是宣扬推广，不是强制性的规定，与后文“刑事处罚”的强制语境不合。"}, {"text": "标志", "is_correct": false, "explanation": "搭配：“实施”后接规定或政策，不能说“实施……标志”。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“实施”不能接“包装”这类实物名词，塑料袋的包装不能被“实施”。"}], "explanations": {"禁令": "禁令：与“实施……禁令”和后文“刑事处罚”的强制语境相合，是正确答案。", "宣传": "语义：“宣传”是宣扬推广，不是强制性的规定，与后文“刑事处罚”的强制语境不合。", "标志": "搭配：“实施”后接规定或政策，不能说“实施……标志”。", "包装": "搭配：“实施”不能接“包装”这类实物名词，塑料袋的包装不能被“实施”。"}, "sentence_index": 0, "correct_answer": "禁令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府颁布了新的禁令，要求所有学校每周组织一次体育课。", "explanation": "这里应该用〈法令〉。禁令只表示禁止某种行为，不用于要求学校做某事这类强制性要求。"}, {"text": "学校发了一份禁令，通知明天全校放假。", "explanation": "这里应该用〈公告〉。禁令是禁止性命令，不用于发布放假这类一般性告知。"}, {"text": "老师下了禁令，让同学们安静地写作业。", "explanation": "这里应该用〈命令〉。禁令只表示禁止，不表示让人做某事，让人做某事要说命令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁令", "is_correct": true, "explanation": "禁令：与“取消”搭配，指撤销此前的禁止规定，是正确答案。"}, {"text": "习惯", "is_correct": false, "explanation": "搭配：“取消”的对象是规定、政策，不能说“取消……习惯”。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：“奖金”不是禁止性规定，与“对外卖塑料盒的”搭配不通，句意无法成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：外卖塑料盒的颜色不是政府可以取消的规定，句子意思不通。"}], "explanations": {"禁令": "禁令：与“取消”搭配，指撤销此前的禁止规定，是正确答案。", "习惯": "搭配：“取消”的对象是规定、政策，不能说“取消……习惯”。", "奖金": "语义：“奖金”不是禁止性规定，与“对外卖塑料盒的”搭配不通，句意无法成立。", "颜色": "语义：外卖塑料盒的颜色不是政府可以取消的规定，句子意思不通。"}, "sentence_index": 6, "correct_answer": "禁令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司发表了禁令，承认了之前的产品缺陷。", "explanation": "这里应该用〈声明〉。禁令是禁止性命令，不用于公开承认某事。"}, {"text": "商店贴出了禁令，打折三天。", "explanation": "这里应该用〈广告〉。禁令表示禁止，不用于宣传打折促销。"}, {"text": "学校新定了禁令，学生需要按时到校。", "explanation": "这里应该用〈规章〉。禁令只表示禁止某种行为，不用于要求学生按时到校这类一般规章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府发布了一只禁令，禁止在公园里放烟花。", "corrected_sentence": "政府发布了一项禁令，禁止在公园里放烟花。", "error_description": "量词错误：“禁令”的量词应为“项”（或“条”），“只”多用于动物，不能用于“禁令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府取消了一座针对外卖塑料盒的禁令。", "corrected_sentence": "政府取消了一项针对外卖塑料盒的禁令。", "error_description": "量词错误：「座」多用于山、桥、楼等大型固定之物，「禁令」应用「项」或「条」，「一座针对外卖塑料盒的禁令」应改为「一项针对外卖塑料盒的禁令」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13241, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合规", "is_correct": true, "explanation": "合规：符合规定，与“违规”意思相反，是正确答案。"}, {"text": "完成", "is_correct": false, "explanation": "与“违规”无反义关系：“完成”指做好某件事，与违反规定没有对立关系。"}, {"text": "参加", "is_correct": false, "explanation": "与“违规”无反义关系：“参加”指加入某项活动，不是违规行为的对立面。"}, {"text": "批准", "is_correct": false, "explanation": "与“违规”无反义关系：“批准”指准许，与违反规定不构成反义。"}], "correct_answer": "合规", "explanations": {"合规": "合规：符合规定，与“违规”意思相反，是正确答案。", "完成": "与“违规”无反义关系：“完成”指做好某件事，与违反规定没有对立关系。", "参加": "与“违规”无反义关系：“参加”指加入某项活动，不是违规行为的对立面。", "批准": "与“违规”无反义关系：“批准”指准许，与违反规定不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13241, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合规", "is_correct": true, "explanation": "合规：符合规定，与“违规”意思相反，是正确答案。"}, {"text": "发表", "is_correct": false, "explanation": "与“违规”无反义关系：“发表”指公开刊登或宣布，与违反规定没有对立关系。"}, {"text": "检查", "is_correct": false, "explanation": "与“违规”无反义关系：“检查”指查看是否有问题，本身不与违规构成反义。"}, {"text": "安排", "is_correct": false, "explanation": "与“违规”无反义关系：“安排”指事先筹划，与违反规定没有对立关系。"}], "correct_answer": "合规", "explanations": {"合规": "合规：符合规定，与“违规”意思相反，是正确答案。", "发表": "与“违规”无反义关系：“发表”指公开刊登或宣布，与违反规定没有对立关系。", "检查": "与“违规”无反义关系：“检查”指查看是否有问题，本身不与违规构成反义。", "安排": "与“违规”无反义关系：“安排”指事先筹划，与违反规定没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13241, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指违反规则、法律或约定，做了不被允许的事情。", "primary_collocate": null, "pronunciation": "wéi guī", "ipa": "uei³⁵ kuei⁵⁵", "syllable_count": 2, "sentences": [{"text": "值得注意的是，非洲大陆已有十余国实施不同程度的塑料袋禁令，部分国家甚至对违规生产或进口行为施以刑事处罚，反映出环境政策在资源约束型社会中的刚性取向。", "target_word": "违规", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他开车违规，警察让他停车。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中违规的球员要离开球场。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这里停车就是违规。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做违规了，不能再试。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有违规过。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时看手机算违规。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司规定很严，谁违规都要扣钱。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店违规使用过期的菜。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判说他踢球时违规了。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "违规了", "label": "体标"}, {"form": "违规过", "label": "体标"}, {"form": "违规行为", "label": "复合"}, {"form": "違規", "label": "繁体"}], "register": "中性", "sense_fingerprint": "违反规则、法律或约定而做不被允许的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5df597c-7f63-48fe-bae5-e2a999fa4fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13241, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违规", "is_correct": true, "explanation": "违规：违反规定，与“对违规生产或进口行为施以刑事处罚”的语境相合，是正确答案。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”指中止，“对停止生产或进口行为施以刑事处罚”与句子的处罚语境不符，句意不通。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”是准许，被批准的行为不会受到刑事处罚，与“施以刑事处罚”矛盾。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”后接活动、比赛等，不能说“举办生产或进口行为”。"}], "explanations": {"违规": "违规：违反规定，与“对违规生产或进口行为施以刑事处罚”的语境相合，是正确答案。", "停止": "语义：“停止”指中止，“对停止生产或进口行为施以刑事处罚”与句子的处罚语境不符，句意不通。", "批准": "语义：“批准”是准许，被批准的行为不会受到刑事处罚，与“施以刑事处罚”矛盾。", "举办": "搭配：“举办”后接活动、比赛等，不能说“举办生产或进口行为”。"}, "sentence_index": 0, "correct_answer": "违规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他按时还清了贷款，这是违规。", "explanation": "这里应该用〈守信〉。违规指违反规定或约定，不用于形容按时还款这类守约行为。"}, {"text": "他把捡到的钱包还给了失主，这已经算是违规了。", "explanation": "这里应该用〈诚实〉。违规指违反规定，不用于形容归还失物这类做法。"}, {"text": "这份报告的数字很违规，看起来不正常。", "explanation": "这里应该用〈反常〉。违规指违反规定，不用于表示数字异常。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "违规", "is_correct": true, "explanation": "违规：违反考试规定，与“考试时看手机算……”的判断相合，是正确答案。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“算”后接的是对行为的判定，不能说“算批改”，且“批改”是老师的工作。"}, {"text": "通过", "is_correct": false, "explanation": "语义：“通过”指合格或过关，“考试时看手机算通过”与常识相反，句意不通。"}, {"text": "监考", "is_correct": false, "explanation": "语义：“监考”指监督考试，本身不是违规行为，“看手机算监考”不成立。"}], "explanations": {"违规": "违规：违反考试规定，与“考试时看手机算……”的判断相合，是正确答案。", "批改": "搭配：“算”后接的是对行为的判定，不能说“算批改”，且“批改”是老师的工作。", "通过": "语义：“通过”指合格或过关，“考试时看手机算通过”与常识相反，句意不通。", "监考": "语义：“监考”指监督考试，本身不是违规行为，“看手机算监考”不成立。"}, "sentence_index": 6, "correct_answer": "违规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早起跑步，身体很好，这是违规。", "explanation": "这里应该用〈锻炼〉。违规指违反规定，不用于形容早起跑步这类锻炼身体的行为。"}, {"text": "这家商店的服务态度很违规，大家都很满意。", "explanation": "这里应该用〈热情〉。违规指违反规定，不用于形容服务态度好。"}, {"text": "这把椅子很违规，坐起来很舒服。", "explanation": "这里应该用〈舒适〉。违规指违反规定或约定，不用于形容椅子坐起来舒服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在考场上被违规，被监考老师发现了。", "corrected_sentence": "他在考场上违规，被监考老师发现了。", "error_description": "被字句错误：“违规”是不及物动词，不能用“被”构成被动句，应说“他在考场上违规”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在比赛中违规着，被裁判罚下场了。", "corrected_sentence": "他在比赛中违规了，被裁判罚下场了。", "error_description": "体标误用：“违规”表示一次性的动作，不能与表持续的“着”搭配，“违规着”应改为“违规了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
