INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13242, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某人或某物施加某种行为或影响。", "primary_collocate": null, "pronunciation": "shī yǐ", "ipa": "ʂʅ⁵⁵ i²¹⁴", "syllable_count": 2, "sentences": [{"text": "值得注意的是，非洲大陆已有十余国实施不同程度的塑料袋禁令，部分国家甚至对违规生产或进口行为施以刑事处罚，反映出环境政策在资源约束型社会中的刚性取向。", "target_word": "施以", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "邻居们对他施以援手。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官对小偷施以重罚。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生对病人施以治疗。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对犯错的学生施以惩戒。", "target_word": "施以", "complexity_tier": "T3", "furigana": "lǎo shī duì fàn cuò de xué shēng shī yǐ chéng jiè", "sentence_source": "generated"}, {"text": "国家对违法的公司施以制裁。", "target_word": "施以", "complexity_tier": "T3", "furigana": "guó jiā duì wéi fǎ de gōng sī shī yǐ zhì cái", "sentence_source": "generated"}, {"text": "地震后，很多人向灾区施以援手。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人对孤儿施以关爱，像亲人一样。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对打架的学生施以教育。", "target_word": "施以", "complexity_tier": "T3", "furigana": "xué xiào duì dǎ jià de xué shēng shī yǐ jiào yù", "sentence_source": "generated"}, {"text": "他对每个朋友都施以善意。", "target_word": "施以", "complexity_tier": "T3", "furigana": "tā duì měi gè péng you dōu shī yǐ shàn yì", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "对某人或某物施加某种行为或影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5df597c-7f63-48fe-bae5-e2a999fa4fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
